window.TRICKS={"cardio:heart":[{"t":"ترتيب الصمامات بطريق الدم: T-P-M-A","m":"تبّولة ← بطاطا ← مجدّرة ← أرز: نفس ترتيب الصمامات اللي بيقطعها الدم","d":["ت = Valve tricuspide (الصمام ثلاثي الشرف): بين الأذين الأيمن والبطين الأيمن","ب = Valve pulmonaire (الصمام الرئوي): من البطين الأيمن للشريان الرئوي","م = Valve mitrale (الصمام التاجي): بين الأذين الأيسر والبطين الأيسر","أ = Valve aortique (الصمام الأبهري): من البطين الأيسر للـ Aorte (الأبهر)","يعني اليمين (Tri + Pulmonaire) بالأول، والشمال (Mitrale + Aortique) بعد الرية"],"fr":{"t":"Ordre des valves : T-P-M-A","m":"Tu Peux Manger Avant : Tricuspide, Pulmonaire, Mitrale, Aortique","d":["T = valve Tricuspide : oreillette droite vers ventricule droit","P = valve Pulmonaire : ventricule droit vers artère pulmonaire","M = valve Mitrale : oreillette gauche vers ventricule gauche","A = valve Aortique : ventricule gauche vers aorte","Le cœur droit d'abord (T, P), puis le cœur gauche après les poumons (M, A)"]}},{"t":"الطبقات التلاتة من برّا لجوّا","m":"القلب متل بيت: السور برّا، الحيطان بالنص، والدهان جوّا مع البواب","d":["السور = Péricarde (التامور): الكيس برّا ← التهابو péricardite","الحيطان = Myocarde (عضلة القلب): بالنص ← التهابها myocardite","الدهان والبواب = Endocarde (البطانة) مع الصمامات: جوّا ← التهابها endocardite"],"fr":{"t":"Les 3 tuniques, de dehors en dedans","m":"Péri = autour, Myo = muscle, Endo = dedans : P-M-E, du dehors vers le dedans","d":["Péricarde : le sac autour du cœur, son inflammation = péricardite","Myocarde : le muscle au milieu, son inflammation = myocardite","Endocarde : la couche interne avec les valves, son inflammation = endocardite"]}},{"t":"Débit cardiaque: معادلة بإيدين","m":"الـ Débit = نبض × ضربة: إذا وحدة ضعفت، الدماغ والرية والأطراف بيحسّوا","d":["Débit cardiaque (الناتج القلبي) = Fréquence cardiaque (عدد النبضات) × Volume d'éjection (حجم الضربة)","أي مرض بيضعّف واحد منهن بيأثّر على الدماغ والرية والأطراف، وهيدا بيفسّر العوارض"],"fr":{"t":"Débit cardiaque : une multiplication","m":"DC = FC × VES : si l'un baisse, cerveau, poumons et membres le sentent","d":["Débit cardiaque = Fréquence cardiaque × Volume d'éjection","Toute maladie qui affaiblit l'un des deux touche le cerveau, les poumons et les membres : c'est ce qui explique les symptômes"]}}],"cardio:infarctus":[{"t":"كيف بتصير الجلطة: دهنة، شقّة، جلطة، موتة","m":"دهنة ← شقّة ← جلطة ← موتة: ٤ خطوات من الـ plaque للـ nécrose","d":["دهنة = plaque d'athérome (دهون بجدار الشريان)","شقّة = rupture (الـ plaque بتنشقّ)","جلطة = thrombus (جلطة بتتكوّن عليها وبتسكّر الشريان)","موتة = ischémie ثم nécrose (موت خلايا بعد ٢٠–٣٠ دقيقة)"],"fr":{"t":"Mécanisme de l'IDM en 4 temps","m":"Plaque, Rupture, Thrombus, Nécrose : P-R-T-N, « Pas Rester Trop, Nécrose ! »","d":["P = Plaque d'athérome dans la paroi de l'artère","R = Rupture de la plaque","T = Thrombus qui bouche l'artère","N = Ischémie puis Nécrose après 20 à 30 minutes"]}},{"t":"علاج الـ MI: BASH-MOT","m":"BASH-MOT: «باش موت؟ لأ!» ٧ أحرف للعلاج + الـ stent","d":["B = Bêta-bloquant (بيخفّف شغل القلب)","A = Aspirine (بتمنع الجلطة تكبر)","S = Statine (بتخفّف الكوليسترول)","H = Héparine (anticoagulant = مميّع)","M = Morphine (antalgique = مسكّن للوجع)","O = O₂ (أوكسجين) إذا الـ saturation واطية","T = Thrombolyse (دوا بيذوّب الجلطة)","+ Angioplastie + stent (بالون + شبكة لفتح الشريان)"],"fr":{"t":"Traitement de l'IDM : BASH-MOT","m":"BASH-MOT : 7 lettres pour le traitement, plus le stent","d":["B = Bêta-bloquant : diminue le travail du cœur","A = Aspirine : empêche le caillot de grossir","S = Statine : baisse le cholestérol","H = Héparine : anticoagulant","M = Morphine : antalgique","O = Oxygène si la saturation est basse","T = Thrombolyse : dissout le caillot","+ Angioplastie avec stent : ballon et ressort pour ouvrir l'artère"]}},{"t":"Marqueurs: مين بيطلع أوّل ومين بيضل","m":"Troponine أوّل وبتضلّ جمعة، CK-MB بتخلص بيومين، LDH = Late (متأخّرة) بتضلّ ١٠ أيام","d":["Troponine T و I (تروبونين): بتبلّش بعد ٢–٤ ساعات وبتضلّ ٧ أيام أو أكتر = الأدق والأهم","CK-MB: الذروة خلال ٢٤ ساعة وبترجع طبيعية بعد ٤٨ ساعة","LDH: الذروة بعد ٣–٤ أيام وبتضلّ ١٠ أيام، مفيدة لمريض إجا متأخّر","AST: نادراً، قيمتو محدودة. أهم فحص دم للجلطة = Troponine"],"fr":{"t":"Marqueurs cardiaques : qui monte, qui reste","m":"Troponine : tôt et longtemps ; CK-MB : finie en 48 h ; LDH = L comme Lente (10 jours)","d":["Troponine T et I : monte après 2 à 4 h et reste 7 jours ou plus, la plus précise","CK-MB : pic en 24 h, revient à la normale après 48 h","LDH : pic au 3e-4e jour, reste 10 jours, utile si le patient arrive tard","ASAT : rarement utilisée. Le dosage clé de l'infarctus = la troponine"]}}],"cardio:angor":[{"t":"أنواع الذبحة التلاتة: S-I-P","m":"S-I-P: Stable = Sport، Instable = بالراحة وخطيرة، Prinzmetal = Pyjama","d":["S = Angine stable (مستقرّة): مع الجهد متل الـ Sport، بتروح بالراحة أو بالـ Trinitrine بأقل من ١٠ دقايق","I = Angine instable (غير مستقرّة): حتى بالراحة، أقوى وأطول، ممكن تصير MI (جلطة)","P = Prinzmetal: spasme (تشنّج) بالشريان، بالليل أو الصبح باكر، يعني بالـ Pyjama"],"fr":{"t":"Les 3 angors : S-I-P","m":"S-I-P : Stable = Sport, Instable = au repos et dangereux, Prinzmetal = Pyjama","d":["S = Angor stable : à l'effort, cède au repos ou à la Trinitrine en moins de 10 min","I = Angor instable : même au repos, plus fort et plus long, peut évoluer en infarctus","P = Prinzmetal : spasme de l'artère, la nuit ou tôt le matin, au repos"]}},{"t":"Angine ولا MI؟ رقم ١٠ ضدّ ٢٠","m":"«١٠ بتروح، ٢٠ بتجرح»: الذبحة أقل من ١٠ دقايق، الجلطة أكتر من ٢٠","d":["Angine (ذبحة): أقل من ١٠ دقايق، بتروح بالراحة أو بالـ Trinitrine، troponine (مؤشّر القلب) طبيعية","MI (جلطة): أكتر من ٢٠ دقيقة، ما بتروح، troponine مرتفعة","بالنوبة: إذا الوجع طوّل أكتر من ١٥ دقيقة ← شك بـ MI"],"fr":{"t":"Angor ou infarctus ? 10 contre 20","m":"Moins de 10 min et ça passe = angor ; plus de 20 min et ça reste = infarctus","d":["Angor : moins de 10 min, cède au repos ou à la Trinitrine, troponine normale","Infarctus : plus de 20 min, ne cède pas, troponine élevée","Pendant la crise : douleur de plus de 15 min = suspecter un infarctus"]}}],"cardio:ecg":[{"t":"الموجات: P فوق، QRS تحت، T راحة","m":"P للأذين، QRS للبطين، T = Tranquille (ارتخاء)، وST طالع = MI","d":["Onde P (موجة P) = انقباض الـ oreillettes (الأذينين)","PR = ٠.١٢–٠.٢٠ ثانية (السيال من الأذينين للبطينين)","QRS = انقباض الـ ventricules (البطينين)، أقل من ٠.١٢ ثانية","Onde T = ارتخاء البطينين (repolarisation)","ST طالع (sus-décalage) = MI، ST نازل (sous-décalage) = ischémie (نقص دم) / Angine"],"fr":{"t":"Les ondes : P, QRS, T","m":"P = oreillettes, QRS = ventricules, T = Tranquille (repolarisation) ; ST qui monte = infarctus","d":["Onde P = contraction des oreillettes","PR = 0,12 à 0,20 s","QRS = contraction des ventricules, moins de 0,12 s","Onde T = repolarisation des ventricules","Sus-décalage ST = infarctus ; sous-décalage ST = ischémie / angor"]}},{"t":"لاصقات الأطراف: إشارة السير","m":"من الإيد اليمين مع عقارب الساعة: أحمر ← أصفر ← أخضر ← وبالآخر أسود","d":["أحمر = RA (الإيد اليمين)","أصفر = LA (الإيد الشمال)","أخضر = LL (الإجر الشمال)","أسود = RL (الإجر اليمين) = terre (أرضي)"],"fr":{"t":"Électrodes des membres : le feu tricolore","m":"Depuis le bras droit, dans le sens des aiguilles : Rouge, Jaune, Vert, puis Noir","d":["Rouge = bras droit (RA)","Jaune = bras gauche (LA)","Vert = jambe gauche (LL)","Noir = jambe droite (RL), la terre"]}},{"t":"لاصقات الصدر: ٤ و٥ والـ V3 بالنص","m":"V1 وV2 عالـ ٤، V4 وV5 وV6 عالـ ٥، وV3 قاعد بالنص","d":["V1 = 4ème espace intercostal (الفراغ الرابع) يمين الـ sternum (عظمة القص)، V2 = مقابيلو شمال","V4 = 5ème espace intercostal (الخامس) على الـ ligne médio-claviculaire (خط نص الترقوة)","V5 = نفس مستوى V4 على الـ ligne axillaire antérieure (خط الإبط الأمامي)","V6 = نفس المستوى على الـ ligne axillaire moyenne (خط نص الإبط)","V3 = بالنص بين V2 وV4"],"fr":{"t":"Électrodes précordiales : 4, 5 et V3 au milieu","m":"V1-V2 au 4e espace, V4-V5-V6 au 5e niveau, V3 entre les deux","d":["V1 = 4e espace intercostal à droite du sternum, V2 = en face à gauche","V4 = 5e espace intercostal sur la ligne médio-claviculaire","V5 = même niveau que V4, ligne axillaire antérieure","V6 = même niveau, ligne axillaire moyenne","V3 = entre V2 et V4"]}}],"cardio:pericarde":[{"t":"Triade de Beck (ثلاثية بيك)","m":"«ضغط نازل، صوت مكتوم، رقبة منفوخة»: القلب محشور بالمي = Tamponnade","d":["ضغط نازل = Hypotension (هبوط ضغط)","صوت مكتوم = Bruits du cœur assourdis (أصوات القلب مكتومة/بعيدة)","رقبة منفوخة = Turgescence jugulaire / JVD (انتفاخ عروق الرقبة)","العلاج فوراً: Péricardiocentèse (بزل التامور = إبرة بتسحب المي)"],"fr":{"t":"Triade de Beck","m":"Tension basse, Bruits étouffés, Jugulaires gonflées : le cœur est comprimé = tamponnade","d":["Hypotension","Bruits du cœur assourdis","Turgescence jugulaire (JVD)","Traitement immédiat : péricardiocentèse"]}},{"t":"وجع الـ péricardite بيتغيّر مع القعدة","m":"بيزيد لما ينام، بيخفّ لما يقعد ويميل لقدّام: هيدا الفرق عن الـ MI","d":["Péricardite (التهاب التامور): الوجع بيتغيّر مع الوضعية","مع fièvre (حرارة) وfrottement péricardique (صوت احتكاك بالسماعة)","السبب الأكثر: virus (فيروس)"],"fr":{"t":"Péricardite : la douleur qui change de position","m":"Pire couché, soulagée assis penché en avant : c'est la différence avec l'infarctus","d":["Péricardite : douleur qui varie avec la position","Avec fièvre et frottement péricardique","Cause la plus fréquente : virus"]}},{"t":"التسلسل: التهاب ← مي ← دكّ","m":"نار ← مي ← حصار: péricardite ← épanchement ← tamponnade، والإيكو بيكشفهن","d":["نار = Péricardite (التهاب الكيس)","مي = Épanchement péricardique (سائل زيادة بين الطبقتين)","حصار = Tamponnade (المي ضغطت عالقلب وما عاد يعبّي دم = طوارئ)","التشخيص الأهم: Échographie cardiaque (إيكو القلب)"],"fr":{"t":"La suite : feu, eau, étau","m":"Péricardite, puis épanchement, puis tamponnade ; l'échographie les montre","d":["Feu = péricardite, inflammation du sac","Eau = épanchement péricardique, liquide en trop","Étau = tamponnade, le liquide comprime le cœur : urgence","Examen clé : échographie cardiaque"]}}],"cardio:endomyo":[{"t":"Osler ضدّ Janeway","m":"Osler = Ouch (بتوجّع) عرؤوس الأصابع، Janeway = ما بتوجّع عالكف والإجر","d":["Nodules d'Osler = حبوب زغار بتوجّع عرؤوس الأصابع","Lésions de Janeway = بقع حمرا ما بتوجّع عراحة الإيد والإجر","مع fièvre (حرارة) = أهم عارض، وsouffle (نفخة) جديدة"],"fr":{"t":"Osler contre Janeway","m":"Osler = Ouch (douloureux) au bout des doigts ; Janeway = indolore aux paumes et plantes","d":["Nodules d'Osler : petits nodules douloureux au bout des doigts","Lésions de Janeway : taches rouges indolores aux paumes et aux plantes","Avec la fièvre, signe principal, et un souffle nouveau"]}},{"t":"تشخيص الـ Endocardite = H + E","m":"Endocardite بدها H + E: Hémocultures + ETO، مش Radio ومش Troponine","d":["H = Hémocultures (زرع دم): ٣ عينات قبل الـ antibiotiques","E = ETO (إيكو عن طريق المري): بتشوف الـ végétations (التنبّتات)","Duke أكيد = ٢ majeurs، أو ١ majeur + ٣ mineurs، أو ٥ mineurs","Duke محتمل = ١ majeur + ١ mineur، أو ٣ mineurs"],"fr":{"t":"Diagnostic d'endocardite = H + E","m":"Endocardite = H + E : Hémocultures + ETO, pas la radio ni la troponine","d":["H = Hémocultures : 3 prélèvements avant les antibiotiques","E = ETO : voit les végétations","Duke certaine = 2 majeurs, ou 1 majeur + 3 mineurs, ou 5 mineurs","Duke possible = 1 majeur + 1 mineur, ou 3 mineurs"]}},{"t":"Myocardite: العضلة تعبت بعد الرشح","m":"Myo = Muscle: رشح ← Coxsackie ← troponine طالعة ← repos وممنوع رياضة","d":["السبب الأشهر: virus (فيروس) بالأخص Coxsackie، غالباً بعد grippe بكم يوم","Troponine (أنزيمات القلب) مرتفعة لأنو العضلة متضرّرة","IRM cardiaque (رنين القلب) بتأكّد الالتهاب","العلاج: repos (راحة) + أدوية insuffisance cardiaque: diurétiques، IEC، bêta-bloquants"],"fr":{"t":"Myocardite : le muscle fatigué après la grippe","m":"Myo = Muscle : grippe, Coxsackie, troponine élevée, repos et pas de sport","d":["Cause la plus connue : virus, surtout Coxsackie, quelques jours après une grippe","Troponine élevée car le muscle est atteint","L'IRM cardiaque confirme l'inflammation","Traitement : repos, plus diurétiques, IEC, bêta-bloquants"]}}],"cardio:pacemaker":[{"t":"Pacemaker ضدّ ICD","m":"Pacemaker بيدفش البطيء، ICD بيصدم السريع","d":["Pacemaker (بطارية القلب) ← للـ bradycardie (بطء القلب): إشارات زغيرة ليسرّعه","ICD (Défibrillateur implantable = صادم مزروع) ← للـ tachycardie / fibrillation ventriculaire (رجفان بطيني)","الـ ICD بيعطي choc électrique (صدمة كهربا) ويمنع الموت المفاجئ"],"fr":{"t":"Pacemaker contre DAI","m":"Le pacemaker pousse le cœur lent ; le défibrillateur choque le cœur rapide","d":["Pacemaker : pour la bradycardie, petites impulsions pour accélérer","Défibrillateur implantable : pour la tachycardie ou la fibrillation ventriculaire","Il délivre un choc électrique et évite la mort subite"]}},{"t":"تعليم المريض: ٦ وصايا","m":"إيد تحت، مغناطيس بعيد، خبّر قبل IRM، بطاقة بالجيبة، مراجعة كل ٦ أشهر، نبضك بإيدك","d":["إيد تحت: ما يرفع إيدو فوق راسه ٤–٦ أسابيع","مغناطيس بعيد: aimants (مغناطيس) وأجهزة قوية، والتلفون مش بجيبة القميص فوق الجهاز","يخبّر قبل أي IRM (رنين) أو أي عملية","carte de porteur (بطاقة الجهاز) دايماً معو، مهم بالمطار","contrôle (مراجعة) كل ٦ أشهر للجهاز والبطارية","يقيس نبضه ويخبّر إذا دوخة، إغماء أو نبض بطيء كتير"],"fr":{"t":"Éducation du patient : 6 réflexes","m":"Bras en bas, aimants loin, prévenir avant IRM, carte sur soi, contrôle tous les 6 mois, prendre son pouls","d":["Ne pas lever le bras au-dessus de la tête pendant 4 à 6 semaines","Éviter les aimants et appareils puissants, pas de téléphone dans la poche de chemise","Prévenir avant toute IRM ou opération","Toujours porter la carte de porteur, utile à l'aéroport","Contrôle tous les 6 mois de l'appareil et de la pile","Prendre son pouls et signaler vertiges, syncope ou pouls très lent"]}}],"cardio:embolie":[{"t":"علامات الجلطة الشريانية: الـ 6P","m":"6P: الإجر بتصرخ: وجع مفاجئ، شاحبة، بلا نبض، بتنمّل، مشلولة، باردة","d":["Douleur brutale (وجع مفاجئ)","Pâleur (شحوب)","Pouls absent (ما في نبض)","Paresthésie (تنميل)","Paralysie (شلل)","Froideur (برودة)","مصدرها غالباً القلب: FA (رجفان أذيني)، صمامات، بعد MI"],"fr":{"t":"Embolie artérielle : les 6 signes","m":"Le membre crie : douleur brutale, pâle, sans pouls, fourmille, paralysé, froid","d":["Douleur brutale","Pâleur","Pouls absent","Paresthésie","Paralysie","Froideur","Origine souvent cardiaque : FA, valves, après un infarctus"]}},{"t":"وريد منرفع، شريان لأ","m":"Veine ← منرفع الإجر ليرجع الدم؛ Artère ← ممدودة أو نازلة شوي ليوصل الدم","d":["TVP (Caillot veineux = جلطة بالوريد): ورم، حمرا، سخنة، بتوجع ← منرفع الإجر","Caillot artériel (جلطة بالشريان): باردة، شاحبة، بلا نبض ← ما منرفعها وما منعملها massage","الرفع بيخفّف الدم الشرياني يلي أصلاً ناقص","Héparine IV (مميّع، مراقبة TCA) ← الترياق (antidote) = protamine"],"fr":{"t":"Veine on lève, artère on ne lève pas","m":"Veine : on surélève pour le retour ; Artère : à plat ou un peu déclive pour l'arrivée du sang","d":["TVP (caillot veineux) : jambe gonflée, rouge, chaude, douloureuse, on la surélève","Caillot artériel : membre froid, pâle, sans pouls, on ne le lève pas et pas de massage","Lever le membre réduit le sang artériel déjà insuffisant","Héparine IV (surveiller le TCA), antidote = protamine"]}}],"cardio:choc":[{"t":"أرقام الصدمة القلبية: ٩٠ و٣٠","m":"«٩٠ و٣٠ وجلد بارد بعد MI»: ضغط تحت ٩٠، بول تحت ٣٠ ml/h = Choc cardiogénique","d":["Pression systolique (الضغط الانقباضي) أقل من ٩٠ mmHg","Diurèse (البول) أقل من ٣٠ ml بالساعة","Peau froide et moite (جلد بارد ورطب)","Tachycardie (نبض سريع) وtachypnée (تنفّس سريع)","أهم سبب: Infarctus du myocarde (الجلطة القلبية)"],"fr":{"t":"Choc cardiogénique : 90 et 30","m":"90 et 30 et peau froide après un infarctus : PAS sous 90, diurèse sous 30 ml/h","d":["Pression systolique inférieure à 90 mmHg","Diurèse inférieure à 30 ml par heure","Peau froide et moite","Tachycardie et tachypnée","Cause principale : infarctus du myocarde"]}},{"t":"الحلقة المفرغة","m":"قلب ضعيف ← بيسرّع ← بيجوع أكتر ← بيضعف أكتر: الحلقة بتلفّ","d":["البطين بيضعف ← بينزل الـ débit cardiaque (الناتج القلبي)","الـ système sympathique (الجهاز الودّي): النبض بيسرع والأوعية بتضيق","العضلة بتحتاج أوكسجين أكتر ← نقص تروية ونخر أكبر ← ضعف أكبر"],"fr":{"t":"Le cercle vicieux","m":"Cœur faible, il accélère, il a plus faim d'oxygène, il s'affaiblit encore","d":["Le ventricule faiblit, le débit cardiaque baisse","Le système sympathique accélère le pouls et resserre les vaisseaux","Le muscle demande plus d'oxygène : plus d'ischémie et de nécrose, contraction encore plus faible"]}},{"t":"مقوّيات القلب: Do-Do","m":"Do-Do بيقوّوا القلب: Dopamine وDobutamine = Inotropes","d":["Inotropes (مقوّيات القلب): dopamine، dobutamine","مع O₂ (أوكسجين) وsemi-Fowler (نص جلوس)","وإذا لازم: Ballon intra-aortique (بالون داخل الأبهر)"],"fr":{"t":"Inotropes : Do-Do","m":"Do-Do renforcent le cœur : Dopamine et Dobutamine","d":["Inotropes : dopamine, dobutamine","Avec oxygène et position semi-Fowler","Si besoin : ballon intra-aortique"]}}],"cardio:ic":[{"t":"قصور أيسر ولا أيمن؟ G = Gaz، D = Dans le corps","m":"Gauche = Gaz (الرية بتغرق)، Droite = Dans le corps (المي بالجسم)","d":["IC gauche (قصور أيسر) ← المي بالرية: dyspnée (ضيق نفس)، PND (ضيق نفس بالليل)، crépitants (خراخر)، toux (سعلة)، OAP (وذمة رئوية)","IC droite (قصور أيمن) ← المي بالجسم: JVD (انتفاخ وريد الرقبة)، hépatomégalie (تضخّم كبد)، ascite (مي بالبطن)، œdème (ورم الإجرين)، زيادة وزن","أهم سبب للقصور الأيمن = القصور الأيسر"],"fr":{"t":"IC gauche ou droite : G = Gaz, D = Dans le corps","m":"Gauche = les poumons se noient ; Droite = l'eau va dans le corps","d":["IC gauche : eau dans les poumons, dyspnée, DPN, crépitants, toux, OAP","IC droite : eau dans le corps, turgescence jugulaire, hépatomégalie, ascite, œdèmes, prise de poids","Première cause d'IC droite = l'IC gauche"]}},{"t":"Digoxine: دقيقة كاملة و٦٠","m":"قبل الـ Digoxine: عدّ دقيقة كاملة، تحت ٦٠ = ما منعطي ومنخبّر الحكيم","d":["Digoxine (Digitaliques = جليكوزيدات): بتقوّي الانقباض وبتضبط النبض","منقيس النبض دقيقة كاملة قبل كل جرعة","أقل من ٦٠ ← ما منعطيه ومنخبّر، وننتبه لعلامات التسمّم بالديجوكسين"],"fr":{"t":"Digoxine : une minute et 60","m":"Avant la digoxine : compter une minute entière ; sous 60 on ne donne pas et on prévient","d":["Digoxine : renforce la contraction et règle le rythme","Prendre le pouls une minute entière avant chaque dose","Moins de 60 : ne pas donner, prévenir le médecin, surveiller les signes de toxicité"]}},{"t":"Lasix بيسرق البوتاسيوم","m":"Lasix بيطلّع المي وبيسرق معها الـ K: راقب البوتاسيوم ووزنو كل يوم","d":["Furosémide (Lasix) = Diurétique (مدرّ بول): يطلّع المي الزيادة","مضاعفة: hypokaliémie (نقص بوتاسيوم) ← راقب الـ K، وأكل فيه بوتاسيوم حسب الحكيم","الوزن كل يوم: نفس الساعة ونفس الميزان"],"fr":{"t":"Le Lasix vole le potassium","m":"Le Lasix chasse l'eau et emporte le K : surveiller la kaliémie et peser chaque jour","d":["Furosémide (Lasix) = diurétique : élimine l'eau en trop","Complication : hypokaliémie, surveiller le K, alimentation riche en potassium selon le médecin","Peser chaque jour : même heure, même balance"]}}],"cardio:arythmies":[{"t":"QRS عريض = بطين = خطر","m":"عريض = Ventriculaire (خطر)، ضيّق = Supraventriculaire (فوق البطينين)","d":["QRS ضيّق (أقل من ٣ مربعات زغار = < 0.12 ث) = supraventriculaire (فوق بطيني)","QRS عريض (٣ مربعات أو أكتر) = ventriculaire (بطيني)، المريض ممكن يموت بلحظات","TV (تسرّع بطيني) = QRS عريض بيهدّد الحياة"],"fr":{"t":"QRS large = ventriculaire = danger","m":"Large = Ventriculaire (danger) ; fin = Supraventriculaire","d":["QRS fin (moins de 3 petits carreaux, moins de 0,12 s) = supraventriculaire","QRS large (3 carreaux ou plus) = ventriculaire, le patient peut mourir en quelques instants","TV = QRS large, menace vitale"]}},{"t":"الإيقاع الجيبي: ٥ شروط","m":"«P قبل كل QRS، PR ثابت، P نفس الشكل، ٦٠–١٠٠، ومنتظم»","d":["Onde P (موجة P) قبل كل QRS","PR ثابت بين 0.12 و0.20 ثانية","شكل الـ P نفسو بكل الاشتقاقات","Fréquence (النبض) بين ٦٠ و١٠٠","المسافات P-P وR-R متساوية (منتظم)"],"fr":{"t":"Rythme sinusal : 5 critères","m":"Une P avant chaque QRS, PR fixe, même P partout, 60 à 100, régulier","d":["Onde P avant chaque QRS","PR fixe entre 0,12 et 0,20 s","Même forme de P dans toutes les dérivations","Fréquence entre 60 et 100","Intervalles P-P et R-R égaux"]}},{"t":"كل اضطراب مع شو بيروح","m":"FA بتعمل جلطة، FV بدها صدمة ICD، BAV بدو pacemaker، WPW = PR قصير + delta","d":["FA (Fibrillation auriculaire = رجفان أذيني) ← جلطات بالقلب ← embolie artérielle","FV (Fibrillation ventriculaire = رجفان بطيني) ← هون بيشتغل الـ ICD (صدمة)","BAV (حصار أذيني بطيني) ← علاجو ممكن pacemaker","WPW ← PR قصير (أقل من 0.12) + onde delta (موجة دلتا)"],"fr":{"t":"Chaque trouble et son partenaire","m":"FA donne des caillots, FV appelle le DAI, BAV appelle le pacemaker, WPW = PR court + delta","d":["FA : caillots dans le cœur, risque d'embolie artérielle","FV : c'est là que le défibrillateur implantable choque","BAV : traitement possible par pacemaker","WPW : PR court (moins de 0,12 s) et onde delta"]}}],"cardio:chirurgie":[{"t":"الصمام: ما بيفتح ولا ما بيسكّر؟","m":"Sténose = ما بيفتح، Insuffisance = ما بيسكّر؛ معدني للعمر، بيولوجي ١٠–١٥ سنة","d":["Sténose (تضيّق) = الصمام ما بيفتح منيح ← الدم صعب يمرق","Insuffisance / régurgitation (قصور / ارتجاع) = ما بيسكّر منيح ← الدم بيرجع لورا","Valve mécanique (صمام معدني): طول العمر، بس anticoagulant (مميّع) مدى الحياة + INR","Valve biologique (صمام من حيوان): بلا مميّع مدى الحياة، بيعيش ١٠–١٥ سنة"],"fr":{"t":"La valve : s'ouvre mal ou ferme mal ?","m":"Sténose = s'ouvre mal, Insuffisance = ferme mal ; mécanique à vie, biologique 10-15 ans","d":["Sténose : la valve s'ouvre mal, le sang passe difficilement","Insuffisance / régurgitation : la valve ferme mal, le sang reflue","Valve mécanique : dure toute la vie, mais anticoagulant à vie et contrôle de l'INR","Valve biologique : pas d'anticoagulant à vie, dure 10 à 15 ans"]}},{"t":"الطُعم من وين؟ إجر، صدر، إيد","m":"الـ greffon: إجر، صدر، إيد = Saphène، Mammaire، Radiale","d":["إجر = Veine saphène (وريد الإجر)","صدر = Artère mammaire interne (شريان الصدر)","إيد = Artère radiale (شريان الإيد)","CABG (زرع شرايين) = جسر حول القسم المسكّر من الشريان التاجي"],"fr":{"t":"Le greffon : S-M-R","m":"Saphène, Mammaire, Radiale : jambe, thorax, bras","d":["S = veine Saphène (jambe)","M = artère Mammaire interne (thorax)","R = artère Radiale (avant-bras)","Pontage = un pont autour de la partie bouchée de la coronaire"]}},{"t":"البيت بعد القلب المفتوح: رقم ٦","m":"٦ أسابيع نقاهة، ٦ أسابيع بلا حمل فوق ٥ كغ، ٦ أسابيع بلا سواقة، والقطب بعد ١٤ يوم","d":["نقاهة ٦ أسابيع","ما يحمل أكتر من ٥ كغ لـ ٦ أسابيع","السواقة بعد ٦ أسابيع","فك القطب بعد ١٤ يوم","يرفع الإجر يلي انأخد منها الوريد وهو قاعد (١٥–٣٠ سم) + جرابات دوالي، ووقف التدخين نهائياً"],"fr":{"t":"Retour à la maison : le chiffre 6","m":"6 semaines de convalescence, pas plus de 5 kg, pas de conduite ; fils retirés à 14 jours","d":["Convalescence 6 semaines","Ne pas porter plus de 5 kg pendant 6 semaines","Conduite après 6 semaines","Ablation des fils après 14 jours","Surélever la jambe du prélèvement en position assise (15 à 30 cm), bas de contention, arrêt total du tabac"]}}],"neuro:brain":[{"t":"الفصوص: فكّر، حسّ، اسمع، شوف","m":"F-P-T-O: فكّر (قدّام)، حسّ (فوق)، اسمع (عالجنب)، شوف (لورا)، والمخيخ بيوازن","d":["فكّر = Lobe frontal (الفص الجبهي): حركة إرادية، تفكير، شخصية، كلام","حسّ = Lobe pariétal (الفص الجداري): لمس، وجع، حرارة","اسمع = Lobe temporal (الفص الصدغي): سمع وذاكرة","شوف = Lobe occipital (الفص القذالي): النظر","وازن = Cervelet (المخيخ): توازن وتنسيق، مشكلتو ataxie (ترنّح)"],"fr":{"t":"Les lobes : penser, sentir, entendre, voir","m":"F-P-T-O : Frontal pense, Pariétal sent, Temporal entend, Occipital voit ; le cervelet équilibre","d":["Frontal : mouvement volontaire, pensée, personnalité, parole","Pariétal : toucher, douleur, chaleur","Temporal : audition et mémoire","Occipital : vision","Cervelet : équilibre et coordination, son atteinte donne une ataxie"]}},{"t":"الإبرة تحت النخاع: ١–٢ ضدّ ٣–٥","m":"النخاع بيخلص عند L1–L2، والإبرة بين L3–L4 أو L4–L5: بعيد عنو","d":["Moelle épinière (النخاع الشوكي) بيخلص تقريباً عند L1–L2","تحتو LCR (السائل الدماغي الشوكي) وأعصاب بس","Ponction lombaire (البزل القطني) بين L3–L4 أو L4–L5","Tronc cérébral (جذع الدماغ) = مراكز التنفّس والقلب، لهيك الـ HTIC خطيرة"],"fr":{"t":"L'aiguille sous la moelle : L1-L2 contre L3-L5","m":"La moelle s'arrête vers L1-L2 ; la ponction se fait en L3-L4 ou L4-L5, loin d'elle","d":["La moelle épinière s'arrête vers L1-L2","En dessous : seulement du LCR et des nerfs","Ponction lombaire en L3-L4 ou L4-L5","Le tronc cérébral contient les centres de la respiration et du cœur : d'où le danger de l'HTIC"]}}],"neuro:evaluation":[{"t":"Self-care deficit: روتين الصبح","m":"روتين الصبح: ياكل، يتحمّم، يلبس، يفوت عالحمّام: ٤ أشياء ما بيقدر يعملها لحالو","d":["ياكل = feeding","يتحمّم / النظافة = bathing / hygiene","يلبس = dressing","يفوت عالحمّام = toileting","كلّهن تحت: Self-care deficit (ما بيقدر يهتم بحالو لحالو)"],"fr":{"t":"Déficit en autosoins : la routine du matin","m":"Manger, se Laver, s'Habiller, aller aux Toilettes : 4 gestes impossibles seul","d":["Manger (feeding)","Se laver, hygiène (bathing)","S'habiller (dressing)","Aller aux toilettes (toileting)","Tous regroupés sous : déficit en autosoins"]}},{"t":"Babinski: الإصبع الكبير طلع = مشكلة","m":"Babinski: منحكّ باطن الإجر؛ أصابع لتحت = طبيعي، الكبير لفوق وفتحوا = مشكلة مركزية","d":["الطبيعي عند الكبير: أصابع الإجر بتنثني لتحت","الإصبع الكبير طلع لفوق والأصابع فتحوا = Babinski positif","يعني مشكلة بالجهاز العصبي المركزي","ومنعكسات الحماية اللي ممكن تروح: السعلة، الإقياء (gag)، القرنية (corneal)"],"fr":{"t":"Babinski : le gros orteil qui monte","m":"On gratte la plante : orteils en bas = normal ; gros orteil en haut et éventail = atteinte centrale","d":["Normal chez l'adulte : les orteils se fléchissent vers le bas","Gros orteil qui monte et orteils en éventail = Babinski positif","Signe d'atteinte du système nerveux central","Réflexes de protection qu'on peut perdre : toux, nausée (gag), cornéen"]}},{"t":"عوامل خطر بتقدر تغيّرها: ٣ ك + ض","m":"كيماويات، كحول ومخدرات، كرة (رياضة صدام)، وضغط: هيدول بإيدك","d":["ك = كيماويات أو تلوّث بالشغل","ك = كحول ومخدرات = Substance abuse (سوء استعمال المواد)","ك = كرة / contact sports (رياضات فيها اصطدام)","ض = Hypertension (ارتفاع الضغط)","ما بتتغيّر: Aging (العمر)، قصة عائلية، قصة قلب، ضربة عالراس قديمة، عدوى"],"fr":{"t":"Facteurs modifiables : ce qui dépend de toi","m":"Chimiques, Alcool et drogues, sports de Contact, Hypertension : C-A-C-H","d":["C = produits Chimiques ou pollution au travail","A = Alcool et drogues (abus de substances)","C = sports de Contact","H = Hypertension","Non modifiables : âge, antécédents familiaux, cardiaques, traumatisme crânien, infections"]}}],"neuro:examens":[{"t":"فحوصات الصبغة: CAMS","m":"CAMS بالصبغة: اسأل يود، سمك، صبغة؛ وحذّرو: حرقة حلق واحمرار وجه","d":["C = CT scan / Scanner (التصوير الطبقي)","A = Angiographie cérébrale (تصوير شرايين الدماغ)","M = Myélographie (تصوير النخاع الشوكي)","S = Scintigraphie cérébrale (Brain scan)","قبل كلّن: allergie (حساسية) على اليود، السمك/الأكل البحري، والصبغة","ونخبّرو إنو ممكن يحسّ بحرقة بالحلق واحمرار بالوجه"],"fr":{"t":"Examens avec produit de contraste : CAMS","m":"CAMS : demander iode, poissons/fruits de mer, produit ; prévenir : brûlure de gorge, rougeur du visage","d":["C = Scanner (CT)","A = Angiographie cérébrale","M = Myélographie","S = Scintigraphie cérébrale","Avant : allergie à l'iode, aux poissons et fruits de mer, au produit de contraste","Prévenir d'une brûlure dans la gorge et d'une rougeur du visage"]}},{"t":"البزل القطني: قبل، بعد، وممنوع","m":"قبل: TP/PTT ووقّف المميّع، عجنبو مطوي • بعد: مسطّح ومي كتير • ممنوع: ضهر عوج، راس مضغوط، جلد ملتهب","d":["قبل: TP وPTT (تخثّر) + NFS، نوقّف الـ anticoagulants (مميّعات) لخطر النزيف","الوضعية: position latérale, en chien de fusil (عجنبو ومطوي)، بين L3–L4 أو L4–L5","بعد: à plat (مسطّح) ٢٤ ساعة مشان وجع الراس + force fluids (مي كتير)","ممنوع (Contre-indications): déformation de la colonne (ضهر عوج)، HTIC (راس مضغوط)، infection (جلد ملتهب) بمكان الإبرة"],"fr":{"t":"Ponction lombaire : avant, après, interdit","m":"Avant : TP/TCA, arrêt anticoagulants, chien de fusil ; Après : à plat et boire ; Interdit : D-H-I","d":["Avant : TP, TCA et NFS, arrêter les anticoagulants (risque de saignement)","Position latérale en chien de fusil, ponction en L3-L4 ou L4-L5","Après : à plat 24 h pour éviter la céphalée, faire boire beaucoup","Contre-indications D-H-I : Déformation de la colonne, HTIC, Infection au point de ponction"]}},{"t":"IRM بتكره الحديد، EEG بلا قهوة","m":"IRM = مغناطيس: ولا حديدة بالجسم • EEG = ٨ ساعات بلا أدوية ولا كافيين","d":["IRM (الرنين): ممنوع مع pacemaker (بطارية قلب)، clips معدنية أو شظايا، ونشيل المجوهرات والمعادن","EEG (تخطيط الدماغ): أهم استعمال épilepsie (الصرع)، نوقّف الأدوية والكافيين ٨ ساعات قبل","EEG: نطمّنو ما في كهربا رح تصيبو","Fond d'œil (قاع العين): بيكشف œdème papillaire = HTIC، وبعد النقط ما يسوق"],"fr":{"t":"L'IRM déteste le métal, l'EEG sans café","m":"IRM = aimant : aucun métal ; EEG = 8 h sans médicaments ni caféine","d":["IRM : interdite avec pacemaker, clips métalliques ou éclats ; retirer bijoux et métaux","EEG : surtout pour l'épilepsie, arrêter médicaments et caféine 8 h avant","EEG : rassurer, aucun courant ne passe dans le patient","Fond d'œil : montre l'œdème papillaire (HTIC) ; après les gouttes, ne pas conduire"]}}],"neuro:laminectomie":[{"t":"Logrolling: جذع شجرة","m":"متل جذع شجرة (log): كتف وحوض بيقلبوا سوا، بلا ما يلوي ضهرو","d":["Logrolling = يقلب كلّو قطعة وحدة: الكتف والحوض سوا","بعد العملية: مسطّح على ضهرو (à plat) + logrolling","بعد laminectomie cervicale (الرقبة): ممنوع نثني الرقبة"],"fr":{"t":"Logrolling : comme un tronc d'arbre","m":"Comme un tronc (log) : épaules et bassin tournent ensemble, sans tordre le dos","d":["Logrolling : tourner d'un bloc, épaules et bassin ensemble","Après l'opération : à plat sur le dos et logrolling","Après laminectomie cervicale : ne pas fléchir le cou"]}},{"t":"المضاعفات: RIDIS","m":"بول محبوس، مصارين واقفة، إجرين خدرانة، جرح ملتهب، عضل مشدود","d":["R = Rétention urinaire (احتباس البول)","I = Iléus paralytique (شلل الأمعاء)","D = Déficit moteur et sensitif (نقص بالحركة والإحساس)","I = Infection (التهاب)","S = Spasme musculaire (تشنّج عضل)"],"fr":{"t":"Complications : RIDIS","m":"RIDIS : Rétention, Iléus, Déficit, Infection, Spasme","d":["R = Rétention urinaire","I = Iléus paralytique","D = Déficit moteur et sensitif","I = Infection","S = Spasme musculaire"]}},{"t":"البيت: ٤ «لا» و٤ «إي»","m":"لا تحمل، لا تسوق، لا تنحني، لا بانيو؛ وإي للمشدّ، التمارين، النوم عجنب، والفرشة القاسية","d":["لا: حمل تقيل، سواقة، انحناء كتير، بانيو (حسب الطبيب)","إي: corset / ceinture (مشدّ)","إي: تمارين أسفل الضهر كل يوم","إي: نوم عجنبو والركبتين مطويين، وفرشة قاسية","ويراقب إجريه (تنميل أو برودة) ويعتني بالجرح"],"fr":{"t":"À la maison : 4 non et 4 oui","m":"Non : porter, conduire, se pencher, baignoire ; Oui : corset, exercices, dormir sur le côté, matelas ferme","d":["Non : charges lourdes, conduite, se pencher, baignoire (selon le médecin)","Oui : corset ou ceinture","Oui : exercices du bas du dos chaque jour","Oui : dormir sur le côté genoux fléchis, matelas ferme","Surveiller les jambes (fourmillements, froideur) et soigner la plaie"]}}],"neuro:craniotomie":[{"t":"ليش منفتح الجمجمة؟ CHAT","m":"CHAT (بسّة): Caillot، HTIC، Anévrisme، Tumeur","d":["C = Caillot (جلطة دم) لنشيلها","H = HTIC (ارتفاع الضغط داخل الجمجمة) لنخفّفو","A = Anévrisme (أم الدم) لنصلّحها","T = Tumeur (ورم) لنشيلو","المكان: supratentorielle (فوق الخيمة) أو infratentorielle (تحت الخيمة: المخيخ وجذع الدماغ)"],"fr":{"t":"Pourquoi une craniotomie ? CHAT","m":"CHAT : Caillot, HTIC, Anévrisme, Tumeur","d":["C = enlever un Caillot","H = diminuer l'HTIC","A = réparer un Anévrisme","T = enlever une Tumeur","Localisation : sus-tentorielle (cerveau) ou sous-tentorielle (cervelet, tronc cérébral)"]}},{"t":"بول كتير ومميّع = Diabète insipide","m":"العملية حدّ الـ hypophyse ← راح الـ ADH ← ما في شي يمسك المي ← بول كتير ومميّع","d":["Hypophyse (الغدة النخامية) بتعمل ADH (الهرمون يلي بيمسك المي)","إذا تأذّت بالعملية ← Diabète insipide (السكري الكاذب)","منراقب البول: كمّيتو وكثافتو، والداخل والطالع"],"fr":{"t":"Urines abondantes et diluées = diabète insipide","m":"Opération près de l'hypophyse, plus d'ADH, l'eau n'est plus retenue : urines abondantes et diluées","d":["L'hypophyse fabrique l'ADH, l'hormone qui retient l'eau","Si elle est touchée : diabète insipide","Surveiller la quantité et la densité des urines, entrées et sorties"]}},{"t":"مضاعفات فتح الراس: ضغط، صرع، نفس، بول، عدوى","m":"ضغط، صرع، نفس، بول، عدوى، وإجرين ضعاف: ٦ مضاعفات","d":["ضغط = HTIC (ارتفاع الضغط داخل الجمجمة)","صرع = Convulsions (نوبات صرع) ← précautions anti-convulsions","نفس = Détresse respiratoire (ضيق/فشل تنفّس)","بول = Diabète insipide (السكري الكاذب)","عدوى = Infection، Méningite (التهاب السحايا)","إجرين ضعاف = نقص بالحركة والإحساس","والوضعية: semi-Fowler مشان الدم يرجع من الراس"],"fr":{"t":"Complications de la craniotomie","m":"Pression, Convulsions, Respiration, Urines, Infection, Déficit : 6 complications","d":["HTIC","Convulsions, d'où les précautions anti-convulsions","Détresse respiratoire","Diabète insipide","Infection, méningite","Déficit moteur et sensitif","Position semi-Fowler pour le retour veineux de la tête"]}}],"neuro:avc":[{"t":"الشريان يا بيتسكّر يا بينفجر","m":"AVC = شريان مسكّر (thrombose، embolie، athérosclérose، vasospasme) أو مفجور (hémorragie)","d":["مسكّر: Thrombose (جلطة بمكانها)، Embolie (جلطة طايرة، غالباً من القلب متل FA)","مسكّر: Athérosclérose cérébrale (تصلّب شرايين الدماغ)، Vasospasme (تشنّج الوعاء)","مفجور: Hémorragie (نزيف)","وكمان: HTA (ارتفاع الضغط)، Traumatisme (ضربة)، Syphilis (الزهري)"],"fr":{"t":"L'artère se bouche ou elle saigne","m":"AVC = artère bouchée (thrombose, embolie, athérosclérose, vasospasme) ou rompue (hémorragie)","d":["Bouchée : thrombose, embolie (souvent d'origine cardiaque, comme la FA)","Bouchée : athérosclérose cérébrale, vasospasme","Rompue : hémorragie","Aussi : HTA, traumatisme, syphilis"]}},{"t":"CT قبل المميّع","m":"CT أوّل: إذا نزيف، الـ héparine بتصبّ زيت عالنار","d":["ما منعطي héparine / مميّع إذا الجلطة نزيف (AVC hémorragique)","الـ CT scan بيبيّن النزيف أو الـ infarctus أو انحراف خط النص","Anticoagulants (مميّعات) بالكورس: Warfarine (Coumadine)، Héparine"],"fr":{"t":"Le scanner avant l'anticoagulant","m":"Scanner d'abord : si c'est une hémorragie, l'héparine jette de l'huile sur le feu","d":["Pas d'héparine ni d'anticoagulant si l'AVC est hémorragique","Le scanner montre l'hémorragie, l'infarctus ou la déviation de la ligne médiane","Anticoagulants du cours : warfarine (Coumadine), héparine"]}},{"t":"FA بترمي جلطة: لفوق أو لتحت","m":"FA بترمي جلطة: لفوق = AVC بالدماغ، لتحت = embolie artérielle بالإجر","d":["FA (رجفان أذيني) بتعمل جلطة بالقلب","إذا راحت عالدماغ = AVC (جلطة دماغية): hémiplégie (شلل جهة)، aphasie (ما بيحكي/بيفهم)","إذا راحت عالإجر = embolie artérielle (جلطة شريانية)"],"fr":{"t":"La FA lance un caillot : en haut ou en bas","m":"La FA lance un caillot : en haut = AVC, en bas = embolie artérielle de la jambe","d":["La FA forme un caillot dans le cœur","Vers le cerveau = AVC : hémiplégie, aphasie","Vers la jambe = embolie artérielle"]}}],"neuro:htic":[{"t":"علامات الـ HTIC: راس، معدة، عيون","m":"«راسو بيوجع، معدتو بتقلب، عيونو بتغبّش» والـ Glasgow عم ينزل","d":["راس = Céphalée (وجع راس قوي) ما بيروح بالمسكّنات","معدة = Vomissements (استفراغ) غالباً بالقوة","عيون = Troubles visuels (غباش) + œdème papillaire (وذمة الحليمة) بالـ fond d'œil","وعي = Glasgow عم ينزل","انتبه: الـ HTIC ممنوع معها الـ ponction lombaire"],"fr":{"t":"Signes d'HTIC : tête, estomac, yeux","m":"Céphalée, Vomissements, Œdème papillaire, et un Glasgow qui baisse","d":["Céphalée intense qui ne cède pas aux antalgiques","Vomissements, souvent en jet","Troubles visuels, œdème papillaire au fond d'œil","Glasgow qui baisse","Attention : ponction lombaire contre-indiquée en cas d'HTIC"]}},{"t":"أسباب الـ HTIC: MATT","m":"MATT: Méningite، AVC، Traumatisme، Tumeur","d":["M = Méningite (التهاب السحايا)","A = AVC (جلطة دماغية)","T = Traumatisme crânien (ضربة عالراس) أو بعد craniotomie","T = Tumeur (ورم)"],"fr":{"t":"Causes d'HTIC : MATT","m":"MATT : Méningite, AVC, Traumatisme, Tumeur","d":["M = Méningite","A = AVC","T = Traumatisme crânien ou après craniotomie","T = Tumeur"]}},{"t":"دور الممرّض: راس ٣٠ وعين عالوعي","m":"راس ٣٠°، عين عالـ Glasgow، حساب المي، Mannitol، وعزل إذا méningite","d":["Tête surélevée (راس مرفوع ٣٠°)","نراقب الوعي (Glasgow) والعلامات الحيوية","Bilan entrées/sorties (الداخل والطالع)","Mannitol حسب الوصفة (مدرّ بيخفّف وذمة الدماغ)","Isolement (عزل) contact أو respiratoire حسب السبب"],"fr":{"t":"Rôle infirmier : tête à 30° et œil sur la conscience","m":"Tête à 30°, Glasgow, bilan entrées/sorties, Mannitol, isolement si méningite","d":["Tête surélevée à 30°","Surveiller la conscience (Glasgow) et les signes vitaux","Bilan entrées/sorties","Mannitol sur prescription","Isolement contact ou respiratoire selon la cause"]}}],"neuro:glasgow":[{"t":"Glasgow: ٤ – ٥ – ٦","m":"«عيونك ٤، حكيك ٥، حركتك ٦»: المجموع ٣ لـ ١٥، و٨ وتحت = coma","d":["Yeux (العيون) ١–٤: لحالو (٤)، عالصوت (٣)، عالوجع (٢)، أبداً (١)","Verbal (الكلام) ١–٥: طبيعي (٥)، مشوّش (٤)، كلمات بلا معنى (٣)، أصوات (٢)، ولا شي (١)","Moteur (الحركة) ١–٦: أوامر (٦)، بيحدّد الوجع (٥)، بيسحب (٤)، flexion (٣)، extension (٢)، ولا شي (١)","١٥ = واعي تماماً، ٨ وما دون = coma (غيبوبة) ← خطر عالتنفّس"],"fr":{"t":"Glasgow : 4 - 5 - 6","m":"Yeux 4, Verbal 5, Moteur 6 : total de 3 à 15 ; 8 ou moins = coma","d":["Yeux 1 à 4 : spontanée, au bruit, à la douleur, jamais","Verbal 1 à 5 : orienté, confus, mots inappropriés, sons, rien","Moteur 1 à 6 : obéit, localise, retrait, flexion, extension, rien","15 = conscient ; 8 ou moins = coma, danger respiratoire"]}}],"henderson:h1":[{"t":"الحاجات ١–٧: نهار المريض من الصبح","m":"تنفّس، اشرب وكول، فوت عالحمّام، تحرّك، نام، البس، ودفّي حالك","d":["١ Respirer (يتنفّس)","٢ Boire et manger (يشرب وياكل)","٣ Éliminer (يخرّج: بول وبراز)","٤ Se mouvoir (يتحرّك ويحافظ على وضعية منيحة)","٥ Dormir et se reposer (ينام ويرتاح)","٦ Se vêtir et se dévêtir (يلبس ويشلح)","٧ Maintenir la température (يحافظ على حرارة جسمه)"],"fr":{"t":"Besoins 1 à 7 : la journée du patient","m":"Respire, bois et mange, élimine, bouge, dors, habille-toi, garde ta chaleur","d":["Respirer","Boire et manger","Éliminer","Se mouvoir et maintenir une bonne posture","Dormir et se reposer","Se vêtir et se dévêtir","Maintenir la température du corps"]}},{"t":"كل حاجة مع مريض القلب تبعها","m":"Pacemaker ← Se vêtir، MI بيتعب ← Se mouvoir، Endocardite ← Maintenir la température","d":["Se vêtir (يلبس): بعد Pacemaker ممنوع يرفع إيدو ← Déficit de soins personnels : se vêtir","Se mouvoir (يتحرّك): مريض قلب بيتعب ← Intolérance à l'activité (عدم تحمّل النشاط)","Maintenir la température (الحرارة): fièvre بالـ Endocardite ← Hyperthermie","Boire et manger (ياكل): قليل ملح لمريض القلب ← Alimentation déficiente / Risque de déshydratation","Respirer (يتنفّس): dyspnée ← Mode de respiration inefficace"],"fr":{"t":"Chaque besoin avec son patient cardiaque","m":"Pacemaker = Se vêtir ; IDM essoufflé = Se mouvoir ; Endocardite = Température","d":["Se vêtir : après pacemaker, pas de bras levé ; déficit de soins personnels : se vêtir","Se mouvoir : patient cardiaque fatigué ; intolérance à l'activité","Maintenir la température : fièvre de l'endocardite ; hyperthermie","Boire et manger : régime sans sel ; alimentation déficiente, risque de déshydratation","Respirer : dyspnée ; mode de respiration inefficace"]}}],"henderson:h2":[{"t":"الحاجات ٨–١٤: ٧ أفعال","m":"نضّف، انتبه، احكي، صلّي، اشتغل، تسلّى، تعلّم","d":["٨ نضّف = Être propre et protéger ses téguments (يكون نضيف ويحمي جلده)","٩ انتبه = Éviter les dangers (يتجنّب المخاطر)","١٠ احكي = Communiquer (يتواصل مع غيره)","١١ صلّي = Agir selon ses croyances et valeurs (يعيش حسب دينه وقيمه)","١٢ اشتغل = S'occuper en vue de se réaliser (يشتغل ويحس حالو مفيد)","١٣ تسلّى = Se récréer (يتسلّى ويرفّه عن حالو)","١٤ تعلّم = Apprendre (يتعلّم)"],"fr":{"t":"Besoins 8 à 14 : les 7 P","m":"Propre, Prudent, Parler, Prier, Produire, Plaisir, Progresser","d":["Propre = Être propre et protéger ses téguments","Prudent = Éviter les dangers","Parler = Communiquer","Prier = Agir selon ses croyances et valeurs","Produire = S'occuper en vue de se réaliser","Plaisir = Se récréer","Progresser = Apprendre"]}},{"t":"الـ Case study: حاجة ← مشكلة ← تشخيص ← تدخّل","m":"ح-م-ت-ت: حاجة، مشكلة، تشخيص NANDA، تدخّل","d":["ح = الحاجة (بالاسم: مثلاً Se mouvoir = يتحرّك)","م = المشكلة: مريض MI بيتعب بس يمشي","ت = التشخيص NANDA: Intolérance à l'activité (عدم تحمّل النشاط)","ت = التدخّل: راحة + نشاط تدريجي","Apprendre (يتعلّم) ← Manque de connaissances (نقص معرفة)، نفس يلي بالـ Pacemaker"],"fr":{"t":"Case study : besoin, problème, diagnostic, intervention","m":"B-P-D-I : Besoin, Problème, Diagnostic NANDA, Intervention","d":["B = le Besoin, par son nom (ex. Se mouvoir)","P = le Problème : patient IDM fatigué à la marche","D = le Diagnostic NANDA : intolérance à l'activité","I = l'Intervention : repos et activité progressive","Apprendre = manque de connaissances, comme pour le pacemaker"]}}],"law:l1":[{"t":"درجات التمريض الأربعة: سلّم الشهادات","m":"🪜 من فوق لتحت: ماستر ← جامعة 3 سنين ← مهني 3 سنين ← بكالوريا فنية","d":["ممرض متخصص = إجازة جامعية بالعلوم التمريضية + ماستر على الأقل ← دورو تخطيطي وقيادي","ممرض = برنامج جامعي أساسي 3 سنين أو أكتر + إجازة جامعية ← بالمشاركة والتنسيق مع الفريق والطبيب","ممرض فني = تعليم مهني 3 سنين + إجازة فنية رسمية ← بالمشاركة مع الممرض والفريق","مساعد ممرض = بكالوريا فنية بالعناية التمريضية ← تحت إشراف (متخصص أو ممرض أو فني)","قاعدة: كل الأربعة بدهن إذن مزاولة مهنة من وزارة الصحة العامة"],"fr":{"t":"Les 4 grades : l'échelle des diplômes","m":"De haut en bas : Master > Licence univ. 3 ans > Licence technique 3 ans > Bac technique","d":["Infirmier spécialisé = licence en sciences infirmières + au moins un master : rôle de planification et de leadership","Infirmier = programme universitaire de 3 ans ou plus + licence : soins en participation et coordination avec l'équipe et le médecin","Infirmier technicien = enseignement professionnel 3 ans + licence technique (LT) : participe avec l'infirmier et l'équipe","Aide-infirmier = bac technique en soins infirmiers : travaille sous supervision","Règle : les 4 ont besoin d'une autorisation d'exercer du ministère de la Santé publique"]}},{"t":"مهام الممرض المتخصص الأربعة: «عَمبَر»","m":"عَمبَر: عناية متقدّمة، مناهج، أبحاث، رأي للمؤسسة","d":["ع = عناية تمريضية متقدّمة ومتخصّصة (جودة عالية، كفاءات سريرية متقدّمة)","م = المساهمة بوضع المناهج الأكاديمية والعملية بمؤسسات التعليم العالي","ب = إجراء الدراسات والأبحاث العلمية","ر = إبداء الرأي للمؤسسة بأصول وكيفية تقديم الخدمات التمريضية"],"fr":{"t":"Les 4 missions du spécialisé : SERA","m":"SERA : Soins avancés, Enseignement (cursus), Recherche, Avis à l'institution","d":["S = Soins infirmiers avancés et spécialisés (haute qualité, compétences cliniques avancées)","E = Enseignement : contribuer aux cursus académiques et pratiques de l'enseignement supérieur","R = Recherche : études et recherches scientifiques","A = Avis donné à l'institution sur la manière d'offrir les services infirmiers"]}},{"t":"شروط إذن المزاولة للبناني: 5 أصابع","m":"✋ كل إصبع شرط: لبناني 18، شهادة، كفاءة، سجلّ نضيف، colloquium","d":["1 = لبناني وعمرو 18 سنة","2 = شهادة تمريض من لبنان، أو من برّا بعد معادلتها","3 = الكفاءات الصحية والعقلية والأخلاقية","4 = غير محكوم بجناية أو محاولة جناية أو جنحة شائنة","5 = نجح بامتحان الـ colloquium (امتحان الكفاءة)","وغير اللبناني: مُرسَل من هيئة أو منظمة دولية مرخّصة، أو أستاذ بمدرسة تمريض (مُجاز ببلدو + عقد محدّد المدّة)"],"fr":{"t":"Autorisation d'exercer (Libanais) : L + D + 3C","m":"Libanais, Diplômé, puis 3C : Compétent, Casier vierge, Colloquium","d":["L = Libanais âgé de 18 ans","D = Diplôme infirmier du Liban, ou de l'étranger après équivalence","C = Compétences sanitaires, mentales et morales","C = Casier vierge : aucune condamnation pour crime, tentative de crime ou délit infamant","C = Colloquium réussi (examen de compétence)","Non-Libanais : envoyé par un organisme international autorisé, ou enseignant en école d'infirmiers (autorisé dans son pays + contrat à durée déterminée)"]}}],"law:l2":[{"t":"LT و BT و BP: قدّيش مدّة كل شهادة","m":"LT تلاتة، BT تلاتة، والـ BP تسعة أشهر متل الحمل 🤰","d":["LT = Licence technique (الإجازة الفنية): 3 سنين ← امتحان رسمي بآخر الدراسة","BT = Baccalauréat technique (البكالوريا الفنية): 3 سنين بعد الشهادة المتوسطة الرسمية أو البريفيه المهنية","BP = Brevet professionnel (البريفيه المهنية): 9 أشهر بعد الشهادة المتوسطة اللبنانية","الامتحان الرسمي للتلاتة بتجريه مديرية التعليم المهني والتقني"],"fr":{"t":"LT, BT, BP : la durée de chaque diplôme","m":"LT trois ans, BT trois ans, BP neuf mois comme une grossesse","d":["LT = Licence technique : 3 ans, examen officiel en fin d'études","BT = Baccalauréat technique : 3 ans après le brevet officiel ou le BP","BP = Brevet professionnel : 9 mois après le brevet libanais","L'examen officiel des trois : Direction de l'enseignement professionnel et technique"]}},{"t":"كل شهادة لمين؟ وين الـ colloquium؟","m":"LT للفني، BT للمساعد، BP للمعاون الصحي، والـ colloquium بس للخاص","d":["LT (الإجازة الفنية) = شهادة الممرض الفني","BT (البكالوريا الفنية بالعناية التمريضية) = شهادة مساعد الممرض","BP (البريفيه المهنية) ← إذن مزاولة بصفة معاون صحي (مش ممرض)","colloquium (امتحان وطني) = بالـ LT بس، ولطلاب المعاهد الخاصة بس"],"fr":{"t":"Quel diplôme pour qui ? Et le colloquium ?","m":"LT pour le technicien, BT pour l'aide, BP pour l'agent de santé, colloquium seulement au privé","d":["LT (licence technique) = diplôme de l'infirmier technicien","BT (bac technique en soins infirmiers) = diplôme de l'aide-infirmier","BP (brevet professionnel) = autorisation comme agent de santé, pas infirmier","Colloquium (examen national) = seulement en LT et pour les instituts privés"]}}],"law:l3":[{"t":"مهام وزارة الصحة العامة: 8 أفعال","m":"الوزارة بتحمي، بتشرف، بتكافح، بتوعّي، بتحسّن، بتنمّي، بتبحث، وبترخّص","d":["بتحمي = الوقاية من الأمراض والأوبئة ومعالجة المرضى والمحتاجين","بتشرف = على المؤسسات الصحية الحكومية والخاصة","بتكافح = القضاء على الأمراض المعدية وغير المعدية","بتوعّي = توعية الشعب لأنماط حياة وعادات غذائية صحّية","بتحسّن = إدارة النظام الصحي ونوعية الخدمات وفعاليتها من حيث التكلفة","بتنمّي = الموارد البشرية للرعاية الصحية","بتبحث = بحوث الأنظمة الصحية","بترخّص = لمزاولة مهن الطب والتمريض والمختبر والأشعة + اقتراح التشريعات"],"fr":{"t":"Missions du ministère de la Santé : 8 verbes","m":"Le ministère protège, supervise, combat, éduque, améliore, forme, cherche et autorise","d":["Protège = prévention des maladies et épidémies, soins aux malades et aux démunis","Supervise = les établissements de santé publics et privés","Combat = les maladies transmissibles et non transmissibles","Éduque = la population vers des modes de vie et une alimentation sains","Améliore = la gestion du système de santé, la qualité et le rapport coût-efficacité","Forme = développe les ressources humaines de santé","Cherche = recherche sur les systèmes de santé","Autorise = licences pour médecine, soins infirmiers, laboratoire, radiologie + propositions de lois"]}},{"t":"مين بيرأس، وكيف الوزارة بالمناطق","m":"وزير ومعو مدير عام، محافظة إلها مصلحة إلا بيروت، وكل قضاء إلو قسم","d":["رأس الوزارة = وزير الصحة","بيعاونو = المدير العام + رؤساء الدوائر المركزية والإقليمية","بكل محافظة = مصلحة الصحة العامة، إلا محافظة بيروت (الاستثناء)","بمركز كل قضاء = «قسم القضاء»","الترخيص لمزاولة التمريض = من وزارة الصحة العامة"],"fr":{"t":"Qui dirige et comment le ministère est présent","m":"Un ministre aidé d'un directeur général, un service par mohafazat sauf Beyrouth, une section par caza","d":["Tête = le ministre de la Santé","Aidé par = le directeur général + les chefs des départements centraux et régionaux","Chaque mohafazat (province) = un service de santé publique, sauf Beyrouth","Chaque chef-lieu de caza (district) = une section de santé","L'autorisation d'exercer infirmier vient du ministère de la Santé publique"]}}],"mgmt:m1":[{"t":"هرم Maslow: خمس ألِفات من تحت لفوق","m":"أكل ← أمان ← أحباب ← احترام ← إثبات الذات","d":["أكل = الحاجات الفيزيولوجية Physiological (الأكل، الشرب، النوم) ← الأساس","أمان = Safety / Sécurité (أمان مادي، أمان داخل المجتمع)","أحباب = العلاقات Love/Belonging / Appartenance (زواج، صداقة، علاقات اجتماعية)","احترام = Esteem / Estime","إثبات الذات = Self-actualization / Accomplissement de soi ← القمة"],"fr":{"t":"Pyramide de Maslow : Pierre Sait Aimer Et Agir","m":"Pierre Sait Aimer Et Agir : Physiologiques, Sécurité, Appartenance, Estime, Accomplissement","d":["Pierre = besoins Physiologiques (manger, boire, dormir) : la base","Sait = Sécurité (matérielle, dans la société)","Aimer = Appartenance (mariage, amitié, relations sociales)","Et = Estime","Agir = Accomplissement de soi : le sommet","On lit la pyramide de bas en haut"]}},{"t":"خصائص الدوافع الستّة: الدافع متل الهوا","m":"🌬️ ما بينشاف، بيتغيّر، كل واحد عطريقتو، الشبع بيزيدو، ما بيجي لحالو، وبيلفّ إذا انسدّ","d":["ما بينشاف = منستنبطو من السلوك","بيتغيّر = حاجات متعدّدة ومتغيّرة وممكن تتضارب","عطريقتو = كل فرد بيشبع حاجاتو بطريقة مختلفة","الشبع بيزيدو = إشباع الحاجة ممكن يزيد قوّتها مش يطفيها","ما بيجي لحالو = نادر نلاقي دافع منفصل، بتكون مجموعة دوافع","بيلفّ = السلوك الهادف ما دايماً بيشبع (عقبات) ← بيطلع سلوك تاني"],"fr":{"t":"Les 6 caractéristiques de la motivation : comme le vent","m":"Comme le vent : invisible, changeante, personnelle, grandit, jamais seule, contourne l'obstacle","d":["Invisible = on la déduit du comportement","Changeante = besoins multiples, variables, parfois contradictoires","Personnelle = chacun satisfait ses besoins à sa manière","Grandit = satisfaire un besoin peut augmenter sa force au lieu de l'éteindre","Jamais seule = rarement isolée, souvent un ensemble de motifs","Contourne = le comportement visé ne satisfait pas toujours (obstacles), un autre comportement apparaît"]}}],"mgmt:m2":[{"t":"الدوائر التمانية تحت المدير: 4 جوز","m":"🏥 جودة وتسويق، تمريض وطب، بشر وصيانة، إدارة ومال","d":["جوز 1 = دائرة الجودة Quality + دائرة التسويق والعلاقات العامة Marketing","جوز 2 = الدائرة التمريضية Nursing + الدائرة الطبية Medical","جوز 3 = الموارد البشرية HR + الصيانة Maintenance","جوز 4 = الدائرة الإدارية Administration + الدائرة المالية Finance","فوق المدير: مجلس الإدارة Board of directors"],"fr":{"t":"Les 8 départements sous le directeur : 4 paires","m":"Qualité et Marketing, Soins et Médical, RH et Maintenance, Administration et Finance","d":["Paire 1 = Qualité + Marketing et relations publiques","Paire 2 = Soins infirmiers + Médical","Paire 3 = Ressources humaines + Maintenance","Paire 4 = Administration + Finance","Au-dessus du directeur : le conseil d'administration"]}},{"t":"الدائرة المالية من جوّا","m":"مالي، تدقيق، حسابي ← والحسابي: فوترة، دخول، صندوق ← أمين ← مساعد","d":["الدائرة المالية = 3 أقسام: القسم المالي، قسم التدقيق Audit، القسم الحسابي Accounting","تحت القسم الحسابي = الفوترة Billing، الدخول Admission، الصندوق Cash desk","الصندوق ← أمين الصندوق Cashier ← مساعد أمين الصندوق"],"fr":{"t":"Le département financier de l'intérieur","m":"Finance, Audit, Comptabilité ; sous la comptabilité : Facturation, Admission, Caisse","d":["Département financier = 3 sections : finance, audit, comptabilité","Sous la comptabilité = facturation, admission, caisse","Caisse : caissier puis caissier adjoint"]}},{"t":"أنواع العلاقات: فوق-تحت ولّا جنب-جنب","m":"↕️ فوق-تحت = توجيهية، ↔️ جنب-جنب = تنسيقية، والاقتراح بيروح عالجودة","d":["توجيهية = من المسؤول للي تحت منّو (مساعد ممرّض ومدير التمريض)","تنسيقية = رئيس قسم مع رئيس قسم تاني (نفس المستوى)","اقتراحات = السهم بيروح على دائرة الجودة"],"fr":{"t":"Types de relations : vertical ou horizontal","m":"Vertical = relation de direction, horizontal = coordination, la suggestion va à la Qualité","d":["Direction = du responsable vers son subordonné (aide-infirmier et directeur des soins)","Coordination = entre deux chefs de section du même niveau","Suggestions = la flèche va vers le département Qualité"]}}],"mgmt:m3":[{"t":"أنماط القيادة التلاتة: مين بيقرّر؟","m":"👑 «أنا بقرّر» ديكتاتوري، «منقرّر سوا» ديمقراطي، «قرّروا انتو» تحرّري","d":["autocratique (ديكتاتورية) = القائد بيصدر أوامرو وبيفرض رأيو، والكل بينفّذ بلا اعتراض","démocratique (ديمقراطية) = مشاركة وتبادل آراء وتعاون لصنع القرار","laisser-faire (تحرّرية) = المجموعة بتحدّد أهدافها وبتنظّم حالها، والقائد بالحدّ الأدنى"],"fr":{"t":"Les 3 styles de leadership : qui décide ?","m":"« Je décide » autocratique, « on décide ensemble » démocratique, « décidez vous-mêmes » laisser-faire","d":["Autocratique = le chef donne des ordres et impose son avis, tous exécutent sans objection","Démocratique = participation, échange d'avis et coopération pour décider","Laisser-faire = le groupe fixe ses objectifs et s'organise, le chef participe au minimum"]}},{"t":"التوجيه: 3 وظايف و4 مبادئ","m":"🧭 «قِتا» للوظايف: قيادة، تحفيز، إرشاد • والمبادئ: عدل، مشاركة، وحدة، تقدير","d":["ق = القيادة leadership: فنّ التأثير بالعاملين لتحقيق الأهداف","ت = التحفيز motivation: تشجيع العاملين بإشباع رغباتهم وحاجاتهم","ا = الإرشاد: تزويد العاملين بالمعلومات والتوجيهات اللازمة","مبادئ = العدالة مع المرؤوسين، مشاركة العاملين بالقرار، وحدة الهدف ووحدة التوجيه، تقدير جهود العاملين"],"fr":{"t":"La direction : 3 fonctions et 4 principes","m":"Fonctions LMO : Leadership, Motivation, Orientation ; principes : Justice, Participation, Unité, Reconnaissance","d":["L = Leadership : l'art d'influencer les employés vers les objectifs","M = Motivation : encourager en satisfaisant désirs et besoins","O = Orientation : donner les informations et directives nécessaires","Principes = justice envers les subordonnés, participation aux décisions, unité du but et de la direction, reconnaissance des efforts"]}},{"t":"القيادة ضدّ الإدارة: إنسان ولّا ورق","m":"⚖️ القائد بيأثّر بالناس، المدير بيطبّق القوانين","d":["القيادة = نفوذ وتأثير جماعي ← الإدارة = سلطة رسمية وامتثال","القيادة = الجماعة مصدر السلطة ← الإدارة = التنظيم الرسمي للسلطة","القيادة = تفاعل ومشاركة ← الإدارة = الوصف التنظيمي للعلاقات","القيادة = العنصر البشري (تدريب، تحفيز) وبتواكب التغيير ← الإدارة = نتائج الأداء والمكوّنات المادية","صفات القائد (7): ذكاء، إبداع، معرفة، ثقة بالنفس، تعاون، تحليل وحلّ مشاكل، شخصية مؤثّرة"],"fr":{"t":"Leadership contre gestion : l'humain ou le règlement","m":"Le leader influence les gens, le gestionnaire applique les règles","d":["Leadership = influence collective ; gestion = autorité officielle et obéissance","Leadership = le groupe est source d'autorité ; gestion = organisation officielle de l'autorité","Leadership = interaction et participation ; gestion = description organisationnelle des relations","Leadership = l'élément humain (formation, motivation), suit le changement ; gestion = résultats et moyens matériels","Qualités du leader (7) : intelligence, créativité, savoir, confiance en soi, coopération, analyse et résolution, personnalité influente"]}}],"mgmt:m4":[{"t":"حسنات المشاركة الخمسة","m":"🤝 لما منشارك: قرار أحسن، ثقة أكبر، قادة جداد، معنويات فوق، ومشاكل بتنحلّ أسرع","d":["قرار أحسن = بتساعد بتحسين القرار","ثقة أكبر = بين المدير والأفراد","قادة جداد = بتنمّي القيادات الإدارية وبتزيد إحساسهم بالمسؤولية","معنويات فوق = بترفع الروح المعنوية","أسرع = حلّ المشاكل بشكل أفضل وبوقت أقلّ","التعريف: أسلوب إداري بيقوم على التعاون وتبادل الآراء لتحقيق الأهداف"],"fr":{"t":"Les 5 avantages de la participation","m":"Quand on participe : meilleure décision, confiance, nouveaux leaders, moral haut, problèmes vite réglés","d":["Meilleure décision = améliore la prise de décision","Confiance = entre le directeur et les individus","Nouveaux leaders = développe les cadres et leur sens des responsabilités","Moral haut = élève le moral","Vite réglés = résoudre mieux les problèmes en moins de temps","Définition : style de gestion basé sur la coopération et l'échange d'avis"]}},{"t":"دور القائد بالمشاركة: بيفتح الباب","m":"🚪 بيشرك، بيهيّئ الجو، بيعطي الكل فرصة، وبيحفّز","d":["بيشرك = العاملين بالمواضيع اللي بتدخل بنطاق أعمالهن","بيهيّئ الجو = تهيئة المناخ الملائم","الكل = إعطاء الفرصة للجميع بالمشاركة","بيحفّز = تحفيز الأفراد","ما تخلط: المشاركة = أسلوب إداري، القيادة الديمقراطية = نمط قيادة بيعتمد عليها"],"fr":{"t":"Rôle du leader dans la participation : il ouvre la porte","m":"Il implique, prépare le climat, donne sa chance à chacun et motive","d":["Implique = les employés dans les sujets de leur domaine","Climat = préparer un climat favorable","Chacun = donner à tous l'occasion de participer","Motive = motiver les individus","Attention : participation = style de gestion ; leadership démocratique = style de leadership qui s'appuie dessus"]}}],"quality:q1":[{"t":"تعريف الجودة: 4 «مناسب»","m":"✅ الشي الصح، عالطريقة الصح، بالوقت الصح، بالمكان الصح ← أحسن نتيجة","d":["الفعل المناسب = شو منعمل","الطريقة المناسبة = كيف","الوقت المناسب = إيمتى","المكان المناسب = وين","← لتحقيق أفضل نتائج ممكنة، بأفضل كفاءة وأقل خطر"],"fr":{"t":"Définition de la qualité : 4 « bons »","m":"Le bon acte, de la bonne façon, au bon moment, au bon endroit : le meilleur résultat","d":["Bon acte = quoi faire","Bonne façon = comment","Bon moment = quand","Bon endroit = où","Pour le meilleur résultat possible, avec la meilleure efficacité et le moindre risque"]}},{"t":"نموذج Donabedian: SPR","m":"🏗️ S-P-R: هيكل ← سير عمل ← نتيجة (متل بيت: حيطان، شغل، نتيجة)","d":["S = Structure (الهيكل): العناصر والموارد الموجودة بالمؤسسة","P = Process (سير العمل / العملية): كيف منفّذ العمل والخدمات","R = Results (النتائج): اللي منوصل إلو بعد الخدمة","مثال: نقص ممرضين (هيكل) ← بيأثّر عأداء الممرض (سير عمل) ← حالات طارئة للمريض (نتيجة)"],"fr":{"t":"Modèle de Donabedian : SPR","m":"S-P-R : Structure, Processus, Résultats","d":["S = Structure : éléments et ressources de l'établissement","P = Processus : comment le travail et les services sont réalisés","R = Résultats : ce qu'on obtient après le service","Exemple : manque d'infirmiers (structure), soins perturbés (processus), urgences chez le patient (résultat)"]}},{"t":"Juran ضدّ Crosby ضدّ الجودة الشاملة","m":"جوران بيخطّط وبيراقب وبيحسّن، كروسبي بيطابق وبيوقّي، والشاملة: زبون، فريق، تحسين","d":["Juran (جوران) = تخطيط + مراقبة (قياس، إحصائيات، انحرافات) + تحسين مستمر","Crosby (كروسبي) = مواءمة الجودة مع المتطلبات + إجراءات وقائية للحد من العيوب ومنعها","الجودة الشاملة = التركيز على الزبون + العمل الجماعي + التحسين المستمر","مشكلات الجودة = استخدام قليل، سوء استخدام، استخدام مفرط للتدخلات"],"fr":{"t":"Juran, Crosby et qualité totale","m":"Juran : Planifier, Contrôler, Améliorer ; Crosby : Conformité + Prévention ; QT : Client, Équipe, Amélioration","d":["Juran = planification + contrôle (mesure, statistiques, écarts) + amélioration continue","Crosby = conformité de la qualité aux exigences + mesures préventives pour réduire et éviter les défauts","Qualité totale = orientation client + travail d'équipe + amélioration continue","Problèmes de qualité = sous-utilisation, mauvaise utilisation, sur-utilisation des interventions"]}}],"quality:q2":[{"t":"دورة Deming: PDCA","m":"🔄 خطّط، نفّذ، تحقّق، اعمل… والدولاب بيرجع يلفّ","d":["P = Plan (خطّط): الهدف، الموارد المادية والبشرية، المدة","D = Do (نفّذ): المريض بينفّذ الخطة بالتعليمات","C = Check (تحقّق): مراقبة اعتدال ضغط الدم والعلامات (الصداع)","A = Act (اعمل / إجراء تصحيحي): قريب من الهدف ← كمّل، بعيد ← دوّر عالثغرة وعيد الخطة"],"fr":{"t":"La roue de Deming : PDCA","m":"Planifier, Faire, Vérifier, Agir, puis la roue recommence","d":["P = Plan : objectif, ressources matérielles et humaines, durée","D = Do : le patient applique le plan avec les consignes","C = Check : surveiller la tension artérielle et les signes (céphalée)","A = Act : proche de l'objectif = continuer ; loin = chercher la faille et refaire le plan"]}},{"t":"سمكة Ishikawa: 4M","m":"🐟 راس السمكة = المشكلة، والعضم الأربعة = 4M","d":["Method (الطريقة): وجود إجراءات، توافر أدوات صحية","Machine (الآلة): صيانة وقائية، إنتاج حسب المواصفات","Manpower (القوى البشرية): تدريب؟ خبرة كافية؟","Material (المواد): توافر المواد الصحية ونوعيتها","مثال الدرس: تأخّر برنامج العمليات بالمستشفى"],"fr":{"t":"Le poisson d'Ishikawa : 4M","m":"Tête du poisson = le problème ; les 4 arêtes = les 4M","d":["Method (méthode) : procédures, outils disponibles","Machine : maintenance préventive, production conforme","Manpower (main-d'œuvre) : formée ? assez d'expérience ?","Material (matériel) : disponibilité et qualité du matériel","Exemple : retard du programme opératoire"]}},{"t":"Pareto وHistogram وControl chart","m":"📊 باريتو: 20 بتعمل 80 • هيستوغرام: أعمدة • Control chart: 3 خطوط","d":["Pareto (باريتو) = 20% من الأسباب ← 80% من النتائج، أعمدة تنازلية من الأهم للأقل","Histogram (المدرج التكراري) = أعمدة عمودية بتبيّن التكرار النسبي للأحداث","Control chart (مخطط المراقبة) = خط علوي + خط أوسط + خط سفلي، بيراقب التباين مع الوقت","مثال باريتو: خطأ بالتوقيع 40% + خطأ بالوقت 30% = 70%"],"fr":{"t":"Pareto, histogramme et carte de contrôle","m":"Pareto : 20 font 80 ; histogramme : des barres ; carte de contrôle : 3 lignes","d":["Pareto = 20 % des causes donnent 80 % des résultats, barres décroissantes du plus au moins important","Histogramme = barres verticales montrant la fréquence relative des événements","Carte de contrôle = ligne haute + ligne médiane + ligne basse, surveille la variation dans le temps","Exemple Pareto : erreur de signature 40 % + erreur d'horaire 30 % = 70 %"]}}],"quality:q3":[{"t":"SWOT: جوّا وبرّا","m":"🏠 S وW جوّا البيت، 🌍 O وT برّا البيت","d":["S = Strengths (نقاط القوة): إيجابيات داخل المؤسسة","W = Weaknesses (نقاط الضعف): أمور داخلية بدها تحسين","O = Opportunities (الفرص): عوامل خارجية منستغلّها","T = Threats (التهديدات): عوامل خارجية بتعيق الأهداف"],"fr":{"t":"SWOT : dedans et dehors","m":"S et W dans la maison, O et T dehors","d":["S = Strengths (forces) : points positifs internes","W = Weaknesses (faiblesses) : points internes à améliorer","O = Opportunities (opportunités) : facteurs externes à exploiter","T = Threats (menaces) : facteurs externes qui gênent les objectifs"]}},{"t":"أهداف SMART","m":"🎯 الهدف الذكي: محدّد، بينقاس، بيتحقّق، إلو صلة، وإلو وقت","d":["S = Specific (محدّد): واضح مش عام","M = Measurable (قابل للقياس): بالأرقام أو النتائج","A = Achievable (قابل للتحقيق): ضمن الإمكانيات","R = Relevant (ذو صلة): مرتبط بحاجة المؤسسة","T = Time-bound (محدّد بزمن): إلو موعد نهائي"],"fr":{"t":"Objectifs SMART","m":"Un objectif intelligent : précis, mesurable, atteignable, pertinent, daté","d":["S = Specific : précis, pas général","M = Measurable : mesurable en chiffres ou résultats","A = Achievable : atteignable avec les moyens disponibles","R = Relevant : lié aux besoins de l'établissement","T = Time-bound : avec une échéance claire"]}},{"t":"تحليل الفجوة: رموز التقييم الخمسة","m":"م.ك كلّو، م.ج جزء، م.ص بدّو تحسين، غ.م مش مطبّق، غ.ط ما بينطبق","d":["م.ك = مطبّق كليًا","م.ج = مطبّق جزئيًا","م.ص = مطبّق ويحتاج إلى تحسين","غ.م = غير مطبّق","غ.ط = لا ينطبق","الفكرة: تقييم ذاتي بيقارن المؤسسة شو هيّي مع المعايير المنشودة"],"fr":{"t":"Analyse des écarts : les 5 codes","m":"Totalement, Partiellement, À améliorer, Non appliqué, Non applicable","d":["Totalement appliqué","Partiellement appliqué","Appliqué mais à améliorer","Non appliqué","Non applicable","Idée : auto-évaluation qui compare l'établissement aux normes visées"]}}],"quality:q4":[{"t":"المؤشر: 3 أسئلة ومعادلة","m":"📈 شو؟ مين؟ قدّيش وقت؟ ← عدد الحالات × 100 ÷ كل العيّنة","d":["شو = الظاهرة موضوع الدراسة","مين = العيّنة البشرية","قدّيش وقت = المدة الزمنية","المعادلة: المؤشر = عدد الحالات المتكرّرة × 100 ÷ العدد الإجمالي للعيّنة ضمن مدة محدّدة","المقياس بيحدّد «لماذا؟» والمعيار بيحدّد «كيف؟»"],"fr":{"t":"L'indicateur : 3 questions et une formule","m":"Quoi ? Qui ? Combien de temps ? Puis cas x 100 / échantillon total","d":["Quoi = le phénomène étudié","Qui = l'échantillon humain","Combien de temps = la période","Formule : indicateur = nombre de cas x 100 / effectif total de l'échantillon sur une période donnée","La mesure dit « pourquoi ? », la norme dit « comment ? »"]}},{"t":"3 أنواع مقاييس: موارد، أنشطة، تغيّرات","m":"هيكلية = قدّيش عنّا، سير العمل = شو عملنا، النتائج = شو تغيّر","d":["مقياس الهيكلية = حجم الموارد المستخدمة","مقياس سير العمل = الأنشطة والمساهمات لتحقيق الهدف","مقياس النتائج = المتغيّرات الحاصلة","أمثلة مؤشرات: العقر، عدوى المستشفى، إعادة الاستشفاء • موارد بشرية: إجازات مرضية، حوادث عمل"],"fr":{"t":"3 types de mesures : ressources, activités, changements","m":"Structure = ce qu'on a, processus = ce qu'on fait, résultats = ce qui change","d":["Structure = volume des ressources utilisées","Processus = activités et contributions pour atteindre l'objectif","Résultats = changements obtenus","Exemples : escarres, infection nosocomiale, réhospitalisation ; RH : arrêts maladie, accidents du travail"]}}],"quality:q5":[{"t":"السياسة ضدّ الإجراء","m":"📜 السياسة = «شو؟» • 🦶 الإجراء = «كيف؟» (الإجراء متل الإجر: بيمشي الخطوات)","d":["السياسة = توجيهات مكتوبة، إطار عام بيحدّد المبادئ ← ماذا يجب أن نعمل؟","الإجراء = خطوات عملية مكتوبة لتنفيذ السياسة ← كيف ننفّذ؟","التصنيف: على مستوى المؤسسة ككل (نظافة اليدين) أو على مستوى القسم (الأشعة، المختبر)"],"fr":{"t":"Politique contre procédure","m":"Politique = « quoi ? » ; procédure = « comment ? », la procédure fait marcher les étapes","d":["Politique = directives écrites, cadre général et principes : que faut-il faire ?","Procédure = étapes pratiques écrites pour appliquer la politique : comment faire ?","Classement : niveau établissement (hygiène des mains) ou niveau service (radiologie, laboratoire)"]}},{"t":"ترقيم السياسات: 3-3-3","m":"🔢 3 حروف - 3 حروف - 3 أرقام، متل COP-MUL-001","d":["أول 3 حروف = الفئة الوظيفية (COP = Care of Patient، العناية بالمريض)","تاني 3 حروف = الفئة المعنية (MUL = Multi Units، الوحدات المتعدّدة)","3 أرقام = رقم تسلسلي (001)","مثال تاني: SQE-HRD-002 = مؤهلات الموظفين وتثقيفهم، قسم الموارد البشرية","ACC = الوصول للرعاية واستمراريتها • PFR = حقوق المريض والعائلة • AOP = تقييم المريض"],"fr":{"t":"Numérotation des politiques : 3-3-3","m":"3 lettres, 3 lettres, 3 chiffres, comme COP-MUL-001","d":["3 premières lettres = catégorie fonctionnelle (COP = Care of Patient)","3 lettres suivantes = catégorie concernée (MUL = Multi Units)","3 chiffres = numéro de série (001)","Autre exemple : SQE-HRD-002 = qualification du personnel, service RH","ACC = accès et continuité des soins ; PFR = droits du patient et de la famille ; AOP = évaluation du patient"]}},{"t":"موضع العملية: X قبل النوم","m":"❌ حطّ X قبل أي دوا بيأثّر عالوعي، وإذا الموضع مش واضح: كل شي بيوقف","d":["علامة X ظاهرة على موضع العملية قبل أي دوا بيأثّر على وعي المريض","برّا غرفة العمليات: تواصل شفهي، السجل الطبي، موافقة المريض، الفحوصات، جدول العملية","جوّا غرفة العمليات: تأكيد مكان العمل الجراحي من جديد","كل مشارك بيعيد الخطوات كاملة وبتتوثّق","موضع مش واضح = تتوقّف كل الخطوات لحتى يتحدّد"],"fr":{"t":"Site opératoire : un X avant le sommeil","m":"Marquer un X avant tout médicament qui altère la conscience ; site flou = tout s'arrête","d":["Marque X visible sur le site avant tout médicament qui agit sur la conscience","Hors bloc : communication orale, dossier médical, consentement, examens, programme opératoire","Au bloc : reconfirmer le site chirurgical","Chaque membre refait toutes les étapes, tout est documenté","Site non clair = toutes les étapes s'arrêtent jusqu'à clarification"]}}],"quality:q6":[{"t":"المسؤولية: 3 عناصر و3 أنواع","m":"⚖️ خطأ + ضرر + رابط بيناتن • مدنية = تعويض، جزائية = عقوبة، مسلكية = نظام داخلي","d":["عناصرها: مبدأ الخطأ (إرادي أو غير إرادي) + الضرر + ارتباط السبب بالضرر","مدنية = تعويض عن خطأ شخصي نتج عنه ضرر","جزائية = خرق قانوني بيستوجب العقوبة","مسلكية = مخالفة للنظام الداخلي للمؤسسة"],"fr":{"t":"La responsabilité : 3 éléments, 3 types","m":"Faute + dommage + lien ; civile = réparation, pénale = sanction, disciplinaire = règlement interne","d":["Éléments : faute (volontaire ou non) + dommage + lien de causalité","Civile = indemniser une faute personnelle qui a causé un dommage","Pénale = violation de la loi qui entraîne une sanction","Disciplinaire = infraction au règlement interne de l'établissement"]}},{"t":"مصادر مسؤولية الممرض السبعة","m":"🚨 غلط بالعناية، قتل، ضرب، فتّ بغير اختصاصك، فضحت سر، قصّرت، وما ساعدت","d":["خطأ في العناية","القتل بقصد","الجرح والضرب المقصود","أخذ مبادرة من خارج اختصاصه","إفشاء سر","التقصير عن الواجب","عدم مدّ يد المساعدة"],"fr":{"t":"Les 7 sources de responsabilité de l'infirmier","m":"Erreur de soin, homicide, coups, hors compétence, secret trahi, négligence, non-assistance","d":["Erreur dans les soins","Homicide volontaire","Coups et blessures volontaires","Initiative hors de sa compétence","Divulgation d'un secret","Manquement au devoir","Non-assistance (ne pas porter secours)"]}},{"t":"رضا المرضى وواجب الـ 48 ساعة","m":"📋 رضا المريض: راقب، سجّل حوادث، استمارات، سجّل شكاوى، حلّل • والإلغاء قبل 48 ساعة","d":["قياس الرضا = مراقبة ميدانية، تسجيل الحوادث، بحث ميداني (استمارات)، تسجيل الشكاوى، التحليل","واجب المريض: إذا بدّو يلغي موعد، يبلّغ مكتب المواعيد قبل 48 ساعة","الشكوى ما لازم تأثّر سلبًا على علاج المريض"],"fr":{"t":"Satisfaction des patients et les 48 heures","m":"Observer, noter les incidents, questionnaires, noter les plaintes, analyser ; annuler 48 h avant","d":["Mesurer la satisfaction = observation sur le terrain, registre des incidents, enquête (questionnaires), registre des plaintes, analyse","Devoir du patient : prévenir le bureau des rendez-vous 48 heures avant d'annuler","Une plainte ne doit jamais nuire aux soins du patient"]}}],"quality:q7":[{"t":"سلامة المريض: 4 تاءات","m":"⚠️ تحديد، تقدير، تعامل، تقييم: أربع «ت» للخطر","d":["ت = تحديد المخاطر","ت = تقدير المخاطر","ت = التعامل مع المخاطر","ت = تقييم كيفية التعامل معها","المسؤولية على مستويين: فردي (الممارس) ومشترك (المؤسسة ككل)"],"fr":{"t":"Sécurité du patient : IETE","m":"Identifier, Estimer, Traiter, Évaluer le risque","d":["I = Identifier les risques","E = Estimer les risques","T = Traiter les risques","E = Évaluer la façon de les traiter","Responsabilité à 2 niveaux : individuelle (le praticien) et partagée (l'établissement)"]}},{"t":"FMEA ضدّ RCA","m":"🔧 FMEA بيصلّح العطل وبيرجّع يشغّل • 🌱 RCA بيحفر عالجذر: ليش صار؟","d":["FMEA = Failure Mode Effects and Analysis (تحليل أنماط الفشل وتأثيراته): استكشاف الأخطاء وإصلاحها","FMEA = بحث منطقي عن مصدر المشكلة لحلّها وإعادة تشغيل العملية","RCA = Root Causes Analysis (تحليل الأسباب الجذرية): ليش صار الفشل؟ وشو سببو؟","RCA = بيحدّد الإجراء الوقائي اللي بيمنع الفشل بالمستقبل"],"fr":{"t":"FMEA contre RCA","m":"FMEA répare la panne et relance ; RCA creuse jusqu'à la racine : pourquoi ?","d":["FMEA = analyse des modes de défaillance et de leurs effets : dépanner et réparer","FMEA = recherche logique de la source du problème, puis relance du processus","RCA = analyse des causes racines : pourquoi l'échec ? quelle cause ?","RCA = définit l'action préventive qui évite l'échec à l'avenir"]}},{"t":"مصادر الأخطاء الطبية: إنسان، إجراء، نظام","m":"👤 الإنسان، 🧩 الإجراء المعقّد، 🏥 النظام الفاشل","d":["عوامل بشرية","تعقيد الإجراء","فشل النظام الطبي","التخفيف: تدريب، صيانة الأجهزة، دقّة بالأدوية المتشابهة باللفظ، دقّة بهوية المريض، التسليم الصحيح"],"fr":{"t":"Sources d'erreurs médicales : humain, acte, système","m":"L'humain, l'acte complexe, le système défaillant","d":["Facteurs humains","Complexité de l'acte","Défaillance du système médical","Réduire le risque : formation, maintenance, prudence avec les médicaments aux noms proches, identité du patient, transmission correcte"]}}],"quality:q8":[{"t":"تعريف الاعتماد: طوعي، خارجي، معايير، مؤقت","m":"🏅 الاعتماد = امتحان بتقدّمو بإرادتك، لجنة من برّا بتصحّح، والشهادة مؤقتة","d":["طوعي = عملية تقييم طوعي","خارجي = جهة تقييم خارجية مستقلة","معايير = محدّدة وقابلة للتطوير وموضوعة مسبقًا من هيئة الاعتماد","مؤقت = بيعطي المؤسسة اعترافًا مؤقتًا بكفاءتها"],"fr":{"t":"Définition de l'accréditation","m":"Un examen qu'on passe volontairement, corrigé par un jury externe, avec un diplôme temporaire","d":["Volontaire = évaluation volontaire","Externe = organisme d'évaluation externe et indépendant","Normes = précises, évolutives, fixées à l'avance par l'organisme d'accréditation","Temporaire = reconnaissance temporaire de la compétence de l'établissement"]}},{"t":"منظمات الاعتماد العالمية: أول حرف بيدلّ","m":"🌍 J لأميركا، T لبريطانيا، A لأستراليا، C لكندا، Agence لفرنسا، Makka للسعودية","d":["JCI = Joint Commission International ← USA (أميركا)","TAS = The Trent Accreditation Scheme ← UK (بريطانيا)","ACHSI = Australian Council on Healthcare Standards International ← أستراليا","CCHSA = Canadian Council on Health Services Accreditation ← كندا","ANAES = Agence Nationale d’Accréditation et d’Évaluation en Santé ← فرنسا","MRQP = Makka Region Quality Program ← السعودية"],"fr":{"t":"Organismes internationaux : le nom donne le pays","m":"JCI USA, TAS UK, ACHSI Australie, CCHSA Canada, ANAES France, MRQP Arabie saoudite","d":["JCI = Joint Commission International : USA","TAS = The Trent Accreditation Scheme : Royaume-Uni","ACHSI = Australian Council on Healthcare Standards International : Australie","CCHSA = Canadian Council on Health Services Accreditation : Canada","ANAES = Agence Nationale d’Accréditation et d’Évaluation en Santé : France","MRQP = Makka Region Quality Program : Arabie saoudite"]}},{"t":"مسح الاعتماد: من الطلب للجولة","m":"📝 طلب ← مراجعة ومبالغ ← فريق (طبيب، ممرضة، إداري) ← موعد ← مسح شامل","d":["1 = طلب الاعتماد: معلومات مفصّلة (الخدمات، عدد الأسرّة، الطاقم، المباني والأجهزة)","2 = مراجعة الطلب ← تحديد المبالغ (حجم المؤسسة، أيام الزيارة، عدد الفريق)","3 = تشكيل الفريق: طبيب + ممرضة + إداري","4 = تحديد موعد الزيارة","مسح شامل = مقابلات (قيادات، طاقم، مرضى وعائلاتهم) + جولة (أدوية، صيدلية، عدوى، نفايات، صيانة)"],"fr":{"t":"L'enquête d'accréditation : de la demande à la visite","m":"Demande, examen et frais, équipe (médecin, infirmière, administratif), date, visite complète","d":["1 = Demande : infos détaillées (services, nombre de lits, personnel, bâtiments et équipements)","2 = Examen de la demande, puis fixation des frais (taille, jours de visite, taille de l'équipe)","3 = Équipe : un médecin + une infirmière + un administratif","4 = Fixer la date de la visite","Visite complète = entretiens (dirigeants, personnel, patients et familles) + tournée (médicaments, pharmacie, infection, déchets, maintenance)"]}}],"quality:q9":[{"t":"محتوى الملف الطبي وصيغه: 3 و3","m":"📁 جوّاتو: شخصي، مالي، طبي • شكلو: ورق، Microfilm، إلكتروني","d":["المعلومات = الشخصية + المالية + الطبية","الصيغة = ورقية + Microfilm (ميكروفيلم) + إلكترونية","قيمتو: طبية، تمريضية، ديموغرافية، وقانونية (مرجع بحال مساءلة)","سرّية الملف لازم تكون كاملة"],"fr":{"t":"Contenu et formats du dossier : 3 et 3","m":"Dedans : personnel, financier, médical ; forme : papier, microfilm, électronique","d":["Informations = personnelles + financières + médicales","Formats = papier + microfilm + électronique","Valeur : médicale, infirmière, démographique et juridique (référence en cas de litige)","La confidentialité doit être totale"]}},{"t":"أرقام الأرشيف: 10، 1، ونسخة","m":"🗄️ 10 سنين حفظ، ملف واحد لمريض واحد، ونسخة عالخروج بموافقة الطبيب","d":["10 = حفظ الملفات بمكان آمن عشر سنين على الأقل","1 = ملف طبي واحد للمريض الواحد مهما تعدّدت مرات الدخول","توحيد ملفات الطوارئ والعيادات الخارجية مع ملفات الاستشفاء","نسخة = المريض بياخد نسخة من ملفو عند خروجو بعد موافقة الطبيب المعني","الوصول = بس للأشخاص المخوّلين"],"fr":{"t":"Les chiffres de l'archive : 10, 1 et une copie","m":"10 ans de conservation, 1 dossier par patient, une copie à la sortie avec l'accord du médecin","d":["10 = conserver les dossiers en lieu sûr au moins dix ans","1 = un seul dossier par patient, quel que soit le nombre d'admissions","Unifier urgences, consultations externes et hospitalisation","Copie = remise au patient à sa sortie après accord du médecin concerné","Accès = seulement pour les personnes autorisées"]}}],"pharma:cardio":[{"t":"موانع الـ Bêtabloquant: BAHA","m":"BAHA: البيتابلوكر بيقلّك ما بتاخدني إذا قلبك بطيء، عندك ربو، ضغطك واطي أو عم ترضعي","d":["B = Bradycardie (بطء ضربات القلب)","A = Asthme sévère (الربو الشديد)","H = Hypotension (انخفاض ضغط الدم)","A = Allaitement (الرضاعة)","موجودين عند الاتنين: Temormin = Aténolol و Concor = Bisoprolol","المراقبة: Pouls (النبض) + Tension artérielle (الضغط الشرياني)"],"fr":{"t":"Contre-indications des bêtabloquants : BAHA","m":"BAHA : pas de bêtabloquant si le cœur est lent, l'asthme sévère, la tension basse ou si la mère allaite","d":["B = Bradycardie","A = Asthme sévère","H = Hypotension","A = Allaitement","Communes à Temormin (aténolol) et Concor (bisoprolol)","Surveillance : pouls + tension artérielle"]}},{"t":"Lanoxin / Digoxin: قوّي وبطّي","m":"الديجوكسين «قوّي وبطّي»: بيقوّي الكبسة وبينظّم وبيبطّي، وبيشتغل عالـ IC والـ FA والـ Flutter","d":["Action: Augmente la force de la contraction (بيقوّي انقباض القلب) + Régularise et ralentit (بينظّم وبيبطّي)","Indications: Insuffisance cardiaque (فشل القلب)، Fibrillation auriculaire (رجفان أذيني)، Flutter auriculaire (رفرفة أذينية)","Surveillance: dose sérique de Digoxin (نسبة الديجوكسين بالدم) + rythme cardiaque (نظم القلب)","Effets: Nausée et vomissement (لعيان واستفراغ)، Trouble visuel (مشاكل نظر)، Hypokaliémie (نقص البوتاسيوم)"],"fr":{"t":"Lanoxin / Digoxine : « Fort et lent »","m":"Digoxine = « fort et lent » : plus de force, rythme régularisé et ralenti ; pour IC, FA et flutter","d":["Action : augmente la force de la contraction + régularise et ralentit","Indications : insuffisance cardiaque, fibrillation auriculaire, flutter auriculaire","Surveillance : dose sérique de digoxine + rythme cardiaque","Effets : nausée et vomissement, trouble visuel, hypokaliémie"]}},{"t":"Lasix: بيشفّط المي والملح","m":"Lasix بيشفّط: بيضيّع مي وK وNa، بيوقّع الضغط وقفة، وبيعمل Crampes","d":["Lasix = Furosémide = Diurétique de l'anse (مدرّ للبول)","مي: Déshydratation (جفاف)","ملح: Hypokaliémie (نقص البوتاسيوم) + baisse de la Natrémie (نقص الصوديوم بالدم)","ضغط: Hypotension orthostatique (هبوط الضغط وقت الوقوف)","عضل: Crampes (تشنجات)","لهيك المراقبة: Électrolytes (الأملاح) + Tension artérielle (الضغط)"],"fr":{"t":"Lasix : il vide l'eau et le sel","m":"Lasix vide tout : l'eau, le K, le Na, la tension debout, et laisse des crampes","d":["Lasix = furosémide = diurétique de l'anse","Eau : déshydratation","Sel : hypokaliémie + baisse de la natrémie","Tension : hypotension orthostatique","Muscles : crampes","Donc surveiller : électrolytes + tension artérielle"]}}],"pharma:coag":[{"t":"مراقبة المميّعات: ض-ش-ن","m":"ض-ش-ن: مع أي مميّع: راقب الضغط، لا للشفرة الكهربا، وعينك عالنزيف","d":["ض = Surveillance de la tension artérielle (مراقبة الضغط)","ش = Éviter rasoir électrique (تجنّب استعمال الشفرة الكهربائية)","ن = Signes d'hémorragie (علامات النزيف)","نفس التلاتة عند Héparine و Lovenox و Sintrom"],"fr":{"t":"Surveillance des anticoagulants : T-R-H","m":"T-R-H : avec tout anticoagulant, Tension, pas de Rasoir électrique, signes d'Hémorragie","d":["T = surveiller la tension artérielle","R = éviter le rasoir électrique","H = surveiller les signes d'hémorragie","Les mêmes trois pour Héparine, Lovenox et Sintrom"]}},{"t":"Thrombolytique ضد Anticoagulant","m":"Thrombo-LYSE بيدوّب الجلطة؛ Anti-COAG بيمنع التخثّر. والـ lyse بيفتح 3 أبواب: الرئة، الراس، القلب","d":["Actilyse / Streptase / Alteplase / Streptokinase = Thrombolytique: Lyse de caillot (تذويب الجلطة)","Indications: Embolie pulmonaire (انصمام رئوي)، AVC (جلطة دماغية)، Infarctus du myocarde (احتشاء عضلة القلب)","Héparine (HNF) و Lovenox = Anticoagulation (منع التخثّر)","Sintrom = Antivitamine K (مضاد فيتامين K)","مراقبة الـ thrombolytique: ECG (تخطيط القلب) + signes d'hémorragie (علامات النزيف)"],"fr":{"t":"Thrombolytique vs anticoagulant","m":"Thrombo-LYSE dissout le caillot ; ANTI-coagulant empêche la coagulation. La lyse ouvre 3 portes : poumon, cerveau, cœur","d":["Actilyse / Streptase / Alteplase / Streptokinase = thrombolytique : lyse de caillot","Indications : embolie pulmonaire, AVC, infarctus du myocarde","Héparine (HNF) et Lovenox = anticoagulation","Sintrom = antivitamine K","Surveillance du thrombolytique : ECG + signes d'hémorragie"]}},{"t":"موانع Sintrom: صرخة AAGH","m":"Sintrom بيصرخ AAGH: لا حساسية، لا أسبرين معه، لا حمل، ولا كبد تعبان","d":["A = Allergie aux anticoagulants oraux (حساسية عالمميّعات بالتم)","A = Association aux médicaments contenant de l'aspirine (ما بينعطى مع أدوية فيها أسبرين)","G = Grossesse (الحمل)","H = Insuffisance Hépatique (فشل الكبد)"],"fr":{"t":"Contre-indications du Sintrom : AAGH","m":"Sintrom crie AAGH : Allergie, Aspirine associée, Grossesse, insuffisance Hépatique","d":["A = allergie aux anticoagulants oraux","A = association aux médicaments contenant de l'aspirine","G = grossesse","H = insuffisance hépatique"]}}],"pharma:atb":[{"t":"Aminosides: الأذن والكلوة","m":"الأمينوسيد بيضرب الأذن والكلوة: راقب أ-ك-ح (أذن، كلوة، حساسية)","d":["Aminosides بالدرس: Amikin (Amikacin) و Gentamycine (Aminoglycoside)","أ = Surveillance de l'audition (مراقبة السمع) ← Effet: Trouble auditif (مشاكل سمع)","ك = Surveillance de la fonction rénale (مراقبة الكلى) ← Effet: Troubles rénaux (مشاكل كلى)","ح = Test d'allergie (فحص الحساسية)","موانع عند الاتنين: Myasthénie (الوهن العضلي)، Grossesse (الحمل)، Allergie aux aminosides"],"fr":{"t":"Aminosides : oreille et rein","m":"L'aminoside frappe l'oreille et le rein : surveiller O-R-A (Oreille, Rein, Allergie)","d":["Aminosides du cours : Amikin (amikacine) et Gentamycine (aminoglycoside)","O = surveillance de l'audition, effet : trouble auditif","R = surveillance de la fonction rénale, effet : troubles rénaux","A = test d'allergie","Contre-indications communes : myasthénie, grossesse, allergie aux aminosides"]}},{"t":"أجيال الـ Céphalosporines: راضي، زينة، كلافو","m":"1-2-3: «راضي» واحد، «زينة» تنين، «كلافو» تلاتة. وحساسية Pénicilline = انتبه من Céphalo","d":["1ère génération (الجيل الأول) = Céfradine","2ème génération (الجيل التاني) = Zinacef (Céfuroxime)","3ème génération (الجيل التالت) = Claforan (Cefotaxime) و Céfiroxime","C لـ Claforan هو 3ème حرف بالأبجدية ← 3ème génération","Allergie aux Pénicillines (حساسية عالبنسلين) مانع عند Claforan و Céfiroxime، و Augmentin ممنوع بـ Allergies à Céphalosporines et aux Pénicillines"],"fr":{"t":"Générations des céphalosporines : 1-2-3","m":"1-2-3 : Céfradine = 1, Zinacef = 2, Claforan = 3. Allergie aux pénicillines = attention aux céphalo","d":["1re génération = Céfradine","2e génération = Zinacef (céfuroxime)","3e génération = Claforan (céfotaxime) et Céfiroxime","C de Claforan = 3e lettre de l'alphabet = 3e génération","Allergie aux pénicillines : contre-indication de Claforan et Céfiroxime ; Augmentin : allergies aux céphalosporines et aux pénicillines"]}},{"t":"Flagyl ما بيسهر","m":"Flagyl ما بيسهر: لا كحول، لا ولد تحت 6 سنين، ولا رضاعة","d":["Flagyl = Métronidazole: Antibiotique + Antiseptique intestinal (مطهّر معوي)","Indications: Antiparasitaire (ضد الطفيليات)، vaginites (التهاب المهبل)، infection gastro-intestinale (التهاب هضمي)","Contre-indications: Consommation d'alcool (شرب الكحول)، Enfant moins de 6 ans (ولد أصغر من 6 سنين)، Allaitement (الرضاعة)، Hypersensibilité (حساسية)"],"fr":{"t":"Flagyl ne fait pas la fête","m":"Flagyl ne fait pas la fête : pas d'alcool, pas d'enfant de moins de 6 ans, pas d'allaitement","d":["Flagyl = métronidazole : antibiotique + antiseptique intestinal","Indications : antiparasitaire, vaginites (traitement local), infection gastro-intestinale","Contre-indications : alcool, enfant de moins de 6 ans, allaitement, hypersensibilité au métronidazole"]}}],"pharma:pain":[{"t":"Aspirine: 4 A","m":"الأسبرين عندو 4 A: ضد الالتهاب، ضد الحرارة، ضد الوجع، وبيمنع تجمّع الصفائح","d":["A = Anti-inflammatoire (مضاد التهاب)","A = Antipyrétique (خافض حرارة)","A = Analgésique (مسكّن)","A = Anti-agrégant plaquettaire (مضاد تجمّع الصفائح لمنع الجلطة)","بس انتبه: Ulcère gastroduodénal (قرحة معدة) و Hémorragie (نزيف) = ممنوع"],"fr":{"t":"Aspirine : les 4 A","m":"L'aspirine a 4 A : anti-inflammatoire, antipyrétique, analgésique, anti-agrégant","d":["A = anti-inflammatoire","A = antipyrétique","A = analgésique","A = anti-agrégant plaquettaire (prévenir la thrombose)","Contre-indications : ulcère gastroduodénal, hémorragie"]}},{"t":"AINS = معدة وكلوة؛ Paracétamol = كبد","m":"الـ AINS بيحرق المعدة وبيتعب الكلوة، والـ Paracétamol صاحب الكبد","d":["AINS بالدرس: Aspirine، Olfen (Diclofenac)، Profénid (Kétoprofène)","معدة: Ulcère gastroduodénal (قرحة) + saignement digestif (نزيف هضمي) ← موانع ومراقبة","كلوة: Surveillance de la fonction rénale (مراقبة الكلى)","Paracétamol (Dafalgan، Perfalgan): ممنوع بـ Insuffisance hépatocellulaire (فشل خلايا الكبد)","Perfalgan: Surveillance de la fonction hépatique (مراقبة الكبد) لأنو بيعمل Toxicité hépatique (تسمم كبدي)"],"fr":{"t":"AINS = estomac et rein ; paracétamol = foie","m":"AINS : estomac et rein en danger ; paracétamol : surveiller le foie","d":["AINS du cours : Aspirine, Olfen (diclofénac), Profénid (kétoprofène)","Estomac : ulcère gastroduodénal + saignement digestif (contre-indication et surveillance)","Rein : surveillance de la fonction rénale","Paracétamol (Dafalgan, Perfalgan) : contre-indiqué si insuffisance hépatocellulaire","Perfalgan : surveiller la fonction hépatique (toxicité hépatique)"]}},{"t":"Tramal: DCS","m":"Tramal بيعمل DCS: بيعلّق، بيقبّض، وبينعّس","d":["Tramal = Tramadol = Analgésique opioïde (مسكّن أفيوني)","D = Dépendance (إدمان) ← لهيك منراقب الكمية","C = Constipation (إمساك)","S = Somnolence (نعاس)","ممنوع: Insuffisance respiratoire aiguë (فشل تنفسي حاد)، Epilepsie (صرع)، intoxication avec des sédatifs (تسمم بالمهدئات)"],"fr":{"t":"Tramal : DCS","m":"Tramal donne DCS : Dépendance, Constipation, Somnolence","d":["Tramal = tramadol = analgésique opioïde","D = dépendance, donc surveiller la quantité","C = constipation","S = somnolence","Contre-indications : insuffisance respiratoire aiguë, épilepsie, intoxication aux sédatifs"]}}],"pharma:resp":[{"t":"Combivent = Ventoline + Atrovent","m":"Combi = تنين بواحد: Salbutamol تبع Ventoline + Ipratropium تبع Atrovent","d":["Ventoline = Salbutamol = Bronchodilatateur (موسّع قصبات)","Atrovent = Anticholinergique + Ipratropium = Bronchodilatateur","Combivent = Salbutamol + Bromure d'ipratropium = Antiasthmatique (ضد الربو)","التلاتة بيوسّعوا: Asthme (ربو) و BPCO (انسداد رئوي مزمن) / Bronchite chronique"],"fr":{"t":"Combivent = Ventoline + Atrovent","m":"Combi = deux en un : le salbutamol de Ventoline + l'ipratropium d'Atrovent","d":["Ventoline = salbutamol = bronchodilatateur","Atrovent = anticholinergique, ipratropium = bronchodilatateur","Combivent = salbutamol + bromure d'ipratropium = antiasthmatique","Pour l'asthme et la BPCO / bronchite chronique"]}},{"t":"Ventoline: القلب بيركض والإيد بترجف","m":"Ventoline: قلب بيركض، إيد بترجف، وK بيهرب","d":["قلب: Tachycardie (تسرّع القلب) + Palpitation (خفقان) ← Surveillance de pouls (مراقبة النبض)","إيد: Tremblement (رجفة)","K: Hypokaliémie (نقص البوتاسيوم)","وكمان: Maux de tête (وجع راس) و Crampes musculaires (تشنج عضلي)"],"fr":{"t":"Ventoline : cœur qui court, main qui tremble","m":"Ventoline : le cœur court, la main tremble, le K s'enfuit","d":["Cœur : tachycardie + palpitation, donc surveiller le pouls","Main : tremblement","K : hypokaliémie","Aussi : maux de tête, crampes musculaires"]}},{"t":"Pulmicort: بعدو مضمضة","m":"Pulmicort كورتيزون بالبخ: بعدو اعتني بالتم، وإلا فطريات وبحّة","d":["Pulmicort = Budésonide corticoïde = Anti-inflammatoire stéroïdien (مضاد التهاب ستيرويدي)","Candidose buccale (فطريات بالتم)","Dysphonie (بحّة بالصوت)","لهيك: Soin de bouche (العناية بالفم) + Surveillance de la respiration (مراقبة التنفس)"],"fr":{"t":"Pulmicort : soin de bouche après","m":"Pulmicort = corticoïde inhalé : soin de bouche, sinon candidose et dysphonie","d":["Pulmicort = budésonide corticoïde = anti-inflammatoire stéroïdien","Effet : candidose buccale","Effet : dysphonie","Donc : soin de bouche + surveillance de la respiration"]}}],"pharma:dig":[{"t":"ضد الحموضة: لو-ري-زا","m":"LO-RI-ZA ضد الحموضة: Losec وRisek إخوة (Oméprazol)، وZantac ابن عمّن (Ranitidine)","d":["Losec = Oméprazol = Inhibiteur de la pompe à proton (IPP، مثبّط مضخة البروتون)","Risek = Oméprazol = IPP","Zantac = Ranitidine = Diminue l'acide gastrique (بيخفّف حموضة المعدة)","التلاتة لـ: Ulcère gastrique (قرحة المعدة) + Reflux gastro-œsophagien (ارتجاع معدي مريئي)"],"fr":{"t":"Anti-acide : LO-RI-ZA","m":"LO-RI-ZA contre l'acide : Losec et Risek sont frères (oméprazole), Zantac est le cousin (ranitidine)","d":["Losec = oméprazole = inhibiteur de la pompe à proton (IPP)","Risek = oméprazole = IPP","Zantac = ranitidine = diminue l'acide gastrique","Les trois : ulcère gastrique + reflux gastro-œsophagien"]}},{"t":"ضد الاستفراغ: Primpéran و Zofran","m":"Primpéran للاستفراغ العادي، وZofran لاستفراغ الكيماوي والأشعة","d":["Primpéran = Métoclopramide = Antiémétique (مضاد استفراغ)","موانع Primpéran: Epilepsie (صرع)، Maladie de Parkinson (باركنسون)، Enfants moins de 1 an (أصغر من سنة)، Hémorragie gastro-intestinale (نزيف هضمي)","Zofran = Ondansétron: nausées et vomissements de la chimiothérapie (العلاج الكيماوي) ou radiothérapie (العلاج بالأشعة)","Motilium = Dompéridone: بيحرّك المعدة والمصارين، لـ Nausée et vomissement و Reflux"],"fr":{"t":"Antiémétiques : Primpéran et Zofran","m":"Primpéran pour les vomissements simples, Zofran pour ceux de la chimio et de la radio","d":["Primpéran = métoclopramide = antiémétique","Contre-indications de Primpéran : épilepsie, maladie de Parkinson, enfants de moins de 1 an, hémorragie gastro-intestinale","Zofran = ondansétron : nausées et vomissements des chimiothérapies ou de la radiothérapie","Motilium = dompéridone : stimule les contractions du tube digestif ; nausées, vomissements, reflux"]}},{"t":"Duphalac بيفتح، Spasfon بيرخّي","m":"Duphalac بيفتح الطريق (إمساك)، وSpasfon بيرخّي الشدّة (تشنج)، بس مش لحساسية القمح","d":["Duphalac = Lactulose = Anti-constipation (ضد الإمساك)، كمان بـ Alitement prolongé (تمدد طويل بالفرشة)","ممنوع Duphalac: Occlusion intestinale (انسداد معوي) و Perforation digestive (ثقب هضمي)","Spasfon = Phloroglucinol = Antispasmodique (مضاد تشنج): Colique néphrétique (مغص كلوي)، Règles douloureuses (دورة موجعة)","مانع Spasfon: Allergie au blé (حساسية القمح)"],"fr":{"t":"Duphalac ouvre, Spasfon détend","m":"Duphalac ouvre la route (constipation), Spasfon détend le spasme, sauf allergie au blé","d":["Duphalac = lactulose = anti-constipation, aussi si alitement prolongé","Contre-indications de Duphalac : occlusion intestinale, perforation digestive","Spasfon = phloroglucinol = antispasmodique : colique néphrétique, règles douloureuses","Contre-indication de Spasfon : allergie au blé"]}}],"pharma:cort":[{"t":"مراقبة الكورتيزون: و-م-س","m":"و-م-س: مع الكورتيزون منراقب الوزن والملح والسكر","d":["و = Surveillance du poids (مراقبة الوزن)","م = Surveillance du Na⁺ (مراقبة الصوديوم/الملح)","س = Surveillance de la glycémie (مراقبة السكر بالدم)","موجودين عند Decadron (Dexamethasone) و Solumédrol (Méthyl-prednisolone)","Solumédrol زيادة: Tension artérielle (الضغط) + Régime pauvre en sucre et en sel (أكل قليل سكر وملح)"],"fr":{"t":"Surveillance des corticoïdes : P-Na-G","m":"P-Na-G : sous corticoïdes, surveiller Poids, Na+ et Glycémie","d":["P = surveillance du poids","Na = surveillance du Na+","G = surveillance de la glycémie","Pour Decadron (dexaméthasone) et Solumédrol (méthylprednisolone)","Solumédrol en plus : tension artérielle + régime pauvre en sucre et en sel"]}},{"t":"الكورتيزون بينفّخ","m":"الكورتيزون بينفّخ: سكر طالع، ضغط طالع، مي محبوسة، وزن زايد، وK نازل","d":["سكر: Hyperglycémie (ارتفاع السكر)","ضغط: HTA / Hypertension artérielle (ارتفاع الضغط)","مي: Œdème (وذمة) + Rétention d'eau et du sel (احتباس المي والملح)","وزن: Prise de poids (زيادة الوزن) + Gonflement du visage (انتفاخ الوجه)","K: Baisse du taux de potassium (نقص البوتاسيوم)"],"fr":{"t":"Les corticoïdes font gonfler","m":"Le corticoïde fait gonfler : sucre en haut, tension en haut, eau retenue, poids en plus, K en bas","d":["Sucre : hyperglycémie","Tension : HTA","Eau : œdème + rétention d'eau et de sel","Poids : prise de poids + gonflement du visage","K : baisse du taux de potassium"]}}],"pharma:diab":[{"t":"Sulfamide ضد Metformin","m":"Diamicron بيوقّع السكر وبيزيد الوزن؛ Metformin بيعمل Lactique وطعمة حديد","d":["Glutril / Diamicron = Sulfamide: Hypoglycémie sévère (هبوط سكر قوي) + Prise de poids (زيادة الوزن)","Metformin / Glucophage = Biguanides: Acidose lactique (حماض لبني) إذا في Insuffisance rénale ou hépatique (فشل كلى أو كبد)","Metformin: Goût métallique (طعمة معدن بالتم) + Perte d'appétit (قلّة شهية)","الاتنين: Diabète non insulinodépendant (سكري غير معتمد عالأنسولين)","المراقبة للاتنين: Glycémie (السكر) + fonction rénale et hépatique (الكلى والكبد)"],"fr":{"t":"Sulfamide vs metformine","m":"Diamicron fait chuter le sucre et grossir ; la metformine donne l'acidose lactique et le goût de métal","d":["Glutril / Diamicron = sulfamide : hypoglycémie sévère + prise de poids","Metformine / Glucophage = biguanide : acidose lactique si insuffisance rénale ou hépatique","Metformine : goût métallique + perte d'appétit","Les deux : diabète non insulinodépendant","Surveillance des deux : glycémie + fonction rénale et hépatique"]}},{"t":"M = Metformin = Métallique","m":"M لـ M: Metformin بيترك طعمة Métallique بالتم","d":["Metformin = Glucophage = Biguanides","Effet: Goût métallique dans la bouche (طعمة معدن بالتم)","ممنوع بـ Acidocétose (حماض كيتوني)، Insuffisance rénale (فشل الكلى)، Alcoolisme (إدمان الكحول)"],"fr":{"t":"M comme Metformine, M comme Métallique","m":"M pour M : la Metformine laisse un goût Métallique","d":["Metformine = Glucophage = biguanide","Effet : goût métallique dans la bouche","Contre-indications : acidocétose, insuffisance rénale, alcoolisme"]}}],"pharma:other":[{"t":"Valium: ماشا MASHAA","m":"Valium بيقلّك MASHAA (ماشا): 6 أفعال بحرف واحد لكل وحدة","d":["M = Myorelaxante (مرخّي عضل)","A = Anxiolytique (مضاد قلق)","S = Sédative (مهدّئ)","H = Hypnotique (منوّم)","A = Anticonvulsivant (مضاد اختلاج)","A = Amnésiante (بيعمل نسيان)","لهيك منراقب: signe de dépendance (إدمان) + mémoire (الذاكرة)، ومنتجنّب l'utilisation prolongée (الاستعمال الطويل)"],"fr":{"t":"Valium : MASHAA","m":"Valium = MASHAA : six actions, une lettre chacune","d":["M = myorelaxante","A = anxiolytique","S = sédative","H = hypnotique","A = anticonvulsivante","A = amnésiante","Donc surveiller : signes de dépendance + mémoire ; éviter l'utilisation prolongée"]}},{"t":"Zyloric = صفر أسيد أوريك","m":"Zyloric = Zéro urique: بيخفّف الأسيد أوريك للنقرس والمغص الكلوي، ومعو مي كتير","d":["Zyloric = Allopurinol = Hypo-uricémiant (مخفّض حمض البول)","Indications: Maladie de goutte (النقرس)، Colique néphrétique (مغص كلوي)، Augmentation d'acide urique (ارتفاع حمض البول)","Surveillance: acide urique régulier (حمض البول) + Hydratation adéquate (شرب مي كفاية)"],"fr":{"t":"Zyloric = zéro urique","m":"Zyloric = zéro urique : baisse l'acide urique (goutte, colique néphrétique) + bien boire","d":["Zyloric = allopurinol = hypo-uricémiant","Indications : maladie de goutte, colique néphrétique, augmentation d'acide urique","Surveillance : acide urique régulier + hydratation adéquate"]}},{"t":"Cytotec = دوا الرحم","m":"Cytotec دوا الرحم: بيليّن الcol، بس خطرو Rupture utérine، وممنوع عالرحم المجروح","d":["Cytotec = Misoprostole","Indications: Interruption de la grossesse (إنهاء الحمل)، Maturation du col (تليين عنق الرحم)، Hémorragie de la délivrance (نزيف بعد الولادة)","Effet الأخطر: Rupture utérine (تمزّق الرحم)","موانع: Utérus cicatriciel (رحم فيه ندبة)، Souffrance fœtale (ضيق الجنين)، Grossesse multiple (حمل توأم)، Asthme (ربو)"],"fr":{"t":"Cytotec = le médicament de l'utérus","m":"Cytotec agit sur l'utérus : maturation du col, mais risque de rupture utérine ; pas sur utérus cicatriciel","d":["Cytotec = misoprostol","Indications : interruption de grossesse, maturation du col, hémorragie de la délivrance","Effet le plus grave : rupture utérine","Contre-indications : utérus cicatriciel, souffrance fœtale, grossesse multiple, asthme"]}}],"rea:r1":[{"t":"القيم الطبيعية: ٧.٤ – ٤٠ – ٢٤","m":"٧.٤ – ٤٠ – ٢٤ بالنص، وزيد ونقّص: ٠.٠٥ للـ pH، ٥ للـ CO₂، ٢ للـ HCO₃⁻","d":["pH (درجة الحموضة) 7.35 – 7.45 (الوسط 7.40)","PaCO₂ 35 – 45 mmHg (الوسط 40) = الجانب التنفسي","HCO₃⁻ (البيكربونات) 22 – 26 mEq/L (الوسط 24) = الجانب الأيضي","PaO₂ 80 – 100 mmHg، SaO₂ 95 – 100 %، BE −2 → +2","pH أقل من 7.35 = acidose (حماض)، أكبر من 7.45 = alcalose (قلاء)"],"fr":{"t":"Valeurs normales : 7,4 - 40 - 24","m":"7,40 - 40 - 24 au centre, puis plus ou moins 0,05 pour le pH, 5 pour le CO2, 2 pour les HCO3-","d":["pH 7,35 à 7,45 (centre 7,40)","PaCO2 35 à 45 mmHg (centre 40) = versant respiratoire","HCO3- 22 à 26 mEq/L (centre 24) = versant métabolique","PaO2 80 à 100 mmHg, SaO2 95 à 100 %, BE de -2 à +2","pH sous 7,35 = acidose ; au-dessus de 7,45 = alcalose"]}},{"t":"القيء قلاء، الإسهال حماض","m":"من فوق بيطلع الحامض = قلاء؛ من تحت بتطلع البيكربونات = حماض","d":["Alcalose métabolique (القلاء الأيضي): التقيّؤ المتكرّر أو الشفط المعدي، مدرّات البول، مضادّات الحموضة، نقص البوتاسيوم","Acidose métabolique (الحماض الأيضي): الإسهال الشديد، الحماض الكيتوني السكّري، حماض اللاكتات بالصدمة، الفشل الكلوي","علامة الحماض الأيضي: Kussmaul (تنفّس عميق سريع)"],"fr":{"t":"Vomir = alcalose, diarrhée = acidose","m":"Par le haut on perd l'acide : alcalose ; par le bas on perd les bicarbonates : acidose","d":["Alcalose métabolique : vomissements répétés ou aspiration gastrique, diurétiques, antiacides, hypokaliémie","Acidose métabolique : diarrhée sévère, acidocétose diabétique, acidose lactique du choc, insuffisance rénale","Signe de l'acidose métabolique : respiration de Kussmaul"]}},{"t":"العيّنة الشريانية: ألن، بلا فقاعات، تلج، ٥ أو ١٠","m":"ألن أوّل، محقنة مهبّرنة بلا فقاعات، عالتلج فوراً، وضغط ٥ دقايق (١٠ مع مميّع)","d":["قبل: test d'Allen (اختبار ألن) للـ artère radiale + نسجّل الـ FiO₂ والحرارة","أثناء: محقنة فيها héparine، نطلّع فقاعات الهوا فوراً ونسدّها ونحرّكها برفق","بعد: نبعتها فوراً أو بالتلج","الضغط ٥ دقايق، و١٠ مع anticoagulants (مميّعات)","héparine زيادة بتنزّل الـ pH وبتخفّف العيّنة"],"fr":{"t":"Prélèvement artériel : Allen, sans bulles, glace, 5 ou 10","m":"Allen d'abord, seringue héparinée sans bulles, glace tout de suite, compression 5 min (10 sous anticoagulant)","d":["Avant : test d'Allen sur l'artère radiale, noter la FiO2 et la température","Pendant : seringue héparinée, chasser les bulles d'air, boucher et rouler doucement","Après : envoyer tout de suite ou dans la glace","Compression 5 min, 10 min sous anticoagulants","Trop d'héparine baisse le pH et dilue l'échantillon"]}}],"rea:r2":[{"t":"الدفاعات التلاتة: بَرَكة","m":"بَرَكة = بيكاربونات (ثواني)، رية (دقايق)، كلية (أيام)","d":["ب = البيكاربونات (HCO₃⁻): ثواني","ر = الرئتين: دقائق","ك = الكليتين: أيام (الكلية بتحتفظ بالـ HCO₃⁻ للتوازن)"],"fr":{"t":"Les 3 défenses : la plus rapide d'abord","m":"Bicarbonates en secondes, Poumons en minutes, Reins en jours : B-P-R","d":["B = Bicarbonates (HCO3-) : secondes","P = Poumons : minutes","R = Reins : jours (le rein garde les HCO3-)"]}},{"t":"ROME: عكس ولا نفس الاتجاه؟","m":"ROME: Respiratoire = Opposé (عكس)، Métabolique = Égal (نفس الاتجاه)","d":["الحماض التنفّسي (Acidose respiratoire): pH ↓ وPaCO₂ ↑ (احتباس CO₂ من نقص التهوية)","القلاء التنفّسي (Alcalose respiratoire): pH ↑ وPaCO₂ ↓ (فرط تهوية)","الحماض الأيضي (Acidose métabolique): pH ↓ وHCO₃⁻ ↓ (سكّري، فشل كلوي، إسهال حاد؛ تنفّس عميق)","القلاء الأيضي (Alcalose métabolique): pH ↑ وHCO₃⁻ ↑ (تنفّس بطيء، ارتباك)","أوّل شي منتطلّع عالـ pH"],"fr":{"t":"ROME : opposé ou égal ?","m":"ROME : Respiratoire = Opposé, Métabolique = Égal (même sens)","d":["Acidose respiratoire : pH bas, PaCO2 haute (rétention de CO2, hypoventilation)","Alcalose respiratoire : pH haut, PaCO2 basse (hyperventilation)","Acidose métabolique : pH bas, HCO3- bas (diabète, insuffisance rénale, diarrhée ; respiration profonde)","Alcalose métabolique : pH haut, HCO3- haut (respiration lente, confusion)","Toujours regarder le pH en premier"]}},{"t":"التعويض: شوف الـ pH أوّل","m":"pH طبيعي = كلّي؛ pH عاطل والتنين عاطلين = جزئي؛ واحد بس عاطل = غير معوَّض","d":["معوَّض كلياً: الـ pH طبيعي والمؤشّرات غير طبيعية","معوَّض جزئياً: الـ pH غير طبيعي والمؤشّرات غير طبيعية","غير معوَّض: الـ pH غير طبيعي، مؤشّر غير طبيعي والتاني طبيعي","والعيّنة: دم من الـ artère (الشريان)، مش من الوريد"],"fr":{"t":"La compensation : regarder le pH d'abord","m":"pH normal = totale ; pH anormal et les deux anormaux = partielle ; un seul anormal = non compensé","d":["Totalement compensé : pH normal, paramètres anormaux","Partiellement compensé : pH anormal, paramètres anormaux","Non compensé : pH anormal, un paramètre anormal et l'autre normal","Prélèvement : sang artériel, pas veineux"]}}],"rea:r3":[{"t":"٣ عائلات: Cristal بيذوب، Colle بيلزق، وأكل","m":"Cristalloïdes = كريستال زغير بيذوب؛ Colloïdes = colle (غرا) بيضلّ بالأوعية؛ والمغذّية = أكل","d":["Cristalloïdes (المحاليل البلّورية): جزيئات صغيرة بتذوب بالماء","Colloïdes (المحاليل الغروية): جزيئات كبيرة بتبقى بالأوعية أطول: Plasma، الدم، Albumine","Colloïdes للنزيف، الصدمة النزفية، الحروق، نقص بروتين الدم؛ ممنوعة بالـ Hypervolémie (فرط الحجم) والوذمات","المغذّية: Aminoplasma (أمينو) وIntralipide (lipide = دهن) ← ممنوعة بفرط الدهون وفشل كبدي حاد"],"fr":{"t":"Trois familles : cristal, colle et repas","m":"Cristalloïdes = petit cristal qui se dissout ; Colloïdes = colle qui reste dans les vaisseaux ; Nutritifs = repas","d":["Cristalloïdes : petites molécules dissoutes dans l'eau","Colloïdes : grosses molécules qui restent plus longtemps dans les vaisseaux : plasma, sang, albumine","Colloïdes : hémorragie, choc hémorragique, brûlures, hypoprotéinémie ; contre-indiqués si hypervolémie ou œdèmes","Nutritifs : Aminoplasma et Intralipide ; contre-indiqués si hyperlipidémie ou insuffisance hépatique aiguë"]}},{"t":"الغلوكوز: ١٠ فوق، ٥ بالنص، ٢.٥ تحت","m":"Glucose 10% = Hyper، Dextrose 5% = Iso، Glucose 2.5% = Hypo","d":["Hypertonique (مرتفع التوتّر): NaCl 20%، Mannitol 10–20%، Glucose 10%","Isotonique (متساوي التوتّر): Dextrose 5% ← تعويض سوائل، دعم الضغط بالصدمة، حامل للأدوية","Hypotonique (منخفض التوتّر): Eau distillée (مي مقطّرة)، Glucose 2.5%"],"fr":{"t":"Le glucose : 10 en haut, 5 au milieu, 2,5 en bas","m":"Glucose 10 % = hyper, Dextrose 5 % = iso, Glucose 2,5 % = hypo","d":["Hypertonique : NaCl 20 %, Mannitol 10 à 20 %, Glucose 10 %","Isotonique : Dextrose 5 %, remplissage, soutien de la tension dans le choc, vecteur de médicaments","Hypotonique : eau distillée, Glucose 2,5 %"]}},{"t":"Hyper وHypo: مراية بعض","m":"Hyper بيعالج HTIC ونقص الصوديوم؛ Hypo ممنوع بنقص الصوديوم والوذمة الدماغية","d":["Hypertonique: دواعي = ارتفاع ضغط الجمجمة + نقص الصوديوم الحاد؛ موانع = القصور الكلوي","Hypotonique: دواعي = الجفاف الخلوي + فرط الصوديوم؛ موانع = انخفاض الصوديوم + الوذمة الدماغية","يعني يلي بيعالجو الـ Hyper، ممنوع فيه الـ Hypo","Isotonique (Dextrose 5%): موانع = فشل القلب، فشل الكلى"],"fr":{"t":"Hyper et hypo : en miroir","m":"L'hyper traite l'HTIC et l'hyponatrémie ; l'hypo est interdit dans l'hyponatrémie et l'œdème cérébral","d":["Hypertonique : indications = HTIC, hyponatrémie aiguë ; contre-indication = insuffisance rénale","Hypotonique : indications = déshydratation cellulaire, hypernatrémie ; contre-indications = hyponatrémie, œdème cérébral","Ce que l'hyper soigne, l'hypo l'aggrave","Isotonique (Dextrose 5 %) : contre-indiqué en insuffisance cardiaque et rénale"]}}],"rea:r4":[{"t":"٣ صدمات: ناقص، مسكّر، فلتان","m":"الدم ناقص (hypovolémique)، الطريق مسكّر (obstructif)، الأعصاب فلتت (neurogène)","d":["ناقص = Choc hypovolémique (نقص الحجم): نزيف، قيء وإسهال، حروق واسعة، جفاف شديد","مسكّر = Choc obstructif (انسدادي): صمّة رئوية كبيرة، انصباب قلبي، استرواح صدري ضاغط","فلتان = Choc neurogène (عصبي): إصابة النخاع الشوكي، التخدير الشوكي أو فوق الجافية، أدوية عصبية","acide lactique (حمض اللاكتيك) مرتفع = صدمة، بكل الأنواع"],"fr":{"t":"3 chocs : manque, bouchon, lâchage","m":"Le sang manque (hypovolémique), la route est bouchée (obstructif), les nerfs lâchent (neurogène)","d":["Hypovolémique : hémorragie, vomissements et diarrhée, brûlures étendues, déshydratation sévère","Obstructif : embolie pulmonaire massive, épanchement péricardique, pneumothorax compressif","Neurogène : lésion de la moelle épinière, rachianesthésie ou péridurale, médicaments neurologiques","Acide lactique élevé = choc, quel que soit le type"]}},{"t":"العصبية هيّي الشاذّة","m":"كلّن سريع وبارد، إلا العصبية: قلب بطيء وجلد ناشف ودافي","d":["نقص الحجم: قلب تسارع، جلد بارد وشاحب ومتعرّق","الانسدادية: قلب تسارع، جلد بارد ومتعرّق","العصبية: bradycardie (بطء القلب)، جلد جاف ودافي","علاج العصبية: سوائل وريدية + Noradrénaline + Atropine + تثبيت العمود الفقري"],"fr":{"t":"Le neurogène est l'exception","m":"Tous rapides et froids, sauf le neurogène : cœur lent, peau sèche et chaude","d":["Hypovolémique : tachycardie, peau froide, pâle, moite","Obstructif : tachycardie, peau froide et moite","Neurogène : bradycardie, peau sèche et chaude","Traitement du neurogène : solutés IV, noradrénaline, atropine, immobilisation du rachis"]}},{"t":"مراقبة كل صدمة: ٥ عيون","m":"ضغط ونبض، وعي، بول، داخل وطالع، وO₂: نفس الـ ٥ بكل الصدمات","d":["مراقبة العلامات الحيوية","مراقبة الوعي","مراقبة الـ diurèse (كمّية البول)","مراقبة السوائل الداخلة والخارجة","إعطاء O₂ (أكسجين)، وأوّل شي: نوقّف أو نعالج السبب"],"fr":{"t":"Surveillance de tout choc : 5 yeux","m":"Signes vitaux, conscience, diurèse, entrées/sorties, oxygène : les mêmes 5 pour chaque choc","d":["Surveiller les signes vitaux","Surveiller la conscience","Surveiller la diurèse","Surveiller les entrées et sorties","Donner de l'oxygène ; d'abord arrêter ou traiter la cause"]}}],"rea:r5":[{"t":"VCV = الحجم، PCV = الضغط، PSV = المريض بيبلّش","m":"VCV: حجم ثابت بغضّ النظر عن جهد المريض. PCV: ضغط ثابت أثناء الشهيق والحجم متغيّر. PSV: المريض بيبلّش الشهيق والجهاز بيعزّز","d":["VCV موانع: التليّف الرئوي، Pneumothorax","PCV دواعي: حروق، وذمة رئوية، ربو حاد. موانع: انسداد رئوي مزمن (COPD)","PSV دواعي: الفطام (sevrage). موانع: فقدان وعي عميق"],"fr":{"t":"VCV = le volume, PCV = la pression, PSV = le patient déclenche","m":"VCV : volume fixe quel que soit l'effort. PCV : pression fixe à l'inspiration, volume variable. PSV : le patient déclenche l'inspiration et le respirateur renforce","d":["VCV contre-indications : fibrose pulmonaire, Pneumothorax","PCV indications : brûlés, œdème pulmonaire, asthme aigu. Contre-indication : BPCO (COPD)","PSV indication : sevrage. Contre-indication : coma profond"]}},{"t":"Bi = اتنين، C = Continu","m":"BiPAP = ضغطين (أعلى بالشهيق، أقل بالزفير)، CPAP = ضغط واحد ثابت ومستمر","d":["الأنبوب بينشال لمّا: FiO2 أقل من 40% و SpO2 أعلى من 92%، سعال وبلع طبيعي، استجابة للأوامر، إيقاف الـ Sédation","VNI ممنوعة: توقّف التنفس، مجرى هوا مش محمي، وعي مضطرب بشدّة، انسداد علوي، دورة دموية مش مستقرة"],"fr":{"t":"Bi = deux, C = Continu","m":"BiPAP = deux pressions (plus haute à l'inspiration, plus basse à l'expiration), CPAP = une seule pression fixe et continue","d":["On extube quand : FiO2 inférieure à 40 % et SpO2 supérieure à 92 %, toux et déglutition normales, répond aux ordres, sédation arrêtée","VNI contre-indiquée : arrêt respiratoire, voies aériennes non protégées, conscience très altérée, obstruction haute, instabilité hémodynamique"]}}],"geri:g1":[{"t":"أمراض الجهاز العصبي عند المسن: الـ5A","m":"5A: ما بيعرف يعمل، ما بيعرف مين، ما بيحكي، ما بيتذكّر، وما بيمشي ثابت","d":["A = Apraxie (صعوبة الحركات الإرادية): ما بيقدر يستعمل الأدوات أو يعمل مهامه اليومية","A = Agnosie (فقدان التعرّف): ما بيميّز الوجوه أو الأشياء أو الأصوات مع إنو حواسو سليمة","A = Aphasie (فقدان اللغة): صعوبة بالكلام أو بالفهم","A = Amnésie (فقدان الذاكرة): بينسى أحداث الماضي أو ما بيتذكّر معلومات جديدة","A = Ataxie (فقدان التنسيق الحركي): مشية مش ثابتة، صعوبة يمسك الأشياء، وقعات متكرّرة","الأسباب المشتركة يلّي بتتكرّر: إصابات الدماغ، الخرف، السكتة الدماغية"],"fr":{"t":"Troubles neurologiques du sujet âgé : les 5 A","m":"5 A : il ne sait plus faire, plus reconnaître, plus parler, plus se souvenir, plus marcher droit","d":["A = Apraxie : difficulté des gestes volontaires, ne sait plus utiliser les objets ni faire ses tâches","A = Agnosie : ne reconnaît plus visages, objets ou sons, alors que les sens sont intacts","A = Aphasie : perte du langage, difficulté à parler ou à comprendre","A = Amnésie : perte de mémoire, oubli du passé ou des informations nouvelles","A = Ataxie : perte de coordination, marche instable, difficulté à saisir, chutes répétées","Causes qui reviennent : lésions cérébrales, démence, AVC"]}},{"t":"نظريات الشيخوخة الست بقصة وحدة","m":"الساعة الجينية قصرت، الآلة تآكلت، الجذور الحرة هجمت، المناعة ضعفت، الهرمونات تغيّرت، والصيانة ما لحقت","d":["الساعة = Théorie génétique / Cellular Clock (البرمجة الجينية): التيلوميرات (Telomeres) بتقصر مع كل انقسام","الآلة = Théorie de l’usure – Wear and Tear (التآكل): الجسم متل آلة بتتآكل مع السنين","الجذور = Théorie des radicaux libres / Oxidative Stress (الجذور الحرة والإجهاد التأكسدي): بتأذي الخلايا وDNA","المناعة = Théorie immunologique (الجهاز المناعي): كفاءة المناعة بتتراجع فبتكتر العدوى","الهرمونات = Théorie hormonale (الهرمونية): تغيّر إفراز الهرمونات بيأثر عالاستقلاب والعضل والعظم","الصيانة = Disposable Soma Theory (الصيانة الحيوية): موارد الجسم محدودة فالإصلاح بيقلّ","الخلاصة: الشيخوخة Multifactorielle (متعدّدة العوامل)"],"fr":{"t":"Les 6 théories du vieillissement en une histoire","m":"L'horloge raccourcit, la machine s'use, les radicaux attaquent, l'immunité baisse, les hormones changent, le soma lâche","d":["Horloge = théorie génétique / Cellular Clock : les télomères raccourcissent à chaque division","Machine = théorie de l'usure (Wear and Tear) : le corps s'use comme une machine","Radicaux = théorie des radicaux libres / stress oxydatif : lésions des cellules et de l'ADN","Immunité = théorie immunologique : baisse de l'efficacité immunitaire, plus d'infections","Hormones = théorie hormonale : sécrétion modifiée, effets sur métabolisme, muscles, os","Soma = Disposable Soma Theory : ressources limitées, la réparation diminue","Conclusion : le vieillissement est multifactoriel"]}},{"t":"العضل والعظم والمفصل: SOO","m":"SOO: عضل بيذوب، عضم بيرقّ، مفصل بيتآكل","d":["S = Sarcopenia (نقص الكتلة والقوة العضلية)","O = Osteoporosis (نقص كثافة العظام) → هشاشة وخطر كسور","O = Osteoarthritis (تيبّس المفاصل وتآكل الغضاريف)","وفوقهن: ضعف الأربطة والأوتار → مرونة أقل وإصابات أكتر"],"fr":{"t":"Muscles, os, articulations : SOO","m":"SOO : le muscle fond, l'os s'amincit, l'articulation s'use","d":["S = Sarcopenia : perte de masse et de force musculaires","O = Osteoporosis : baisse de densité osseuse, risque de fractures","O = Osteoarthritis : raideur articulaire et usure du cartilage","En plus : ligaments et tendons plus faibles, moins de souplesse, plus de blessures"]}}],"geri:g2":[{"t":"اختبارات المعرفة والمزاج بالأرقام","m":"MMSE وMoCA من 30، MoCA تحت 26 = خلل بكّير، Mini-Cog = 3 كلمات + ساعة بأقل من 3 دقايق","d":["MMSE (Mini Mental State Examination): العلامة الكاملة 30، كل ما نزلت كل ما زاد احتمال الخرف","Mini-Cog: أقل من 3 دقايق، جزأين: تذكّر 3 كلمات + رسم ساعة (Clock Drawing Test)","MoCA (Montreal Cognitive Assessment): من 30، أقل من 26 = خلل معرفي مبكر، أشمل وأدق","GDS (Geriatric Depression Scale): للاكتئاب، أسئلة نعم/لا، نسخة 15 ونسخة 30 سؤال","انتبه: بالـ GDS العكس، كل ما عليت العلامة كل ما زاد احتمال الاكتئاب"],"fr":{"t":"Tests cognitifs et humeur en chiffres","m":"MMSE et MoCA sur 30, MoCA sous 26 = trouble précoce, Mini-Cog = 3 mots + horloge en moins de 3 minutes","d":["MMSE : note maximale 30, plus elle baisse, plus la démence est probable","Mini-Cog : moins de 3 minutes, 2 parties : rappel de 3 mots + test de l'horloge","MoCA : sur 30, moins de 26 = trouble cognitif précoce, plus complet et plus précis","GDS (Geriatric Depression Scale) : dépression, questions oui/non, version 15 ou 30 questions","Attention : pour la GDS c'est l'inverse, plus le score est haut, plus la dépression est probable"]}},{"t":"التقييم الوظيفي: جسمي وبيتي","m":"الأساسي = جسمي (آكل، ألبس، أتحمّم، حمّام، أتنقّل، إخراج)؛ المعقّد = بيتي (طبخ، تنضيف، تسوّق، دوا، تلفون، مصاري)","d":["أنشطة الحياة الأساسية: الأكل، اللبس، الاستحمام، استعمال المرحاض، التنقّل، التحكّم بالإخراج","الأنشطة المعقّدة: الطهي، تنظيف البيت، التسوّق، إدارة الأدوية، استعمال الهاتف، إدارة الأموال","الهدف: نعرف إذا بدّو مساعدة جزئية، مساعدة كاملة، أو جهاز مساعد متل عكّاز أو Walker (مشّاية)"],"fr":{"t":"Évaluation fonctionnelle : mon corps et ma maison","m":"Activités de base = mon corps (manger, s'habiller, se laver, toilettes, se déplacer, continence) ; complexes = ma maison","d":["Activités de base : manger, s'habiller, se laver, utiliser les toilettes, se déplacer, contrôler l'élimination","Activités complexes : cuisiner, nettoyer la maison, faire les courses, gérer les médicaments, le téléphone, l'argent","But : savoir s'il faut une aide partielle, une aide totale ou une aide technique (canne, Walker)"]}},{"t":"تحاليل البروتين وسوء التغذية: APTT + CRP","m":"البروتين؟ احفظ الحروف APTT، وزيد عليهن CRP لتفهم الألبومين","d":["A = Albumin (الألبومين)","P = Prealbumin (البري ألبومين)","T = Total Protein (البروتين الكلي)","T = Transferrin (الترانسفرين)","+ CRP: للكشف عن الالتهاب، لأنو الالتهاب بيأثّر على مستوى الألبومين"],"fr":{"t":"Bilan protéique de la dénutrition : APTT + CRP","m":"Les protéines ? Retiens les lettres APTT, et ajoute la CRP pour interpréter l'albumine","d":["A = Albumine","P = Préalbumine","T = Protéines totales","T = Transferrine","+ CRP : détecte l'inflammation, qui modifie le taux d'albumine"]}}],"geri:g3":[{"t":"أنواع الجفاف الثلاثة: شو راح؟","m":"سوا سوا = متساوي، راح الملح = ناقص التوتر، راحت المي = زائد التوتر (الأشيع عند المسن)","d":["متساوي التوتر: بيروح الماء والأملاح بنسب متساوية، غالباً من الإسهال أو القيء","ناقص التوتر (نقص الصوديوم): بيروح الملح أكتر من المي، من مي كتير بلا تعويض أملاح أو من المدرّات","زائد التوتر (نقص الماء): بتروح المي أكتر من الملح، الأشيع عند المسن لأنو ما بيشرب كفاية"],"fr":{"t":"Les 3 types de déshydratation : qu'est-ce qui part ?","m":"Les deux ensemble = isotonique ; le sel part = hypotonique ; l'eau part = hypertonique (la plus fréquente chez l'âgé)","d":["Isotonique : perte d'eau et de sels en proportions égales, souvent diarrhée ou vomissements","Hypotonique (manque de sodium) : plus de sel perdu que d'eau, trop d'eau sans sels ou diurétiques","Hypertonique (manque d'eau) : plus d'eau perdue que de sel, la plus fréquente chez l'âgé qui boit peu"]}},{"t":"حرارة المسن بالأرقام: 35، 38، 40","m":"تحت 35 = برد خطر، 38–39.5 = حمى (باراسيتامول)، فوق 40 وجلد ناشف = ضربة شمس (لا باراسيتامول)","d":["تحت 35 درجة، أو ارتجاف شديد، أو اضطراب وعي: بلّغ الطبيب، ودفّي تدريجياً","38 – 39.5 درجة أو رعشة أو تغيّر بالوعي: بلّغ الطبيب، كمادات مي فاترة وخافض حرارة موصوف متل الباراسيتامول","فوق 40 درجة مع جلد أحمر وناشف (التعرّق وقف): ضربة شمس","بضربة الشمس ممنوع خافض الحرارة لأنها مش حمى عادية"],"fr":{"t":"La température de l'âgé en chiffres : 35, 38, 40","m":"Sous 35 = froid dangereux ; 38–39,5 = fièvre (paracétamol) ; plus de 40 et peau sèche = coup de chaleur (pas de paracétamol)","d":["Sous 35 degrés, frissons intenses ou trouble de conscience : prévenir le médecin, réchauffer progressivement","38 à 39,5 degrés, frissons ou conscience altérée : prévenir le médecin, compresses tièdes, antipyrétique prescrit","Plus de 40 degrés avec peau rouge et sèche (la sudation s'arrête) : coup de chaleur","Coup de chaleur : aucun antipyrétique, ce n'est pas une fièvre ordinaire"]}},{"t":"إسعاف ضربة الشمس: ظلّل، شلّح، برّد، شرّب، اتّصل","m":"ظلّل، شلّح، برّد، شرّب، راقب، اتّصل، وما تعطي خافض حرارة","d":["ظلّل: انقلو لمكان بارد أو مظلّل بعيد عن الشمس","شلّح: خفّف الملابس التقيلة","برّد: تدريجياً بمي فاترة أو كمادات رطبة أو مروحة خفيفة، وكمادات باردة عالإبطين والرقبة والفخذين","شرّب: رشفات زغيرة مي إذا واعي وما عندو صعوبة بلع","راقب: التنفّس والنبض ومستوى الوعي","اتّصل: بالطبيب أو الإسعاف فوراً"],"fr":{"t":"Coup de chaleur : ombre, déshabiller, refroidir, appeler","m":"Ombre, déshabiller, refroidir, faire boire, surveiller, appeler, et jamais d'antipyrétique","d":["Ombre : transporter dans un endroit frais ou ombragé","Déshabiller : enlever les vêtements lourds","Refroidir : progressivement, eau tiède, compresses humides, ventilateur léger ; froid aux aisselles, cou, cuisses","Faire boire : petites gorgées d'eau s'il est conscient et avale bien","Surveiller : respiration, pouls, conscience","Appeler : le médecin ou les secours immédiatement"]}}],"geri:g4":[{"t":"أسباب السقوط: جسمو، دواه، بيتو، نفسيتو","m":"المسن بيوقع من 4 جهات: جسمو، دواه، بيتو، ونفسيتو","d":["جسمو (جسدية): ضعف عضل الإجرين، باركنسون والخرف والجلطات، النظر، Orthostatic Hypotension (هبوط الضغط عند الوقوف)، الأذن والتوازن، المفاصل","دواه (دوائية): مهدّئات ومنوّمات، مضادات اكتئاب وذهان، أدوية الضغط والمدرّات، أدوية بتدوّخ","بيتو (بيئية): أرض زلقة، ضو ضعيف، سجّاد مش مثبّت، ما في درابزين، فوضى وأثاث كتير","نفسيتو (نفسية-اجتماعية): الخوف من الوقعة، العزلة وقلّة النشاط، ما حدا يراقبو"],"fr":{"t":"Causes des chutes : les 4 C","m":"4 C : Corps, Cachets, Cadre de vie, Craintes","d":["Corps : faiblesse des jambes, Parkinson, démence, AVC, troubles visuels, hypotension orthostatique, oreille, articulations","Cachets : sédatifs et somnifères, antidépresseurs et antipsychotiques, antihypertenseurs et diurétiques","Cadre de vie : sol glissant, éclairage faible, tapis non fixés, pas de rampe, encombrement","Craintes : peur de tomber, isolement, peu d'activité, absence de surveillance"]}},{"t":"المشاكل النفسية عند المسن: 4 رفوف","m":"4 رفوف: ذهاني (هذيان، خرف، هلوسات)، نفسي (اكتئاب، قلق، نوم)، سلوكي، اجتماعي","d":["ذهانية: الهذيان (اضطراب مفاجئ بالوعي)، الخرف (تراجع تدريجي)، الضلالات والهلوسات","نفسية: الاكتئاب، القلق، اضطرابات النوم","سلوكية: انفعال سريع وعدوانية كلامية، قلّة أكل أو إفراط، عزلة","اجتماعية: الوحدة، الاعتماد على غيرو، الإهمال أو سوء المعاملة، تراجع دورو بالعيلة","تفريق سريع: الهذيان فجأة (التهاب أو دوا)، الخرف تدريجي"],"fr":{"t":"Problèmes psychiques de l'âgé : 4 étagères","m":"4 étagères : psychotique (délire, démence, hallucinations), psychique (dépression, anxiété, sommeil), comportement, social","d":["Psychotiques : délirium (trouble brutal de la conscience), démence (déclin progressif), idées délirantes et hallucinations","Psychiques : dépression, anxiété, troubles du sommeil","Comportementaux : irritabilité et agressivité verbale, perte ou excès d'appétit, isolement","Sociaux : solitude, dépendance, négligence ou maltraitance, perte du rôle familial","Astuce : le délirium est brutal (infection ou médicament), la démence est progressive"]}}],"geri:g5":[{"t":"الفصال، النقرس، الهشاشة: مين بيوجع إيمتى؟","m":"الفصال بيوجع مع الحركة، النقرس فجأة وبالليل بإصبع الإجر، والهشاشة ساكتة لحتى تنكسر","d":["Osteoarthritis (الفصال العظمي): وجع بيزيد مع الحركة وبيخفّ مع الراحة، تيبّس صباحي أقل من 30 دقيقة، Crepitus (طقطقة)","Gout (النقرس): نوبة وجع حاد ومفاجئ، غالباً بإصبع الإجر الكبير، احمرار وسخونة وانتفاخ، بيزيد بالليل","Osteoporosis (هشاشة العظام): غالباً بلا أعراض لحتى يصير كسر"],"fr":{"t":"Arthrose, goutte, ostéoporose : qui fait mal quand ?","m":"L'arthrose fait mal au mouvement, la goutte d'un coup la nuit au gros orteil, l'ostéoporose se tait jusqu'à la fracture","d":["Arthrose : douleur qui augmente au mouvement et se calme au repos, raideur matinale de moins de 30 minutes, craquements","Goutte : crise de douleur aiguë et brutale, souvent au gros orteil, rougeur, chaleur, gonflement, pire la nuit","Ostéoporose : souvent sans symptômes jusqu'à une fracture"]}},{"t":"علاج النقرس: النوبة والمنع","m":"النوبة: NCC (NSAIDs، Colchicine، Cortisone)، والمنع على المدى الطويل: AF (Allopurinol، Febuxostat)","d":["N = NSAIDs (مضادات الالتهاب)","C = Colchicine (الكولشيسين)","C = Cortisone (الكورتيزون) ببعض الحالات","A = Allopurinol و F = Febuxostat: خافضات لليوريك لمنع الانتكاس","ومع الدوا: سوائل كتير، أقل لحمة حمرا ومأكولات بحرية، وزن صحي، بلا كحول"],"fr":{"t":"Traitement de la goutte : crise et prévention","m":"Crise : NCC (AINS, Colchicine, Cortisone) ; à long terme : AF (Allopurinol, Febuxostat)","d":["N = AINS (NSAIDs, anti-inflammatoires)","C = Colchicine","C = Cortisone dans certains cas","A = Allopurinol et F = Febuxostat : hypo-uricémiants contre les récidives","En plus : boire beaucoup, moins de viande rouge et de fruits de mer, poids sain, pas d'alcool"]}},{"t":"علامات هشاشة العظام: ضهر بيوجع، بينحني، بيقصر، بينكسر","m":"الهشاشة: ضهر بيوجع، بينحني، بيقصر، وبينكسر من ولا شي","d":["بيوجع: ألم مزمن بالضهر","بينحني: Kyphosis (انحناء الضهر)","بيقصر: نقص الطول مع الوقت","بينكسر: كسور متكرّرة من إصابات بسيطة","العلاج: كالسيوم وفيتامين D، Bisphosphonates، رياضة خفيفة وتمارين حمل وزن، والوقاية من السقوط"],"fr":{"t":"Ostéoporose : douleur, dos courbé, taille perdue, fracture","m":"Ostéoporose : le dos fait mal, se courbe, on rapetisse, et ça casse pour un rien","d":["Mal : douleur chronique du dos","Courbé : cyphose","Rapetisse : perte de taille avec le temps","Casse : fractures répétées après des traumatismes minimes","Traitement : calcium et vitamine D, bisphosphonates, exercice léger en charge, prévention des chutes"]}}],"geri:g6":[{"t":"مراحل قرحة الفراش: لون، فقاعة، دهن، عضم","m":"1 لون، 2 فقاعة، 3 دهن، 4 عضم","d":["المرحلة 1: تغيّر لون الجلد (أحمر أو أزرق)، بارد أو دافي، ألم موضعي","المرحلة 2: تشقّقات أو فقاعات، فقدان جزئي للطبقة العليا من الجلد","المرحلة 3: فقدان كامل للجلد ويبين النسيج الدهني","المرحلة 4: تلف عميق للعضل والأوتار والعظم، وخطر عدوى شديدة","والممرضة: تغيير الوضعية كل ساعتين وفحص الجلد كل يوم"],"fr":{"t":"Stades de l'escarre : couleur, bulle, graisse, os","m":"1 couleur, 2 bulle, 3 graisse, 4 os","d":["Stade 1 : changement de couleur (rouge ou bleu), peau froide ou chaude, douleur locale","Stade 2 : fissures ou bulles, perte partielle de la couche superficielle","Stade 3 : perte complète de la peau, tissu graisseux visible","Stade 4 : atteinte profonde des muscles, tendons, os, risque d'infection grave","Rôle infirmier : changer de position toutes les 2 heures, inspecter la peau chaque jour"]}},{"t":"أماكن قرحة الفراش من تحت لفوق","m":"من تحت لفوق: كعب، عجز، ورك، كوع، كتف","d":["الكعبين","العجزية (أسفل الضهر)","الوركين","المرفقان (الكوع)","الكتفين","القاعدة: كل منطقة عظمية عليها ضغط مستمر"],"fr":{"t":"Sites de l'escarre de bas en haut","m":"De bas en haut : talons, sacrum, hanches, coudes, épaules","d":["Talons","Sacrum (bas du dos)","Hanches","Coudes","Épaules","Règle : toute zone osseuse soumise à une pression continue"]}},{"t":"الاستلقاء الطويل بيسرق 6","m":"الاستلقاء بيسرق 6: دم بيبطّى، عضم بيرقّ، عضل بيدوب، بروتين بينهدم، دم بيفقر، مناعة بتنزل","d":["دم بيبطّى: تدفّق الدم بيقلّ → خطر خثرات وجفاف","عضم بيرقّ: Osteoclast (ناقضات العظم) بتنشط → ترقّق عظم وكالسيوم بالبول","عضل بيدوب: الكتلة والقوة العضلية بتقلّ (ضمور)","بروتين بينهدم: Hypercatabolism (الهدم البروتيني) → سوء تغذية","دم بيفقر: إنتاج الكريات الحمرا بيقلّ → فقر دم","مناعة بتنزل: كترة الإنتانات"],"fr":{"t":"L'alitement prolongé vole 6 choses","m":"L'alitement vole 6 : sang ralenti, os aminci, muscle fondu, protéines cassées, globules rouges en baisse, immunité en baisse","d":["Sang ralenti : baisse du débit sanguin, risque de caillots et de déshydratation","Os aminci : ostéoclastes activés, ostéoporose et calcium urinaire augmenté","Muscle fondu : baisse de masse et de force (amyotrophie)","Protéines cassées : hypercatabolisme, dénutrition","Globules rouges en baisse : anémie","Immunité en baisse : infections fréquentes"]}}],"geri:g7":[{"t":"أنواع السلس البولي: بيكحّ، بيركض، بيفيض، ما بيلحق","m":"بيكحّ = Stress، بيركض = Urge، بيفيض = Overflow، ما بيلحق يوصل = Functional، كحّ + ركض = مختلط","d":["Stress Incontinence (الجهدي): مع السعال أو الضحك أو حمل شي تقيل، السبب ضعف عضل قاع الحوض","Urge Incontinence (الإلحاحي): رغبة مفاجئة وقوية بلا سيطرة، السبب فرط نشاط المثانة","Overflow (الفيضي): تسرّب مستمر من امتلاء المثانة، السبب انسداد أو احتباس بول","Functional (الوظيفي): المثانة طبيعية بس ما بيقدر يوصل عالحمّام (حركة أو إدراك)","المختلط: جهدي + إلحاحي، الأشيع عند المسن"],"fr":{"t":"Incontinence urinaire : tousse, court, déborde, n'arrive pas","m":"Tousse = effort, court = urgence, déborde = regorgement, n'arrive pas = fonctionnelle, tousse + court = mixte","d":["Effort (Stress) : à la toux, au rire, en portant une charge ; cause : faiblesse du plancher pelvien","Urgence (Urge) : envie brutale et forte sans contrôle ; cause : hyperactivité vésicale","Regorgement (Overflow) : fuite continue par vessie trop pleine ; cause : obstacle ou rétention","Fonctionnelle : vessie normale mais n'arrive pas aux toilettes (mobilité ou cognition)","Mixte : effort + urgence, la plus fréquente chez l'âgé"]}},{"t":"الإمساك عند المسن: أقل من 3 والأدوية يلّي بتسكّر","m":"أقل من 3 مرّات بالجمعة = إمساك؛ أدوية بتسكّر: أفيون، كولين، اكتئاب، حديد، مدرّ","d":["أفيون: المسكّنات الأفيونية","كولين: مضادات الكولين","اكتئاب: مضادات الاكتئاب","حديد: مكمّلات الحديد","مدرّ: مدرّات البول (بسبب الجفاف)","العلاج: مي 1 – 2.5 ليتر باليوم إذا ما في مانع، ألياف، حركة، وقت ثابت للحمّام بعد الأكل"],"fr":{"t":"Constipation de l'âgé : moins de 3 et le FADO qui bloque","m":"Moins de 3 selles par semaine = constipation ; médicaments en cause : le FADO","d":["F = Fer (suppléments)","A = Anticholinergiques et Antidépresseurs","D = Diurétiques (par déshydratation)","O = Opioïdes (antalgiques)","Traitement : 1 à 2,5 litres d'eau par jour sans contre-indication, fibres, mouvement, heure fixe après les repas"]}},{"t":"أنواع سلس البراز","m":"عاجل ما بيستنّى، سلبي ما بيحسّ، فيضي حول كتلة، ووظيفي ما بيلحق","d":["Urgent (عاجل): رغبة مفاجئة وما بيقدر يأجّل","Passive (سلبي): البراز بيطلع بلا ما يحسّ قبل","Overflow (فيضي): انحشار برازي وبراز سائل بيتسرّب حول الكتلة القاسية","وظيفي: الأمعاء طبيعية بس ما بيوصل عالحمّام","انتبه: إمساك شديد ممكن يعمل سلس فيضي، فالممرضة بتكشف الانحشار"],"fr":{"t":"Types d'incontinence fécale","m":"Urgente : ne peut pas attendre ; passive : ne sent rien ; regorgement : autour d'un fécalome ; fonctionnelle : n'arrive pas","d":["Urgente : besoin soudain impossible à retarder","Passive : selles qui sortent sans sensation préalable","Par regorgement : fécalome avec fuite de selles liquides autour de la masse dure","Fonctionnelle : intestin normal mais n'arrive pas aux toilettes","Attention : une constipation sévère peut donner un regorgement, l'infirmière recherche le fécalome"]}}],"geri:g8":[{"t":"قصور الدرقية ضد فرطها","m":"هايبو = كل شي بطيء وبارد (TSH فوق)، هايبر = كل شي سريع وبيعرّق (TSH تحت)","d":["Hypothyroidism (قصور الدرقية): وزن بيزيد، تعب وخمول، إمساك، برد، نبض بطيء، جلد ناشف، اكتئاب، T3/T4 تحت وTSH فوق","علاجو: ليفوثيروكسين بجرعات زغيرة تدريجية، الصبح قبل الأكل","Hyperthyroidism (فرط الدرقية): وزن بينزل، خفقان، عصبية وقلق، تعرّق، رجفة، إسهال، T3/T4 فوق وTSH تحت","عند المسن ممكن يبين بس تعب أو رجفان أذيني (Apathetic hyperthyroidism)","علاجو: Methimazole، حاصرات بيتا، يود مشع، جراحة"],"fr":{"t":"Hypothyroïdie contre hyperthyroïdie","m":"Hypo = tout est lent et froid (TSH haute) ; hyper = tout est rapide et transpire (TSH basse)","d":["Hypothyroïdie : prise de poids, fatigue, constipation, frilosité, bradycardie, peau sèche, dépression ; T3/T4 basses, TSH haute","Traitement : lévothyroxine à petites doses progressives, le matin à jeun","Hyperthyroïdie : perte de poids, palpitations, nervosité, sueurs, tremblements, diarrhée ; T3/T4 hautes, TSH basse","Chez l'âgé : parfois seulement fatigue ou fibrillation auriculaire (hyperthyroïdie apathique)","Traitement : méthimazole, bêtabloquants, iode radioactif, chirurgie"]}},{"t":"فرط جارات الدرق: حصى، عظام، بطن، نفسية","m":"PTH فوق = كالسيوم فوق: حصى، عظام، بطن، نفسية","d":["حصى: حصى كلوية","عظام: هشاشة عظام وآلام عظمية","بطن: إمساك","نفسية: تعب وتشوّش ذهني","أشيع سبب: ورم حميد بجارة الدرق؛ والممرضة بتشجّع السوائل"],"fr":{"t":"Hyperparathyroïdie : calculs, os, ventre, psy","m":"PTH haute = calcium haut : calculs, os, ventre, psy","d":["Calculs : lithiase rénale","Os : ostéoporose et douleurs osseuses","Ventre : constipation","Psy : fatigue et confusion","Cause la plus fréquente : adénome bénin ; rôle infirmier : faire boire"]}},{"t":"قصور جارات الدرق: كالسيوم نازل، أعصاب فايرة","m":"PTH تحت = كالسيوم تحت وفوسفور فوق: تنميل، تشنّج، Chvostek وTrousseau إيجابيين","d":["تنميل ووخز حوالي التمّ وبالإيدين والإجرين","تشنّجات وتقلّصات عضلية، وبالحالات الشديدة Tetany (تكزّز)","Chvostek positive و Trousseau positive","الخطر: تشنّج الحنجرة واضطراب نظم القلب","السبب الأشيع: إصابة جارات الدرق أثناء جراحة الدرقية، فبعد العملية راقب التنميل والتشنّج"],"fr":{"t":"Hypoparathyroïdie : calcium bas, nerfs excités","m":"PTH basse = calcium bas et phosphore haut : fourmillements, crampes, Chvostek et Trousseau positifs","d":["Fourmillements autour de la bouche, des mains et des pieds","Crampes et spasmes musculaires, tétanie dans les formes sévères","Signes de Chvostek et de Trousseau positifs","Danger : spasme laryngé et troubles du rythme cardiaque","Cause la plus fréquente : lésion des parathyroïdes lors d'une thyroïdectomie, surveiller après l'opération"]}}],"geri:g9":[{"t":"ثلاثية باركنسون: TBR","m":"TBR: بيرجف وهو مرتاح، بيتحرّك ببطء، وعضلو يابس","d":["T = Tremor (رجفان أثناء الراحة)","B = Bradykinesia (بطء الحركة)","R = Rigidity (تيبّس عضلي)","السبب: نقص الدوبامين بالعقد القاعدية","العلاج الأهم: ليفودوبا + كاربيدوبا، وإعطاء الدوا بانتظام مهم كتير"],"fr":{"t":"Triade parkinsonienne : TBR","m":"TBR : il tremble au repos, il bouge lentement, ses muscles sont raides","d":["T = Tremor (tremblement de repos)","B = Bradykinésie (lenteur des mouvements)","R = Rigidité musculaire","Cause : manque de dopamine dans les noyaux gris centraux","Traitement principal : lévodopa + carbidopa, à donner à heures régulières"]}},{"t":"السكتة الدماغية: FAST","m":"FAST: وجّو، إيدو، حكيو، والوقت، ومذيب الخثرة بأول 4.5 ساعات","d":["F = Face (الوجه): انحراف التمّ","A = Arm (الإيد): ضعف مفاجئ أو شلل نصف الجسم","S = Speech (الكلام): صعوبة بالحكي","T = Time (الوقت): مذيبات الخثرة خلال أول 4.5 ساعات بالجلطة الإقفارية","الجلطة الإقفارية الأشيع، والنزف بيجي مع صداع شديد"],"fr":{"t":"AVC : FAST","m":"FAST : visage, bras, parole, temps ; thrombolyse dans les 4,5 premières heures","d":["F = Face (visage) : bouche déviée","A = Arm (bras) : faiblesse soudaine ou hémiplégie","S = Speech (parole) : difficulté à parler","T = Time (temps) : thrombolyse dans les 4,5 premières heures pour l'AVC ischémique","L'AVC ischémique est le plus fréquent ; l'hémorragie s'accompagne de céphalée intense"]}},{"t":"الخرف ضد الهذيان، وقاعدة CAM","m":"الخرف بطيء ومزمن، الهذيان فجأة ومتقلّب؛ CAM = 1 + 2 + (3 أو 4)","d":["الخرف (Dementia): تدهور مزمن تدريجي، Alzheimer الأشيع 60–70%","الهذيان (Delirium): حاد، خلال ساعات أو أيام، متقلّب خلال النهار، ورا سبب (التهاب، جفاف، دوا…)","CAM: 1 ارتباك حاد، 2 تغيّر بالانتباه، 3 تفكير مضطرب، 4 تغيّر بمستوى الوعي","التشخيص: 1 و 2 لازم، مع 3 أو 4","الهذيان الخامل (Hypoactive) أخطر لأنو بيتهمل"],"fr":{"t":"Démence contre délirium, et la règle CAM","m":"Démence = lente et chronique ; délirium = brutal et fluctuant ; CAM = 1 + 2 + (3 ou 4)","d":["Démence : déclin chronique progressif, Alzheimer le plus fréquent (60–70 %)","Délirium : aigu, en heures ou jours, fluctuant dans la journée, avec une cause (infection, déshydratation, médicament)","CAM : 1 confusion aiguë, 2 trouble de l'attention, 3 pensée désorganisée, 4 conscience altérée","Diagnostic : 1 et 2 obligatoires, plus 3 ou 4","Le délirium hypoactif est le plus dangereux car il passe inaperçu"]}}],"geri:g10":[{"t":"الدوا عند المسن: ADME كلّو أبطأ","m":"ADME عند المسن: كل شي أبطأ، والدوا بيتجمّع","d":["A = Absorption (الامتصاص): أبطأ، بس الكمية النهائية تقريباً نفسها","D = Distribution (التوزيع): دهون أكتر، مي أقل، ألبومين أقل → الأدوية الدهنية بتطوّل","M = Métabolisme (الأيض): الكبد أبطأ والإنزيمات أضعف","E = Élimination (الإخراج): الكلى أبطأ → تراكم وخطر سمّية","وفوقها Polypharmacy (أدوية كتير سوا) = تداخلات"],"fr":{"t":"Médicaments chez l'âgé : ADME, tout ralentit","m":"ADME chez l'âgé : tout est plus lent, et le médicament s'accumule","d":["A = Absorption : plus lente, mais quantité finale presque inchangée","D = Distribution : plus de graisse, moins d'eau, moins d'albumine ; les liposolubles restent plus longtemps","M = Métabolisme : foie plus lent, enzymes moins efficaces","E = Élimination : reins plus lents, accumulation et risque de toxicité","Plus la polymédication : interactions"]}},{"t":"ارتجاع، قرحة، رتوج: وين الوجع؟","m":"حرقة بالصدر بعد الأكل = GERD (ارفع الراس)؛ H. pylori وأسبرين = قرحة؛ وجع تحت عالشمال مع حرارة = رتوج ملتهبة","d":["GERD (الارتجاع المعدي المريئي): حرقة بالصدر بعد الأكل، طعم حامض، سعال أو بحّة → رفع الراس بالنوم وتياب واسعة","Peptic Ulcer (القرحة الهضمية): Helicobacter pylori أو الأسبرين وNSAIDs؛ قيء دموي أو براز أسود = نزيف","Diverticulitis (التهاب الرتوج): وجع أسفل البطن غالباً عالشمال، حرارة، غثيان، إمساك أو إسهال","Diverticulosis (رتوج بلا التهاب): غالباً بلا أعراض"],"fr":{"t":"Reflux, ulcère, diverticules : où est la douleur ?","m":"Brûlure après le repas = RGO (tête surélevée) ; H. pylori, aspirine = ulcère ; bas à gauche + fièvre = diverticulite","d":["RGO : brûlure thoracique après le repas, goût acide, toux ou voix rauque ; tête surélevée la nuit, vêtements amples","Ulcère peptique : Helicobacter pylori ou aspirine et AINS ; vomissement de sang ou selles noires = hémorragie","Diverticulite : douleur du bas-ventre souvent à gauche, fièvre, nausées, constipation ou diarrhée","Diverticulose (sans inflammation) : souvent sans symptômes"]}},{"t":"أطقم الأسنان: نضّف، شيل، افحص","m":"الطقم: نضّفو كل يوم، شيلو بالنوم، وافحصو عند الحكيم","d":["نضّف: كل يوم بفرشاية ناعمة ومعجون مخصّص أو محلول تنظيف","شيل: بالنوم لترتاح اللثة","افحص: دورياً عند طبيب الأسنان لتجنّب الكسر أو إنو ما يعود يركب","ومنع الالتهابات الفموية: نضافة التمّ واللسان، شرب مي، فحص دوري، بلا تدخين وسكّريات زيادة"],"fr":{"t":"Dentier : nettoyer, retirer, contrôler","m":"Le dentier : nettoyé chaque jour, retiré la nuit, contrôlé chez le dentiste","d":["Nettoyer : chaque jour, brosse douce et pâte adaptée ou solution de nettoyage","Retirer : pendant le sommeil pour reposer les gencives","Contrôler : régulièrement chez le dentiste pour éviter casse ou mauvaise adaptation","Prévenir les infections buccales : hygiène bouche et langue, boire, contrôles, éviter tabac et excès de sucre"]}}],"comm:c1":[{"t":"مبادئ الرعاية الصحية الأولية: 3 أزواج","m":"6 مبادئ = 3 أزواج: عادل وشامل • تعاون ومشاركة • مستمر ومناسب","d":["عادل = التوزيع العادل (العدالة الصحية): للكل بلا تمييز","شامل = الشمولية والتكامل: وقاية، تشخيص، علاج، إعادة تأهيل","تعاون = التعاون بين القطاعات: تعليم، تغذية، إسكان، بيئة","مشاركة = المشاركة المجتمعية: المجتمع بيخطط وبينفّذ","مستمر = استمرارية الرعاية: من الطفولة للشيخوخة","مناسب = الاعتماد على التقنيات المناسبة: فعالة ورخيصة وبتناسب المجتمع"],"fr":{"t":"Principes des soins de santé primaires : 3 paires","m":"6 principes = 3 paires : Équitable + Global • Collaboration + Participation • Continu + Adapté","d":["Équitable = distribution équitable (équité en santé) : pour tous, sans discrimination","Global = globalité et intégration : prévention, diagnostic, traitement, réadaptation","Collaboration = coopération intersectorielle : éducation, nutrition, logement, environnement","Participation = participation communautaire : la communauté planifie et exécute","Continu = continuité des soins : de l'enfance à la vieillesse","Adapté = technologies appropriées : efficaces, peu coûteuses, adaptées au contexte local"]}},{"t":"عناصر الرعاية الأولية: نهار الممرضة بالضيعة","m":"8 عناصر بنهار وحدة: بتعلّم، بتلقّح، بتتابع الحامل والطفل، بتطعمي، بتنضّف المي، بتداوي، بتعطي دوا، وبتطمّن","d":["بتعلّم = التثقيف الصحي (حجر الزاوية)","بتلقّح = التطعيمات: حصبة، شلل أطفال، دفتيريا، إنفلونزا","الحامل والطفل = الصحة الإنجابية وصحة الطفل","بتطعمي = التغذية","بتنضّف المي = المياه النقية والصرف الصحي","بتداوي = معالجة الأمراض الشائعة: تنفسي، إسهال، جلدي","بتعطي دوا = توفير الأدوية الأساسية بأسعار معقولة","بتطمّن = الصحة العقلية والدعم النفسي","وتذكّر: 6 مبادئ، 8 عناصر، وكلّو من ألما-آتا 1978"],"fr":{"t":"Éléments des SSP : la journée de l'infirmière au village","m":"8 éléments en une journée : elle éduque, vaccine, suit mère et enfant, nourrit, assainit, soigne, fournit, rassure","d":["Éduque = éducation pour la santé (pierre angulaire)","Vaccine = vaccinations : rougeole, poliomyélite, diphtérie, grippe","Mère et enfant = santé reproductive et santé de l'enfant","Nourrit = nutrition","Assainit = eau potable et assainissement","Soigne = traitement des maladies courantes : respiratoires, diarrhée, cutanées","Fournit = médicaments essentiels à prix abordable","Rassure = santé mentale et soutien psychologique","À retenir : 6 principes, 8 éléments, tout vient d'Alma-Ata 1978"]}},{"t":"أنواع المجتمع: 3 أزواج متعاكسة + واحد عالنت","m":"7 مجتمعات: ريفي ضد حضري، زراعي ضد صناعي، تقليدي ضد حديث، والسابع افتراضي عالإنترنت","d":["ريفي: قرى، كثافة قليلة، علاقات متينة، تحدّي: خدمات قليلة وهجرة للمدن","حضري: مدن، كثافة عالية، تحدّي: ازدحام وتلوث وغلاء","زراعي: محاصيل وماشية، العيلة وحدة إنتاج، تحدّي: المواسم والمناخ","صناعي: مصانع وآلات، تحدّي: بطالة وتلوث صناعي","تقليدي: عادات موروثة واحترام الكبار، تحدّي: مقاومة التغيير","حديث: تعليم مرتفع وتكنولوجيا، تحدّي: ضغوط وقلة تواصل عميق","افتراضي: عبر الإنترنت، تحدّي: الخصوصية والأمان والمعلومات المضللة"],"fr":{"t":"Types de communauté : 3 paires opposées + 1 en ligne","m":"7 communautés : rurale vs urbaine, agricole vs industrielle, traditionnelle vs moderne, et la virtuelle","d":["Rurale : villages, faible densité, liens forts ; défi : peu de services, exode vers les villes","Urbaine : villes, forte densité ; défi : encombrement, pollution, coût de la vie","Agricole : cultures et bétail, la famille = unité de production ; défi : saisons et climat","Industrielle : usines et machines ; défi : chômage et pollution industrielle","Traditionnelle : coutumes héritées, respect des aînés ; défi : résistance au changement","Moderne : éducation élevée, technologie ; défi : stress, peu de liens profonds","Virtuelle : via Internet ; défi : vie privée, sécurité, désinformation"]}}],"comm:c2":[{"t":"مستويات الوقاية: قبل، بكّير، بعد","m":"أولية قبل المرض، ثانوية بكّير (كشف مبكر)، ثالثة بعد التشخيص","d":["أولية = قبل ما يصير: تطعيمات، تثقيف صحي، تحسين البيئة (مي نضيفة، صرف صحي)","ثانوية = بكّير: فحوصات دورية (ضغط، سكر، كشف مبكر عن السرطان) وتشخيص مبكر","ثالثة = بعد التشخيص: إعادة تأهيل (علاج طبيعي) وتأهيل نفسي لمنع المضاعفات"],"fr":{"t":"Niveaux de prévention : avant, tôt, après","m":"Primaire = avant la maladie, secondaire = tôt (dépistage), tertiaire = après le diagnostic","d":["Primaire = avant : vaccinations, éducation pour la santé, amélioration de l'environnement (eau propre, assainissement)","Secondaire = tôt : examens périodiques (tension, glycémie, dépistage du cancer) et diagnostic précoce","Tertiaire = après : réadaptation (kinésithérapie) et réhabilitation psychologique contre les complications"]}},{"t":"الأنظمة الفرعية للنظام الصحي: عَوْ + 3 ت","m":"5 أنظمة فرعية: «عَوْ» + 3 ت = علاجي، وقائي، تأهيلي، تثقيفي، تمويلي","d":["ع = النظام العلاجي: مستشفيات، تشخيص، طوارئ","و = النظام الوقائي: تطعيمات، حملات ضد التدخين، تغذية","ت = النظام التأهيلي: علاج طبيعي ووظيفي للإعاقات والمزمن","ت = نظام التثقيف الصحي: نشر الوعي ضد العادات الضارة","ت = النظام التمويلي: ميزانية الدولة، تمويل خارجي، تأمين صحي"],"fr":{"t":"Sous-systèmes du système de santé : CPRÉF","m":"5 sous-systèmes : CPRÉF = Curatif, Préventif, Réadaptation, Éducation, Financement","d":["C = curatif : hôpitaux, diagnostic, urgences","P = préventif : vaccinations, campagnes antitabac, nutrition","R = réadaptation : kinésithérapie et ergothérapie pour handicaps et maladies chroniques","É = éducation pour la santé : sensibilisation contre les habitudes nocives","F = financement : budget de l'État, financement extérieur, assurance maladie"]}},{"t":"محلي، إقليمي، وطني: حيّ، منطقة، دولة","m":"محلي بالحيّ = لقاح، إقليمي بالمنطقة = عملية، وطني بالدولة = زرع أعضاء وسياسات","d":["محلي: مراكز بالأحياء والقرى: تطعيمات، رعاية أولية، تثقيف، حالات بسيطة","إقليمي: مستشفيات إقليمية: عمليات جراحية، أمومة متقدمة، تشخيص متخصص، صحة عقلية","وطني: الوزارات ومراكز وطنية: سياسات صحية، أمراض نادرة، زراعة الأعضاء","وما تخلط مع مستويات الرعاية: أولية، ثانوية، ثلاثية (جراحات القلب والأورام)، تأهيلية"],"fr":{"t":"Local, régional, national : quartier, région, pays","m":"Local = vaccin, régional = opération, national = greffe d'organes et politiques de santé","d":["Local : centres de quartier et de village : vaccinations, soins primaires, éducation, cas simples","Régional : hôpitaux régionaux : chirurgie, maternité avancée, diagnostic spécialisé, santé mentale","National : ministères et centres nationaux : politiques de santé, maladies rares, transplantation d'organes","Ne pas confondre avec les niveaux de soins : primaire, secondaire, tertiaire (chirurgie cardiaque, oncologie), réadaptation"]}}],"comm:c3":[{"t":"وظائف ممرضة صحة المجتمع: 6 أفعال","m":"علّم، احمي، اكتشف، طمّن، نسّق، أسعف","d":["علّم = التثقيف الصحي: تغذية، نظافة، فحوصات وتطعيمات","احمي = الوقاية من الأمراض: حملات ومراقبة الأمراض المعدية","اكتشف = التشخيص المبكر والمتابعة: فحوصات أولية، سكري وضغط","طمّن = دعم الصحة النفسية: استشارات وتوجيه بالأزمات","نسّق = التنسيق مع الخدمات الصحية: توجيه للمستشفى أو العيادة المتخصصة","أسعف = الطوارئ والإسعافات الأولية بالكوارث المحلية"],"fr":{"t":"Fonctions de l'infirmière communautaire : 6 verbes","m":"Éduquer, Protéger, Dépister, Soutenir, Coordonner, Secourir","d":["Éduquer = éducation pour la santé : nutrition, hygiène, examens et vaccins","Protéger = prévention des maladies : campagnes, surveillance des maladies infectieuses","Dépister = diagnostic précoce et suivi : examens de base, diabète et hypertension","Soutenir = soutien en santé mentale : conseils, orientation en cas de crise","Coordonner = coordination avec les services : orientation vers l'hôpital ou la clinique spécialisée","Secourir = urgences et premiers secours lors des catastrophes locales"]}},{"t":"الرعاية المنزلية: إبرة، سكري، عيلة، تقرير","m":"بالبيت 4 أدوار: إبرة، سكري، عيلة، تقرير","d":["إبرة = تقديم العلاج بالبيت: حقن، تغيير ضمادات، مراقبة الأدوية","سكري = متابعة الحالات المزمنة (سكري وضغط) للتأكد من الاستقرار","عيلة = التثقيف والتوجيه: كيف العيلة بتتعامل مع المريض","تقرير = التقييم الدوري وتقارير للأطباء عن تقدّم الحالة","لمين؟ كبار السن، المزمن، والإعاقات اللي بيصعب عليهن يروحوا عالمستشفى"],"fr":{"t":"Soins à domicile : piqûre, diabète, famille, rapport","m":"À domicile, 4 rôles : piqûre, diabète, famille, rapport","d":["Piqûre = traitement à domicile : injections, pansements, surveillance des médicaments","Diabète = suivi des maladies chroniques (diabète, hypertension) pour vérifier la stabilité","Famille = éducation et orientation : comment la famille s'occupe du patient","Rapport = évaluation périodique et rapports au médecin sur l'évolution","Pour qui ? Personnes âgées, malades chroniques, handicaps rendant le déplacement difficile"]}}],"comm:c4":[{"t":"أهداف الصحة العامة: 5 أفعال","m":"وقّي، عزّز، ساوي، نضّف البيئة، جهّز للطوارئ","d":["وقّي = الوقاية من الأمراض والسيطرة عليها ومراقبة الأوبئة","عزّز = تعزيز الصحة: أكل متوازن، رياضة، بلا تدخين، صحة نفسية","ساوي = تحقيق المساواة الصحية: الكل، ريف ومدينة","نضّف البيئة = تعزيز البيئة الصحية: هوا، مي، نفايات، تلوث ومناخ","جهّز = الاستعداد للطوارئ: خطط استجابة وتدريب فرق ومستشفيات"],"fr":{"t":"Objectifs de la santé publique : 5 verbes","m":"Prévenir, Promouvoir, Égaliser, Assainir, Préparer","d":["Prévenir = prévention et contrôle des maladies, surveillance des épidémies","Promouvoir = promotion de la santé : alimentation équilibrée, sport, pas de tabac, santé mentale","Égaliser = équité en santé : accès pour tous, rural comme urbain","Assainir = environnement sain : air, eau, déchets, pollution et climat","Préparer = préparation aux urgences : plans de réponse, équipes et hôpitaux formés"]}},{"t":"مكافحة الأوبئة: 3 تلاتات","m":"3×3: تطعيم، توعية، نظافة • تشخيص، رعاية، عزل • حكومة، دولي، مجتمع","d":["التدخلات الوقائية: تطعيم، توعية صحية، نظافة (غسل إيدين، تعقيم، كمامة)","إدارة الحالات: تشخيص مبكر، رعاية طبية (تنفس صناعي، عناية مركزة)، عزل وحجر صحي","التنسيق: حكومي (وزارات الصحة)، دولي (منظمات الصحة)، مجتمعي (منظمات غير حكومية ومتطوعين)","وبعدين التكنولوجيا: ذكاء اصطناعي لتوقّع التفشي، تطبيقات لتتبّع المخالطين"],"fr":{"t":"Lutte contre les épidémies : 3 x 3","m":"3 x 3 : Vacciner, Informer, Hygiène • Dépister, Soigner, Isoler • État, International, Communauté","d":["Interventions préventives : vaccination, sensibilisation, hygiène (lavage des mains, désinfection, masque)","Gestion des cas : diagnostic précoce, soins médicaux (respirateurs, réanimation), isolement et quarantaine","Coordination : gouvernementale (ministères de la santé), internationale, communautaire (ONG, bénévoles)","Puis la technologie : intelligence artificielle pour prévoir, applications de traçage des contacts"]}},{"t":"نوعين أوبئة وتلات تواريخ","m":"معدي = جرثومة (إنفلونزا، إيبولا، كوليرا) • غير معدي = نمط حياة (سكري، سمنة، قلب)","d":["المعدية: فيروسات، بكتيريا، طفيليات","غير المعدية: أمراض مزمنة بتنتشر بسبب نمط الحياة","التاريخ: الطاعون الأسود (العصور الوسطى) ← الإنفلونزا الإسبانية 1918 ← كوفيد-19","الأهمية 3 «يّ»: اجتماعياً، اقتصادياً، علمياً (لقاحات وعلاجات)"],"fr":{"t":"Deux types d'épidémies et trois dates","m":"Infectieuse = microbe (grippe, Ebola, choléra) • Non infectieuse = mode de vie (diabète, obésité, cœur)","d":["Infectieuses : virus, bactéries, parasites","Non infectieuses : maladies chroniques liées au mode de vie","Histoire : peste noire (Moyen Âge), grippe espagnole 1918, Covid-19","Importance : sociale, économique, scientifique (vaccins et traitements)"]}}],"comm:c5":[{"t":"أساليب التثقيف الصحي: 5 محطات","m":"وجهاً لوجه، شاشة، موبايل، مدرسة، مستوصف","d":["وجهاً لوجه = التوعية المباشرة: لقاءات وورش عمل، ندوات ومحاضرات","شاشة = الحملات الإعلامية: تلفزيون وراديو، إعلانات موجّهة","موبايل = وسائل التواصل الاجتماعي: فيديوهات، رسوم بيانية، رد على الأسئلة","مدرسة = البرامج المدرسية: صحة بالمناهج، مسابقات ومعارض","مستوصف = التثقيف عبر المراكز الصحية: نصائح مباشرة ومنشورات"],"fr":{"t":"Méthodes d'éducation pour la santé : 5 étapes","m":"Face à face, écran, portable, école, centre de santé","d":["Face à face = sensibilisation directe : rencontres, ateliers, conférences","Écran = campagnes médiatiques : télévision, radio, annonces ciblées","Portable = réseaux sociaux : vidéos, infographies, réponses aux questions","École = programmes scolaires : santé dans le programme, concours et expositions","Centre de santé = conseils directs aux patients et brochures"]}},{"t":"مكونات الصحة النفسية: قلب، راس، ناس","m":"الصحة النفسية = قلب (عاطفة) + راس (استقرار) + ناس (تكيّف اجتماعي)","d":["قلب = السلامة العاطفية: التعامل الإيجابي مع السعادة والحزن والغضب والخوف، والتحكم بالانفعالات","راس = الاستقرار النفسي: توازن بين الأفكار والمشاعر، والتعامل مع الأزمات بعقلانية","ناس = التكيّف الاجتماعي: علاقات متينة بالثقة، وتفاعل سليم بالعيلة والشغل والمجتمع"],"fr":{"t":"Composantes de la santé mentale : cœur, tête, gens","m":"Santé mentale = cœur (émotions) + tête (stabilité) + gens (adaptation sociale)","d":["Cœur = bien-être émotionnel : gérer joie, tristesse, colère, peur ; contrôler ses émotions","Tête = stabilité psychologique : équilibre pensées-émotions, gérer les crises avec raison","Gens = adaptation sociale : relations de confiance, bonne interaction en famille, au travail, dans la société"]}},{"t":"خدمات الصحة النفسية: عيادة، عيلة، مدرسة، شغل","m":"4 خدمات: عيادة (تقييم وعلاج)، عيلة (دعم المرضى وأسرهم)، مدرسة، شغل","d":["عيادة = التقييم والعلاج النفسي: اكتئاب، قلق، اضطراب ما بعد الصدمة؛ CBT (العلاج المعرفي السلوكي)","عيلة = الدعم الاجتماعي: مجموعات دعم للمرضى وتدريب أسرهم","مدرسة = الاستشارات النفسية بالمدارس: تنمّر، ضغط دراسي، ثقة بالنفس","شغل = الاستشارات النفسية بأماكن العمل: الإجهاد وصعوبات العمل"],"fr":{"t":"Santé mentale : clinique, famille, école, travail","m":"4 services : clinique (évaluation, thérapie), famille (soutien), école, travail","d":["Clinique = évaluation et psychothérapie : dépression, anxiété, stress post-traumatique ; TCC (thérapie cognitivo-comportementale)","Famille = soutien social : groupes de soutien pour les patients, formation des familles","École = consultations psychologiques à l'école : harcèlement, pression scolaire, confiance en soi","Travail = consultations au travail : épuisement et difficultés professionnelles"]}}],"comm:c6":[{"t":"تحديات المستقبل: 5 ضيوف تقال","m":"5 ضيوف تقال: بكتيريا عنيدة، سكري وضغط، اكتئاب وقلق، حرّ ومناخ، وكوفيد","d":["بكتيريا عنيدة = مقاومة المضادات الحيوية","سكري وضغط = انتشار الأمراض المزمنة (سكري، ضغط، قلب)","اكتئاب وقلق = تزايد الأمراض النفسية (عزلة وانتحار)","حرّ ومناخ = تغيّر المناخ: حشرات، فيضانات وجفاف، أمن غذائي","كوفيد = الأوبئة والجائحات بسبب السفر والكثافة السكانية","والحلول: بحث علمي، وقاية، أنظمة صحية، تعاون دولي ومحلي، مناخ، صحة نفسية"],"fr":{"t":"Défis futurs : 5 invités lourds","m":"5 invités lourds : bactérie têtue, diabète-tension, dépression, chaleur-climat, Covid","d":["Bactérie têtue = résistance aux antibiotiques","Diabète-tension = maladies chroniques (diabète, hypertension, cœur)","Dépression = hausse des troubles psychiques (isolement, suicide)","Chaleur-climat = changement climatique : insectes, inondations, sécheresse, sécurité alimentaire","Covid = épidémies et pandémies (voyages, densité de population)","Solutions : recherche, prévention, systèmes de santé, coopération, climat, santé mentale"]}},{"t":"مين بيعمل شو بالوباء؟ 4 وزارات","m":"صحة = لقاح، نقل = حركة، تعليم = مدارس، إعلام = معلومات","d":["وزارة الصحة: لقاحات وعلاجات وحملات تطعيم","وزارة النقل: تنظيم حركة الناس والبضائع لمنع العدوى","وزارة التعليم: سكّر المدارس عند الحاجة وتعليمات الوقاية","وزارة الإعلام: معلومات موثوقة ضد الشائعات"],"fr":{"t":"Qui fait quoi en épidémie ? 4 ministères","m":"Santé = vaccin, Transport = mouvement, Éducation = écoles, Information = infos","d":["Santé : vaccins, traitements, campagnes de vaccination","Transport : organiser les déplacements des personnes et des marchandises","Éducation : fermer les écoles si besoin, consignes de prévention","Information : informations fiables contre les rumeurs"]}},{"t":"أهداف التعاون بين القطاعات: عيش، كول، اشتغل، ما تمرض","m":"4 أهداف: عيش ببيئة نضيفة، كول أكل آمن، اشتغل بشغل صحي، وما تمرض","d":["عيش = خلق بيئة صحية: مساحات عامة نضيفة، أقل تلوث صناعي","كول = تحسين جودة الغذاء: إنتاج زراعي صحي ورقابة غذائية","اشتغل = توفير فرص عمل صحية: قوانين ضد المخاطر المهنية","ما تمرض = الحد من الأمراض المعدية وغير المعدية بحملات مشتركة"],"fr":{"t":"Intersectorialité : vivre, manger, travailler, guérir","m":"4 objectifs : vivre dans un milieu sain, manger sain, travailler sans risque, moins de maladies","d":["Vivre = environnement sain : espaces publics propres, moins de pollution industrielle","Manger = qualité des aliments : production agricole saine, contrôle alimentaire","Travailler = emplois sains : lois contre les risques professionnels","Moins de maladies = lutte contre les maladies infectieuses et non infectieuses par des campagnes communes"]}}],"comm:c7":[{"t":"أرقام الكشف المبكر: 25، 40، 50","m":"عنق الرحم من 25، الثدي من 40، القولون من 50","d":["25 = Frottis (مسحة عنق الرحم) كل 3 سنين ابتداءً من عمر 25","40 = الماموغرافيا (تصوير الثدي) من سن 40، أو قبل إذا في تاريخ عائلي","الثدي كمان: فحص ذاتي كل شهر بعد الدورة + فحص سريري كل سنة","50 = تنظير القولون من سن 50، أو قبل إذا في تاريخ عائلي","القولون كمان: تحليل الدم الخفي بالبراز كل سنة","والفم: راقب أي قرحة أو تغيّر بيطوّل أكتر من أسبوعين، وخزعة لأي ورم مشتبه فيه"],"fr":{"t":"Chiffres du dépistage : 25, 40, 50","m":"Col de l'utérus dès 25, sein dès 40, côlon dès 50","d":["25 = frottis cervical tous les 3 ans à partir de 25 ans","40 = mammographie dès 40 ans, ou plus tôt si antécédents familiaux","Sein aussi : autopalpation chaque mois après les règles + examen clinique chaque année","50 = coloscopie dès 50 ans, ou plus tôt si antécédents familiaux","Côlon aussi : recherche de sang occulte dans les selles chaque année","Bouche : surveiller toute ulcération de plus de 2 semaines, biopsie de toute tumeur suspecte"]}},{"t":"عوامل أمراض القلب: ضغط + 2 ك + 3 س","m":"ضغط + 2 ك (كوليسترول، كحول) + 3 س (سكري، سمنة، سيجارة)","d":["ضغط = ارتفاع ضغط الدم بيجهد جدران الشرايين","ك = ارتفاع الكوليسترول LDL بيعمل لويحات","ك = الإفراط بالكحول بيرفع الضغط","س = داء السكري بيضرّ الأوعية ويعزّز التصلب العصيدي","س = السمنة بترفع الضغط والكوليسترول والسكري","س = سيجارة (التدخين) بتزيد الالتهاب وتراكم الدهون","والوقاية: رياضة 30 دقيقة باليوم (مشي أو سباحة)"],"fr":{"t":"Facteurs cardiovasculaires : HTA-LDL-ADOS","m":"HTA + LDL + A.D.O.S. = Alcool, Diabète, Obésité, Smoking (tabac)","d":["HTA = l'hypertension fatigue la paroi des artères","LDL = le cholestérol LDL forme les plaques","A = alcool en excès : élève la tension","D = diabète : abîme les vaisseaux, favorise l'athérosclérose","O = obésité : élève tension, cholestérol et glycémie","S = smoking (tabac) : plus d'inflammation et de dépôts graisseux","Prévention : sport 30 minutes par jour (marche ou natation)"]}},{"t":"فاجرستروم: 6 أسئلة، اتنين بـ3، والمجموع 10","m":"Fagerström (اختبار إدمان النيكوتين): 6 أسئلة، أول سيجارة وعدد السجاير بـ3، الباقي بـ1 = 10","d":["3 نقاط: أول سيجارة خلال 5 دقايق من الفيقة","3 نقاط: 31 سيجارة أو أكتر باليوم","1 نقطة لكل وحدة: صعوبة بالأماكن الممنوعة، سيجارة الصبح الأهم، بيدخّن أكتر الصبح، بيدخّن وهو مريض بالتخت","التفسير: 0 لـ 2 خفيف • 3 لـ 4 متوسط • 5 لـ 6 شديد • 7 لـ 10 إدمان قوي جداً بدّو علاج","ودخان التبغ: أكتر من 7000 مادة، منها أكتر من 70 مسرطنة"],"fr":{"t":"Fagerström : 6 questions, deux à 3 points, total 10","m":"Test de Fagerström : 6 questions ; 1re cigarette et nombre de cigarettes = 3 points, les autres = 1 ; max 10","d":["3 points : 1re cigarette dans les 5 minutes après le réveil","3 points : 31 cigarettes ou plus par jour","1 point chacune : difficulté dans les lieux interdits, cigarette du matin la plus importante, fume plus le matin, fume même malade au lit","Score : 0-2 faible, 3-4 moyen, 5-6 fort, 7-10 très forte dépendance, traitement médical","Fumée de tabac : plus de 7000 substances, dont plus de 70 cancérigènes"]}}],"comm:c8":[{"t":"رزنامة اللقاحات بلبنان: 0، 2-4-6، 9، 12، 18","m":"ولادة B، ثم 2-4-6 خماسي + PCV13، 9 حصبة، 12 MMR + PCV13، 18 خماسي + شلل فموي + MMR","d":["عند الولادة: Hepatitis B (التهاب الكبد B)","2، 4، 6 أشهر: الخماسي (دفتيريا، كزاز، سعال ديكي، شلل، Hib) + PCV13","9 أشهر: لقاح الحصبة","12 شهر: MMR (الحصبة، النكاف، الحصبة الألمانية) + PCV13","18 شهر: خماسي + شلل فموي + MMR","تذكير الثلاثي البكتيري: 4 لـ 5 سنين (مع الشلل الفموي)، 10 لـ 12، 16 لـ 18"],"fr":{"t":"Calendrier vaccinal au Liban : 0, 2-4-6, 9, 12, 18","m":"Naissance : hépatite B ; 2-4-6 mois : pentavalent + PCV13 ; 9 : rougeole ; 12 : ROR + PCV13 ; 18 : penta + polio oral + ROR","d":["Naissance : hépatite B","2, 4, 6 mois : pentavalent (diphtérie, tétanos, coqueluche, polio, Hib) + PCV13","9 mois : vaccin rougeole","12 mois : ROR (rougeole, oreillons, rubéole) + PCV13","18 mois : pentavalent + polio oral + ROR","Rappels DTC : 4-5 ans (avec polio oral), 10-12 ans, 16-18 ans"]}},{"t":"المناعة المكتسبة: بتصنع أو بتاخد جاهز","m":"إيجابية = بتصنع الأجسام المضادة بنفسك • سلبية = بتاخدها جاهزة، وكل وحدة طبيعية أو صناعية","d":["إيجابية طبيعية (Active): بعد الإصابة بمرض، مثل الحصبة","إيجابية صناعية: اللقاحات","سلبية طبيعية (Passive): من الأم للجنين أو بالرضاعة","سلبية صناعية: مصل جاهز، مثل مصل لدغة الثعبان","والطبيعية (Innate) بتنولد معك: حواجز ميكانيكية (جلد، أغشية مخاطية، أهداب) وكيميائية (لعاب، دموع، حمض المعدة)"],"fr":{"t":"Immunité acquise : je fabrique ou je reçois","m":"Active = je fabrique mes anticorps • Passive = je les reçois prêts ; chacune naturelle ou artificielle","d":["Active naturelle : après une maladie, par exemple la rougeole","Active artificielle : les vaccins","Passive naturelle : de la mère au fœtus ou par l'allaitement","Passive artificielle : sérum prêt, par exemple sérum antivenin de serpent","Immunité innée (dès la naissance) : barrières mécaniques (peau, muqueuses, cils) et chimiques (salive, larmes, acide gastrique)"]}},{"t":"لقاح، مصل، دوا: مين أسرع ومين بيدوم؟","m":"اللقاح بطيء بس بيدوم (وقاية)، المصل سريع بس ما بيدوم (بعد التعرّض)، الدوا بيعالج بعد المرض","d":["لقاح: مفعول بعيد المدى، مناعة لسنين، للوقاية، بدّو وقت ليصير فعّال","مصل: أجسام مضادة جاهزة، مفعول سريع جداً، مباشرة بعد التعرّض لميكروب أو سمّ، بلا مناعة طويلة","دوا: مادة كيميائية أو عشبية، بيعالج بعد المرض، بلا مناعة طويلة، وممكن ينعاد كذا مرة","يعني: لقاح = إيجابية صناعية، مصل = سلبية صناعية"],"fr":{"t":"Vaccin, sérum, médicament : qui est rapide, qui dure ?","m":"Vaccin = lent mais durable (prévention) ; sérum = rapide mais court (après exposition) ; médicament = traite après","d":["Vaccin : effet à long terme, immunité pendant des années, prévention, met du temps à agir","Sérum : anticorps prêts, effet très rapide, juste après exposition à un microbe ou un poison, pas d'immunité durable","Médicament : substance chimique ou à base de plantes, traite la maladie déclarée, pas d'immunité durable, à reprendre souvent","Donc : vaccin = immunité active artificielle, sérum = immunité passive artificielle"]}}],"medsurg:iv":[{"t":"مضاعفات التسريب: قصة المصل الشقي","m":"المصل تسرّب، جاب جراثيم، فوّت هوا، لهّب الوريد، وغرّق المريض","d":["تسرّب = Infiltration (السائل تحت الجلد وبالأنسجة)","جراثيم = Bactériémie (تجرثم الدم أو إنتان) ← تعقيم وغسل إيدين ومراقبة الحرارة","هوا = Embolie gazeuse (جلطة هوائية) ← نغيّر الكيس قبل ما يفضى وبلا فقاعات بالـ tubulure","لهّب الوريد = التهاب الوريد / Lymphangite ← أدوية مهيّجة ببطء وغسل بالـ physiologique","غرّق = Surcharge liquidienne (فرط حمل السوائل) ← انتبه للـ insuffisance rénale / cardiaque","ونغيّر مكان التسريب والـ système كل 72 h"],"fr":{"t":"Complications de la perfusion : BILES","m":"BILES : Bactériémie, Infiltration, Lymphangite, Embolie gazeuse, Surcharge liquidienne","d":["B = Bactériémie : asepsie, lavage des mains, surveiller la température","I = Infiltration : liquide sous la peau et dans les tissus","L = Lymphangite (inflammation de la veine) : produits irritants lentement, rincer au sérum physiologique","E = Embolie gazeuse : changer la poche avant qu'elle se vide, aucune bulle dans la tubulure","S = Surcharge liquidienne : attention à l'insuffisance rénale ou cardiaque","Changer le site et le système toutes les 72 h"]}},{"t":"ألوان الكانيولا: من الغيمة للشمس","m":"غيمة رمادية، عشب أخضر، وردة زهرية، سما زرقا، شمس صفرا: 16 ← 18 ← 20 ← 22 ← 24","d":["gris (رمادي) = 16","vert (أخضر) = 18","rose (زهري) = 20","bleu (أزرق) = 22","jaune orangé (أصفر برتقالي) = 24","«كبر صغير»: كل ما كبر الرقم صغر قطر الإبرة، ومنختار القياس حسب حجم الوريد"],"fr":{"t":"Couleurs des cathéters : du nuage au soleil","m":"Nuage gris, herbe verte, fleur rose, ciel bleu, soleil jaune : 16, 18, 20, 22, 24","d":["Gris = 16","Vert = 18","Rose = 20","Bleu = 22","Jaune orangé = 24","Plus le chiffre est grand, plus l'aiguille est fine ; choisir selon la taille de la veine"]}},{"t":"Entérale ضدّ Parentérale","m":"Entérale = عالمصارين بأنبوب؛ Parentérale = بالوريد: glucose، lipide، électrolytes","d":["Entérale (التغذية المعوية): أكل للمعدة بالأنبوب الأنفي، والمعدة والأمعاء شغّالين","منستعملها إذا: غياب منعكس البلع، زيادة الاستقلاب (حروق)، أو ورم بالحنجرة","Parentérale (التغذية الوريدية): glucose (سكّر)، lipide (دهون)، électrolytes (شوارد) بالوريد","منستعملها إذا: الأكل أقل من الحاجة، azote (الآزوت) سلبي، أو لنريّح الجهاز الهضمي","مضاعفات الـ cathéter: انسداد، انزياح، infection، pneumothorax"],"fr":{"t":"Entérale contre parentérale","m":"Entérale = par le tube digestif avec une sonde ; Parentérale = par la veine : glucose, lipides, électrolytes","d":["Entérale : aliments dans l'estomac par sonde nasale, tube digestif fonctionnel","Indications : absence de réflexe de déglutition, hypermétabolisme (brûlures), tumeur du larynx","Parentérale : glucose, lipides, électrolytes par voie veineuse","Indications : apports insuffisants, bilan azoté négatif, mise au repos du tube digestif","Complications du cathéter : obstruction, déplacement, infection, pneumothorax"]}}],"law:l4":[{"t":"OMS بأرقام: 7 – 48 – جنيف – 34 – 3","m":"OMS خلقت 7 نيسان 48 بجنيف، جمعيتها كل أيار، ومجلسها 34 لـ 3 سنين","d":["OMS (منظمة الصحة العالمية) = وكالة تابعة للأمم المتحدة","تأسّست 7 نيسان 1948 · مقرّها جنيف (Genève)","جمعية الصحة العالمية: كل سنة بجنيف بشهر أيار","المجلس التنفيذي: 34 عضو لمدة 3 سنين، بينفّذ قرارات الجمعية","الممرض الأجنبي: إذن الوزارة + النقابة + عقد سنة بمستشفى محدّد + إثبات حاجة"],"fr":{"t":"L'OMS en chiffres : 7 – 48 – Genève – 34 – 3","m":"OMS née le 7 avril 48 à Genève, assemblée chaque mai, conseil de 34 pour 3 ans","d":["OMS = agence des Nations unies","Fondée le 7 avril 1948 · siège à Genève","Assemblée mondiale de la Santé : chaque année à Genève, en mai","Conseil exécutif : 34 membres pour 3 ans, applique les décisions de l'Assemblée","Infirmier étranger : autorisation du ministère + ordre + contrat d'un an dans un hôpital précis + besoin prouvé"]}}],"medsurg:csh":[{"t":"الأنواع والمراحل: «أنا، غريب، توأم» ثم «حضّر، حقن، ثبّت»","m":"Auto = أنا، Allo = غريب متطابق، Syn = توأم؛ والمراحل: حضّر ← احقن ← ثبّت (engraftment)","d":["Autologue (ذاتي) = من المريض نفسو","Allogénique (خيفي) = من متبرّع متطابق","Syngénique = من توأم متطابق (نادر)","المراحل: تحضير (كيماوي/أشعة) ← حقن بالوريد ← engraftment (استقرار الخلايا)","GVHD: قبل 100 يوم = aigu (حاد: جلد، كبد، هضمي)، بعد 100 يوم = chronique (مزمن) ← كورتيزون + مثبّطات المناعة"],"fr":{"t":"Types et étapes : moi, un donneur, mon jumeau","m":"Auto = moi, Allo = donneur compatible, Syn = jumeau ; étapes : préparer → injecter → prise de greffe","d":["Autologue = du patient lui-même","Allogénique = d'un donneur compatible","Syngénique = d'un jumeau identique (rare)","Étapes : préparation (chimio / radiothérapie) → injection IV → engraftment","GVHD : avant 100 jours = aiguë (peau, foie, tube digestif), après 100 jours = chronique → corticoïdes + immunosuppresseurs"]}}],"medsurg:fdv":[{"t":"نهاية الحياة: 4 أنواع دعم «جسم، قلب، رغبة، عيلة»","m":"جسم (ألم وأعراض وراحة)، قلب (سماع ولطف)، رغبة (مكان الوفاة، روحي، كرامة)، عيلة (قرارات وبعد الوفاة)","d":["جسم = تسكين الألم حسب البروتوكول + غثيان، ضيق نفس، تعب، إمساك + تغيير وضعية وعناية بالجلد والفم","قلب = الاستماع، التحدّث بلطف، الأمان، دعم الأسرة","رغبة = رغبات المريض (مكان الوفاة)، رجل دين وطقوس، الكرامة","عيلة = تنسيق مع الفريق ومساعدة بالقرارات؛ بعد الوفاة: دعم، إجراءات، احترام الجثمان"],"fr":{"t":"Fin de vie : 4 soutiens — corps, cœur, souhaits, famille","m":"Corps (douleur, symptômes, confort), cœur (écoute, douceur), souhaits (lieu du décès, spirituel, dignité), famille (décisions, après le décès)","d":["Corps = antalgiques selon le protocole + nausées, dyspnée, fatigue, constipation + position, peau, bouche","Cœur = écouter, parler avec douceur, sécuriser, soutenir la famille","Souhaits = lieu du décès, religieux et rites, dignité","Famille = coordination avec l'équipe, aide aux décisions ; après le décès : soutien, démarches, respect du corps"]}}],"medsurg:coro":[{"t":"قبل القسطرة: «صوم، كلى، مميّع، يود» وبعدها: «15، ممدود، بول»","m":"صوم 6 ساعات، كلى (فحص قبل وبعد 3 أيام)، مميّع (Sintrom / Warfarin + INR)، يود (حساسية)؛ وبعد: علامات حيوية كل 15 دقيقة، الطرف ممدود وثابت، التبوّل","d":["صوم = صايم 6 ساعات على الأقل","كلى = فحص الكلى قبل، ومنعيدو بعد 3 أيام (المادة الملوّنة)","مميّع = وقف Sintrom / Warfarin وقياس INR؛ ودوا السكري 24 ساعة قبل و48 ساعة بعد","يود = التأكد ما في حساسية على اليود + الموافقة الخطّية","بعد: علامات حيوية كل 15 دقيقة بأول ساعة، الطرف ممدود وثابت، التبوّل ومراقبة النزيف"],"fr":{"t":"Avant le cathétérisme : jeûne, reins, anticoagulant, iode ; après : 15, allongé, urines","m":"Jeûne 6 h, reins (bilan avant et 3 jours après), anticoagulant (Sintrom / Warfarine + INR), iode (allergie) ; après : signes vitaux toutes les 15 min, membre allongé et immobile, diurèse","d":["Jeûne = au moins 6 heures","Reins = bilan rénal avant, refait 3 jours après (produit de contraste)","Anticoagulant = arrêt du Sintrom / de la Warfarine et INR ; antidiabétiques 24 h avant et 48 h après","Iode = vérifier l'absence d'allergie + consentement écrit","Après : signes vitaux toutes les 15 min la première heure, membre allongé et immobile, diurèse et surveillance du saignement"]}}],"medsurg:angio":[{"t":"Angioplastie: «البالون بيوسّع، الدعامة بتمسك، والإجر 8 ساعات»","m":"البالون بينفخ ويوسّع الشريان المسدود، الدعامة بتخلّيه مفتوح؛ وبعد الدخول من الفخذ: 8 ساعات بلا حراك بعد نزع الـ désilet (الغمد)","d":["بالون = بينفخ بمكان الانسداد ← تدفّق دم أحسن للقلب","دعامة = أنبوب شبكي بيخلّي الشريان مفتوح (معظمها مغلّفة بدوا)","موانع: انسداد كامل ما بينقطع، ضعف شديد بعضلة القلب، حساسية شديدة من اليود","8 ساعات = راحة بلا حراك بعد نزع الـ désilet + النبض المحيطي والتنميل"],"fr":{"t":"Angioplastie : le ballonnet dilate, le stent tient, la jambe 8 heures","m":"Le ballonnet se gonfle et dilate l'artère bouchée, le stent la garde ouverte ; voie fémorale : 8 heures sans bouger après le retrait du désilet","d":["Ballonnet = gonflé à l'endroit de l'obstruction → meilleur flux vers le cœur","Stent = tube grillagé qui garde l'artère ouverte (souvent recouvert d'un médicament)","Contre-indications : occlusion totale infranchissable, faiblesse sévère du muscle cardiaque, allergie sévère à l'iode","8 heures = repos sans bouger après le retrait du désilet + pouls périphériques et fourmillements"]}}]};
